const ASSETS = {"/index.html":{"type":"text/html; charset=utf-8","body":"<!doctype html>\n<html lang=\"vi\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta http-equiv=\"Cache-Control\" content=\"no-cache, no-store, must-revalidate\">\n  <meta http-equiv=\"Pragma\" content=\"no-cache\">\n  <meta http-equiv=\"Expires\" content=\"0\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n  <meta name=\"theme-color\" content=\"#090b0c\">\n  <meta name=\"color-scheme\" content=\"dark\">\n  <title>Tiền của Điền</title>\n  <link rel=\"manifest\" href=\"./manifest.webmanifest?v=18\">\n  <link rel=\"icon\" href=\"./icon.svg\" type=\"image/svg+xml\">\n<style>\n:root{--bg:#090b0c;--panel:#121517;--field:#0c0f11;--line:#252b2f;--text:#f4f7f8;--muted:#899197;--accent:#00e68a;--bad:#ff6670;--warn:#f2c14e}\n*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;background:var(--bg);overflow:auto}body{font-family:Inter,ui-sans-serif,system-ui,-apple-system,\"Segoe UI\",sans-serif;color:var(--text)}button,input{font:inherit}.app{height:100dvh;min-height:530px;max-width:620px;margin:0 auto;padding:max(12px,env(safe-area-inset-top)) 14px max(12px,env(safe-area-inset-bottom));display:grid;grid-template-rows:auto auto auto minmax(115px,1fr);gap:10px;background:radial-gradient(circle at 90% -10%,rgba(0,230,138,.12),transparent 36%)}header{display:flex;justify-content:space-between;align-items:center;gap:12px}.route{font-size:11px;font-weight:800;letter-spacing:.06em;color:var(--accent)}h1{margin:2px 0 0;font-size:27px;line-height:1;letter-spacing:-.045em}.version{display:inline-block;margin-top:5px;font-size:9px;font-weight:900;letter-spacing:.08em;color:var(--accent);opacity:.8}.install{border:1px solid var(--line);background:var(--panel);color:var(--accent);font-size:11px;font-weight:850;padding:8px 11px;border-radius:10px;cursor:pointer}.hidden{display:none!important}.tabs{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:7px}.tab{height:34px;border:1px solid var(--line);border-radius:10px;background:#101315;color:var(--muted);font-size:12px;font-weight:900;letter-spacing:.04em;cursor:pointer}.tab.active{color:#07110d;background:var(--accent);border-color:var(--accent)}.panel{border:1px solid var(--line);background:linear-gradient(180deg,#15191b,var(--panel));border-radius:17px;padding:12px}.inputs{display:grid;grid-template-columns:1fr 1fr;gap:10px}.inputs label.wide{grid-column:1/-1}.inputs label>span{display:flex;justify-content:space-between;align-items:center;gap:6px;font-size:11px;font-weight:780;color:#c7cdd0;margin:0 2px 5px}.inputs small{font-size:8px;color:var(--muted);font-weight:900;letter-spacing:.07em}.field{height:45px;display:flex;align-items:center;border:1px solid var(--line);background:var(--field);border-radius:12px;overflow:hidden}.field:focus-within{border-color:var(--accent);box-shadow:0 0 0 2px rgba(0,230,138,.08)}.field.rate-highlight{background:linear-gradient(180deg,rgba(0,230,138,.18),rgba(0,230,138,.08));border-color:rgba(0,230,138,.62);box-shadow:inset 0 0 0 1px rgba(0,230,138,.06)}.field.rate-highlight input{color:#f7fffb}.field.rate-highlight b{color:var(--accent)}.field input{width:100%;min-width:0;height:100%;border:0;outline:0;background:transparent;color:var(--text);padding:0 11px;font-size:16px;font-weight:800}.field input::placeholder{color:#535b60;font-size:12px;font-weight:650}.field b{font-size:9px;color:var(--muted);padding:0 10px}.received{display:block;margin:5px 3px 0;color:var(--muted);font-size:10px;line-height:1.15;font-style:normal;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.result-card{min-height:0;border:1px solid #284439;background:linear-gradient(180deg,#142119,#101613);border-radius:18px;padding:14px;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center}.result-card span{font-size:10px;color:var(--muted);font-weight:900;letter-spacing:.12em}.result-card strong{font-size:clamp(30px,8vw,46px);line-height:1.03;margin:8px 0 4px;letter-spacing:-.055em}.result-card b{font-size:16px}.good{color:var(--accent)!important}.bad{color:var(--bad)!important}.neutral{color:var(--warn)!important}\n@media(max-width:390px){.app{padding-left:10px;padding-right:10px;gap:8px}.panel{padding:10px}.inputs{gap:8px}.field{height:41px}.field input{font-size:14px}h1{font-size:23px}.received{font-size:9px;margin-top:4px}.result-card{padding:11px}.result-card strong{font-size:29px}.tab{height:31px;font-size:11px}}\n@media(max-height:690px){.app{gap:7px;padding-top:7px;padding-bottom:7px}.route{font-size:9px}h1{font-size:20px}.tabs{gap:5px}.tab{height:28px;font-size:10px}.panel{padding:8px}.inputs{gap:6px}.inputs label>span{font-size:9px;margin-bottom:3px}.field{height:33px}.field input{font-size:13px}.received{font-size:8px;margin-top:3px}.result-card{padding:8px}.result-card strong{font-size:26px;margin:4px 0 2px}}\n.fx-tools{grid-column:1/-1;border-top:1px solid var(--line);padding-top:9px;min-width:0}\n.fx-controls{display:flex;align-items:center;justify-content:space-between;gap:8px}\n.fx-toggle,.fx-refresh{min-height:32px;border:1px solid var(--line);border-radius:9px;background:var(--field);color:var(--muted);padding:5px 10px;font-size:11px;font-weight:800;cursor:pointer}\n.fx-toggle{display:inline-flex;align-items:center;gap:7px}\n.fx-toggle.enabled{color:var(--accent);border-color:#285d46;background:#11251c}\n.fx-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:currentColor}\n.fx-refresh{color:var(--text)}.fx-refresh:disabled{opacity:.45;cursor:default}\n.fx-tools p{margin:5px 0 0;font-size:9px;line-height:1.4;color:var(--muted);overflow-wrap:anywhere}\n.fx-tools a{color:var(--muted);text-underline-offset:2px}\n.fx-tools .fx-warning{color:var(--warn)}\n.field.auto-rate{border-style:dashed}.field.auto-rate input{cursor:default}\n.rub-note{grid-column:1/-1;margin:0 2px;color:var(--warn);font-size:10px;line-height:1.35}\n.result-note{margin:8px 0 0;font-size:9px;line-height:1.4;color:var(--muted);font-weight:500;letter-spacing:0}\n.usd-reference{display:block;margin:4px 3px 0;font-size:10px;line-height:1.35;font-style:normal;font-weight:650;color:#73c6a3;overflow-wrap:anywhere}\n.usd-reference.stale{color:var(--warn)}\nbutton:focus-visible{outline:2px solid var(--accent);outline-offset:3px}\n@media(max-width:390px){.tabs{gap:5px}.fx-toggle,.fx-refresh{font-size:10px;padding:5px 8px}}\n@media(max-height:690px){.fx-tools{padding-top:6px}.fx-tools p{font-size:8px;margin-top:3px}.fx-toggle,.fx-refresh{min-height:28px;font-size:10px}.rub-note{font-size:9px}.result-note{font-size:8px;margin-top:5px}.usd-reference{font-size:9px;margin-top:3px}}\n\n</style>\n</head>\n<body>\n  <main class=\"app\">\n    <header>\n      <div>\n        <div class=\"route\" id=\"routeText\">VND → USDT → EUR → VND</div>\n        <h1>Tiền của Điền</h1><span class=\"version\">v18 · TỶ GIÁ USD THAM KHẢO</span>\n      </div>\n      <button id=\"installBtn\" class=\"install hidden\">Cài app</button>\n    </header>\n\n    <nav class=\"tabs\" aria-label=\"Loại vòng tiền\">\n      <button type=\"button\" class=\"tab\" data-page=\"cad\">CAD</button>\n      <button type=\"button\" class=\"tab\" data-page=\"try\">TRY</button>\n      <button type=\"button\" class=\"tab active\" data-page=\"vnd\">VND</button>\n      <button type=\"button\" class=\"tab\" data-page=\"jpy\">JPY</button>\n      <button type=\"button\" class=\"tab\" data-page=\"rub\">RUB</button>\n    </nav>\n\n    <section class=\"panel inputs\">\n      <label class=\"wide\">\n        <span>Vốn ban đầu</span>\n        <div class=\"field\"><input aria-label=\"Vốn ban đầu\" id=\"capital\" inputmode=\"numeric\" value=\"100.000.000\"><b id=\"capitalUnit\">VND</b></div>\n      </label>\n\n      <label>\n        <span id=\"rate1Label\">USDT / VND <small>P2P</small></span>\n        <div class=\"field\"><input id=\"rate1\" inputmode=\"decimal\" placeholder=\"Ví dụ 26.300\"><b id=\"rate1Unit\">VND</b></div>\n        <em class=\"received\" id=\"received1\">Nhận: — USDT</em>\n        <em class=\"usd-reference hidden\" id=\"usdReference1\" aria-live=\"polite\"></em>\n      </label>\n\n      <label>\n        <span id=\"rate2Label\">USDT / EUR <small>P2P</small></span>\n        <div class=\"field\"><input id=\"rate2\" inputmode=\"decimal\" placeholder=\"Ví dụ 0,8600\"><b id=\"rate2Unit\">EUR</b></div>\n        <em class=\"received\" id=\"received2\">Nhận: — EUR</em>\n        <em class=\"usd-reference hidden\" id=\"usdReference2\" aria-live=\"polite\"></em>\n      </label>\n\n      <label class=\"wide\">\n        <span id=\"rate3Label\">EUR / VND</span>\n        <div class=\"field\"><input id=\"rate3\" inputmode=\"decimal\" placeholder=\"Ví dụ 30.700\"><b id=\"rate3Unit\">VND</b></div>\n        <em class=\"received\" id=\"received3\">Nhận: — VND</em>\n        <em class=\"usd-reference hidden\" id=\"usdReference3\" aria-live=\"polite\"></em>\n      </label>\n\n      <p id=\"rubNote\" class=\"rub-note hidden\">Bước USD/RUB quy ước 1 USDT = 1 USD. Giá mua USDT thực tế có thể khác.</p>\n      <div class=\"fx-tools\">\n        <div class=\"fx-controls\">\n          <button type=\"button\" id=\"fxAuto\" class=\"fx-toggle enabled\" role=\"switch\" aria-checked=\"true\" aria-label=\"Tự động điền các ô tỷ giá pháp định\"><i class=\"fx-dot\" aria-hidden=\"true\"></i><span id=\"fxAutoText\">Tự điền: Bật</span></button>\n          <button type=\"button\" id=\"fxRefresh\" class=\"fx-refresh\">Cập nhật</button>\n        </div>\n        <p id=\"fxStatus\" role=\"status\" aria-live=\"polite\">Đang lấy tỷ giá pháp định…</p>\n        <p><a href=\"https://www.exchangerate-api.com\" target=\"_blank\" rel=\"noopener noreferrer\">Rates By Exchange Rate API</a> · Tham khảo, cập nhật hằng ngày.</p>\n      </div>\n    </section>\n\n    <section class=\"result-card\">\n      <span>LÃI / LỖ</span>\n      <strong id=\"profit\">—</strong>\n      <b id=\"roi\">—</b>\n      <p id=\"resultNote\" class=\"result-note\">Ước tính · chưa trừ phí giao dịch</p>\n    </section>\n  </main>\n\n\n\n<script>\n'use strict';\nconst $ = id => document.getElementById(id);\nconst fmt0 = new Intl.NumberFormat('vi-VN', {maximumFractionDigits: 0});\nconst fmt2 = new Intl.NumberFormat('vi-VN', {maximumFractionDigits: 2});\nconst fmt4 = new Intl.NumberFormat('vi-VN', {maximumFractionDigits: 4});\nconst fmtRate = new Intl.NumberFormat('vi-VN', {useGrouping: false, maximumFractionDigits: 6});\nconst memoryStorage = new Map();\nfunction stored(name) {\n  try { return localStorage.getItem(name) ?? memoryStorage.get(name) ?? null; }\n  catch (_) { return memoryStorage.get(name) ?? null; }\n}\nfunction remember(name, value) {\n  memoryStorage.set(name, String(value));\n  try { localStorage.setItem(name, String(value)); } catch (_) {}\n}\n\n// A/B always means the amount of B for ONE unit of A.\n// Only explicit fiat pairs have an fx property. USDT is never fetched or\n// inferred from the provider's USD rate, except the disclosed RUB convention.\nconst PAGES = {\n  cad: {\n    route: 'CAD → EUR → USDT → CAD', capital: 'CAD', highlight: 0,\n    rates: [\n      {label: 'EUR / CAD', unit: 'CAD', placeholder: 'Ví dụ 1,5500', receive: 'EUR', op: 'divide', fx: ['EUR', 'CAD']},\n      {label: 'USDT / EUR', tag: 'P2P', unit: 'EUR', placeholder: 'Ví dụ 0,8900', receive: 'USDT', op: 'divide'},\n      {label: 'USDT / CAD', tag: 'P2P', unit: 'CAD', placeholder: 'Ví dụ 1,3900', receive: 'CAD', op: 'multiply'}\n    ]\n  },\n  try: {\n    route: 'TRY → EUR → USDT → TRY', capital: 'TRY', highlight: 3,\n    rates: [\n      {label: 'EUR / TRY', unit: 'TRY', placeholder: 'Ví dụ 48,50', receive: 'EUR', op: 'divide', fx: ['EUR', 'TRY']},\n      {label: 'USDT / EUR', tag: 'P2P', unit: 'EUR', placeholder: 'Ví dụ 0,8550', receive: 'USDT', op: 'divide'},\n      {label: 'USDT / TRY', tag: 'P2P', unit: 'TRY', placeholder: 'Ví dụ 41,50', receive: 'TRY', op: 'multiply'}\n    ]\n  },\n  vnd: {\n    route: 'VND → USDT → EUR → VND', capital: 'VND', highlight: 1,\n    rates: [\n      {label: 'USDT / VND', tag: 'P2P', unit: 'VND', placeholder: 'Ví dụ 26.300', receive: 'USDT', op: 'divide', vndThousands: true},\n      {label: 'USDT / EUR', tag: 'P2P', unit: 'EUR', placeholder: 'Ví dụ 0,8600', receive: 'EUR', op: 'multiply'},\n      {label: 'EUR / VND', unit: 'VND', placeholder: 'Ví dụ 30.700', receive: 'VND', op: 'multiply', vndThousands: true, fx: ['EUR', 'VND']}\n    ]\n  },\n  jpy: {\n    route: 'VND → JPY → USDT → VND', capital: 'VND', highlight: 2,\n    rates: [\n      {label: 'JPY / VND', unit: 'VND', placeholder: 'Ví dụ 165,50', receive: 'JPY', op: 'divide', fx: ['JPY', 'VND']},\n      {label: 'USDT / JPY', tag: 'P2P', unit: 'JPY', placeholder: 'Ví dụ 155,00', receive: 'USDT', op: 'divide'},\n      {label: 'USDT / VND', tag: 'P2P', unit: 'VND', placeholder: 'Ví dụ 26.300', receive: 'VND', op: 'multiply', vndThousands: true}\n    ]\n  },\n  rub: {\n    route: 'VND → RUB → USDT → VND', capital: 'VND', highlight: 3,\n    rates: [\n      {label: 'RUB / VND', unit: 'VND', placeholder: 'Ví dụ 310,50', receive: 'RUB', op: 'divide', fx: ['RUB', 'VND']},\n      {label: 'USD / RUB', unit: 'RUB', placeholder: 'Ví dụ 83,50', receive: 'USDT', op: 'divide', fx: ['USD', 'RUB']},\n      {label: 'USDT / VND', tag: 'P2P', unit: 'VND', placeholder: 'Ví dụ 26.300', receive: 'VND', op: 'multiply', vndThousands: true}\n    ]\n  }\n};\n\nfunction migrateVndTab() {\n  const legacy = {capital: 'tiendien_capitalVnd', rate1: 'tiendien_usdtVnd', rate2: 'tiendien_usdtEur', rate3: 'tiendien_eurVnd'};\n  for (const id of ['capital', 'rate1', 'rate2', 'rate3']) {\n    const target = `tiendien_vnd_${id}`;\n    const value = stored(`tiendien_eur_${id}`) ?? stored(legacy[id]);\n    if (stored(target) === null && value !== null) remember(target, value);\n  }\n}\nmigrateVndTab();\n// CAD now has a different starting currency and different quote positions.\n// Keep its new inputs separate so VND capital / unrelated old quotes cannot\n// acquire a new currency label. Only the unchanged USDT/CAD quote migrates.\nconst oldUsdtCad = stored('tiendien_cad_rate2');\nif (stored('tiendien_cad_eur_usdt_rate3') === null && oldUsdtCad !== null) {\n  remember('tiendien_cad_eur_usdt_rate3', oldUsdtCad);\n}\nlet page = stored('tiendien_page');\nif (page === 'eur' || !PAGES[page]) page = 'vnd';\n\nfunction capitalNum(value) {\n  const number = Number(String(value ?? '').replace(/\\D/g, ''));\n  return Number.isFinite(number) ? number : 0;\n}\nfunction rateNum(value, thousands = false) {\n  let text = String(value ?? '').trim().replace(/\\s/g, '');\n  if (!text) return 0;\n  if (text.includes(',')) text = text.replace(/\\./g, '').replace(',', '.');\n  else if (thousands && /^\\d{1,3}(?:\\.\\d{3})+$/.test(text)) text = text.replace(/\\./g, '');\n  const number = Number(text);\n  return Number.isFinite(number) ? number : 0;\n}\nfunction formatCapital() {\n  const digits = $('capital').value.replace(/\\D/g, '');\n  $('capital').value = digits ? fmt0.format(capitalNum(digits)) : '';\n}\nfunction money(value, unit) { return `${value >= 0 ? '+' : '−'}${(unit === 'CAD' ? fmt2 : fmt0).format(Math.abs(value))} ${unit}`; }\nfunction pct(value) { return `${value >= 0 ? '+' : ''}${fmt2.format(value)}%`; }\nfunction tone(element, value) {\n  element.classList.remove('good', 'bad', 'neutral');\n  element.classList.add(value > 0.01 ? 'good' : value < -0.01 ? 'bad' : 'neutral');\n}\nfunction formatReceived(value, unit) {\n  if (!(value > 0 && Number.isFinite(value))) return `Nhận: — ${unit}`;\n  return `Nhận: ${(unit === 'VND' || unit === 'TRY' ? fmt2 : fmt4).format(value)} ${unit}`;\n}\nfunction key(name) { return `tiendien_${page === 'cad' ? 'cad_eur_usdt' : page}_${name}`; }\nfunction save() {\n  remember(key('capital'), $('capital').value);\n  PAGES[page].rates.forEach((rate, index) => {\n    // Keep the last manually entered fiat quote separate from the live cache.\n    if (!fxEnabled || !rate.fx) remember(key(`rate${index + 1}`), $(`rate${index + 1}`).value);\n  });\n}\n\nconst FX_URL = 'https://open.er-api.com/v6/latest/USD';\nconst FX_CACHE_KEY = 'tiendien_fx_usd_v16';\nconst FX_AUTO_KEY = 'tiendien_fx_auto_v16';\nconst FX_ATTEMPT_KEY = 'tiendien_fx_attempt_v16';\nconst FX_CODES = ['USD', 'EUR', 'CAD', 'TRY', 'JPY', 'VND', 'RUB'];\nlet fxEnabled = stored(FX_AUTO_KEY) !== '0';\nlet fxError = '';\nlet fxBusy = false;\nlet fxRequest = null;\nlet fxLastAttempt = Number(stored(FX_ATTEMPT_KEY)) || 0;\n\nfunction validateFx(payload) {\n  if (!payload || payload.result !== 'success' || payload.base_code !== 'USD' || !payload.rates) throw new Error('Invalid FX data');\n  for (const code of FX_CODES) {\n    const rate = payload.rates[code];\n    if (typeof rate !== 'number' || !Number.isFinite(rate) || rate <= 0) throw new Error('Invalid FX rate');\n  }\n  if (Math.abs(payload.rates.USD - 1) > 0.000001) throw new Error('Invalid FX base');\n  const last = payload.time_last_update_unix;\n  const next = payload.time_next_update_unix;\n  if (!Number.isFinite(last) || !Number.isFinite(next) || last <= 0 || next <= last || last * 1000 > Date.now() + 300000) throw new Error('Invalid FX timestamp');\n  return payload;\n}\nfunction readFxCache() {\n  try {\n    const cached = JSON.parse(stored(FX_CACHE_KEY) || 'null');\n    if (!cached || !Number.isFinite(cached.fetchedAt) || cached.fetchedAt <= 0 || cached.fetchedAt > Date.now() + 300000) return null;\n    validateFx(cached.payload);\n    return cached;\n  } catch (_) { return null; }\n}\nlet fxSnapshot = readFxCache();\nfunction fxIsDue() {\n  return !fxSnapshot || Date.now() >= fxSnapshot.payload.time_next_update_unix * 1000 + 60000;\n}\nfunction crossRate(base, quote) {\n  if (!fxSnapshot) return 0;\n  return fxSnapshot.payload.rates[quote] / fxSnapshot.payload.rates[base];\n}\nfunction renderUsdReferences() {\n  // Benchmarks are read-only display data. Never substitute them for P2P\n  // USDT inputs or use them in the route's received/profit calculations.\n  PAGES[page].rates.forEach((rate, index) => {\n    const reference = $(`usdReference${index + 1}`);\n    const pair = rate.label.split('/').map(code => code.trim());\n    const hasUsdt = pair.includes('USDT');\n    reference.classList.toggle('hidden', !hasUsdt);\n    reference.classList.toggle('stale', hasUsdt && Boolean(fxSnapshot) && (fxIsDue() || Boolean(fxError)));\n    if (!hasUsdt) {\n      reference.textContent = '';\n      reference.setAttribute('title', '');\n      return;\n    }\n    const currency = pair.find(code => code !== 'USDT');\n    const label = `USD / ${currency}`;\n    if (fxSnapshot) {\n      const value = crossRate('USD', currency);\n      const qualifier = fxError ? ' · giá lưu' : fxIsDue() ? ' · giá cũ' : '';\n      reference.textContent = `${label}: ${fmt4.format(value)}${qualifier}`;\n      const timestamp = new Date(fxSnapshot.payload.time_last_update_unix * 1000).toLocaleString('vi-VN', {timeZone: 'Asia/Ho_Chi_Minh'});\n      reference.setAttribute('title', `1 USD = ${fmt4.format(value)} ${currency}. Tỷ giá tham khảo từ ExchangeRate-API, lúc ${timestamp} (giờ VN).`);\n    } else {\n      reference.textContent = `${label}: ${fxBusy ? 'đang tải…' : fxError ? 'chưa tải được' : '—'}`;\n      reference.setAttribute('title', 'Chưa có dữ liệu tỷ giá pháp định; không suy ra từ giá USDT nhập tay.');\n    }\n  });\n}\nfunction applyFxToPage() {\n  if (!fxEnabled || !fxSnapshot) return;\n  PAGES[page].rates.forEach((rate, index) => {\n    if (!rate.fx) return;\n    const value = crossRate(...rate.fx);\n    const input = $(`rate${index + 1}`);\n    input.value = fmtRate.format(value);\n    input.dataset.fxSource = 'api';\n  });\n}\nfunction renderFxStatus() {\n  $('fxAuto').setAttribute('aria-checked', String(fxEnabled));\n  $('fxAuto').classList.toggle('enabled', fxEnabled);\n  $('fxAutoText').textContent = `Tự điền: ${fxEnabled ? 'Bật' : 'Tắt'}`;\n  $('fxRefresh').disabled = fxBusy;\n  $('fxRefresh').textContent = fxBusy ? 'Đang tải…' : 'Cập nhật';\n  $('fxStatus').classList.toggle('fx-warning', Boolean(fxError) || (fxIsDue() && Boolean(fxSnapshot)));\n  const manualPrefix = fxEnabled ? '' : 'Ô giá nhập tay. ';\n  if (fxSnapshot) {\n    const date = new Intl.DateTimeFormat('vi-VN', {dateStyle: 'short', timeStyle: 'short', timeZone: 'Asia/Ho_Chi_Minh'}).format(new Date(fxSnapshot.payload.time_last_update_unix * 1000));\n    const prefix = fxError ? `${fxError} · đang dùng giá lưu lúc ` : fxIsDue() ? 'Giá cũ từ ' : 'Tỷ giá lúc ';\n    $('fxStatus').textContent = `${manualPrefix}${prefix}${date} (giờ VN). USDT nhập tay.`;\n  } else if (fxError) {\n    $('fxStatus').textContent = `${manualPrefix}${fxError}. ${fxEnabled ? 'Tắt Tự điền để nhập tay.' : 'USD tham khảo chưa có dữ liệu.'}`;\n  } else {\n    $('fxStatus').textContent = manualPrefix + (fxBusy ? 'Đang lấy tỷ giá pháp định… USDT nhập tay.' : 'Chưa có tỷ giá tự động. USDT nhập tay.');\n  }\n  PAGES[page].rates.forEach((rate, index) => {\n    const input = $(`rate${index + 1}`);\n    const automatic = Boolean(rate.fx && fxEnabled);\n    input.readOnly = automatic;\n    input.setAttribute('aria-readonly', String(automatic));\n    const tag = rate.fx ? (automatic ? (fxSnapshot ? 'TỰ ĐỘNG' : input.value ? 'ĐÃ LƯU' : 'CHỜ GIÁ') : 'NHẬP TAY') : rate.tag;\n    $(`rate${index + 1}Label`).innerHTML = `${rate.label}${tag ? ` <small>${tag}</small>` : ''}`;\n    input.closest('.field').classList.toggle('auto-rate', automatic);\n  });\n  $('resultNote').textContent = fxEnabled ? 'Ước tính theo tỷ giá tham khảo · chưa trừ phí' : 'Ước tính · chưa trừ phí giao dịch';\n  renderUsdReferences();\n}\n\nasync function refreshFx({force = false} = {}) {\n  // The feed also powers USD reference lines while auto-fill is disabled.\n  if (fxRequest) return fxRequest;\n  if (!force && !fxIsDue()) { renderFxStatus(); return; }\n  const elapsed = Date.now() - fxLastAttempt;\n  // One scheduled attempt every five minutes when offline/unavailable; manual\n  // refresh is limited to once a minute. A fresh daily snapshot needs no poll.\n  if (elapsed >= 0 && elapsed < (force ? 60000 : 300000)) { renderFxStatus(); return; }\n  fxLastAttempt = Date.now();\n  remember(FX_ATTEMPT_KEY, fxLastAttempt);\n  fxBusy = true;\n  renderFxStatus();\n  fxRequest = (async () => {\n    const controller = new AbortController();\n    const timeout = setTimeout(() => controller.abort(), 10000);\n    try {\n      const response = await fetch(FX_URL, {cache: 'no-store', credentials: 'omit', signal: controller.signal});\n      if (!response.ok) throw new Error(response.status === 429 ? 'RATE_LIMIT' : 'FETCH_FAILED');\n      const payload = validateFx(await response.json());\n      if (fxSnapshot && payload.time_last_update_unix < fxSnapshot.payload.time_last_update_unix) throw new Error('Older FX response');\n      fxSnapshot = {payload, fetchedAt: Date.now()};\n      remember(FX_CACHE_KEY, JSON.stringify(fxSnapshot));\n      fxError = '';\n      // The user may have switched tabs or disabled auto while fetch awaited.\n      if (fxEnabled) { applyFxToPage(); calculate(); }\n    } catch (error) {\n      fxError = error.message === 'RATE_LIMIT' ? 'Nguồn đang giới hạn truy cập' : 'Không tải được tỷ giá';\n    } finally {\n      clearTimeout(timeout);\n      fxBusy = false;\n      fxRequest = null;\n      renderFxStatus();\n    }\n  })();\n  return fxRequest;\n}\n\nfunction restorePage() {\n  $('capital').value = stored(key('capital')) ?? (page === 'cad' ? '10.000' : page === 'try' ? '100.000' : '100.000.000');\n  ['rate1', 'rate2', 'rate3'].forEach(id => {\n    $(id).value = stored(key(id)) ?? '';\n    delete $(id).dataset.fxSource;\n  });\n  formatCapital();\n}\nfunction renderPage() {\n  const config = PAGES[page];\n  $('routeText').textContent = config.route;\n  $('capitalUnit').textContent = config.capital;\n  config.rates.forEach((rate, index) => {\n    const input = $(`rate${index + 1}`);\n    $(`rate${index + 1}Unit`).textContent = rate.unit;\n    input.placeholder = rate.placeholder;\n    input.setAttribute('aria-label', `${rate.label}: số ${rate.unit} cho một ${rate.label.split(' / ')[0]}`);\n    input.closest('.field').classList.toggle('rate-highlight', index + 1 === config.highlight);\n  });\n  document.querySelectorAll('.tab').forEach(button => {\n    const active = button.dataset.page === page;\n    button.classList.toggle('active', active);\n    button.setAttribute('aria-pressed', String(active));\n  });\n  $('rubNote').classList.toggle('hidden', page !== 'rub');\n  remember('tiendien_page', page);\n  restorePage();\n  applyFxToPage();\n  renderFxStatus();\n  calculate();\n}\nfunction calculate() {\n  const config = PAGES[page];\n  const capital = capitalNum($('capital').value);\n  let amount = capital;\n  config.rates.forEach((rate, index) => {\n    const quote = rateNum($(`rate${index + 1}`).value, Boolean(rate.vndThousands));\n    amount = amount > 0 && quote > 0 ? (rate.op === 'divide' ? amount / quote : amount * quote) : 0;\n    if (!Number.isFinite(amount)) amount = 0;\n    $(`received${index + 1}`).textContent = formatReceived(amount, rate.receive);\n  });\n  if (!(capital > 0 && amount > 0)) {\n    $('profit').textContent = '—'; $('roi').textContent = '—';\n    $('profit').className = ''; $('roi').className = '';\n  } else {\n    const profit = amount - capital;\n    const roi = profit / capital * 100;\n    if (Number.isFinite(profit) && Number.isFinite(roi)) {\n      $('profit').textContent = money(profit, config.capital);\n      $('roi').textContent = pct(roi);\n      tone($('profit'), profit); tone($('roi'), profit);\n    } else {\n      $('profit').textContent = '—'; $('roi').textContent = '—';\n      $('profit').className = ''; $('roi').className = '';\n    }\n  }\n  save();\n}\n\n$('capital').addEventListener('input', () => { formatCapital(); calculate(); });\n['rate1', 'rate2', 'rate3'].forEach(id => $(id).addEventListener('input', calculate));\ndocument.querySelectorAll('.tab').forEach(button => button.addEventListener('click', () => {\n  save(); page = button.dataset.page; renderPage(); refreshFx();\n}));\n$('fxAuto').addEventListener('click', () => {\n  save();\n  fxEnabled = !fxEnabled;\n  remember(FX_AUTO_KEY, fxEnabled ? '1' : '0');\n  if (fxEnabled) applyFxToPage();\n  else {\n    PAGES[page].rates.forEach((rate, index) => {\n      if (!rate.fx) return;\n      const manual = stored(key(`rate${index + 1}`));\n      if (manual !== null) $(`rate${index + 1}`).value = manual;\n      delete $(`rate${index + 1}`).dataset.fxSource;\n    });\n  }\n  renderFxStatus(); calculate();\n  if (fxEnabled) refreshFx();\n});\n$('fxRefresh').addEventListener('click', () => refreshFx({force: true}));\nwindow.addEventListener('online', () => refreshFx());\ndocument.addEventListener('visibilitychange', () => { if (!document.hidden) refreshFx(); });\nsetInterval(() => { if (!document.hidden) refreshFx(); }, 60000);\n\nlet deferredPrompt = null;\nwindow.addEventListener('beforeinstallprompt', event => {\n  event.preventDefault(); deferredPrompt = event; $('installBtn').classList.remove('hidden');\n});\n$('installBtn').addEventListener('click', async () => {\n  if (!deferredPrompt) return;\n  deferredPrompt.prompt(); await deferredPrompt.userChoice;\n  deferredPrompt = null; $('installBtn').classList.add('hidden');\n});\n\n// Retire this app's old cache without touching other apps on the same origin.\n(async () => {\n  try {\n    if ('serviceWorker' in navigator) {\n      const scope = new URL('./', location.href).href;\n      const registrations = await navigator.serviceWorker.getRegistrations();\n      for (const registration of registrations) if (registration.scope === scope) await registration.unregister();\n    }\n    if ('caches' in window) {\n      for (const name of await caches.keys()) if (/^(tien-cua-dien|tiendien)[-_]/.test(name)) await caches.delete(name);\n    }\n  } catch (_) {}\n})();\nrenderPage();\nrefreshFx();\n\n</script>\n</body>\n</html>\n"},"/v18.html":{"type":"text/html; charset=utf-8","body":"<!doctype html>\n<html lang=\"vi\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta http-equiv=\"Cache-Control\" content=\"no-cache, no-store, must-revalidate\">\n  <meta http-equiv=\"Pragma\" content=\"no-cache\">\n  <meta http-equiv=\"Expires\" content=\"0\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n  <meta name=\"theme-color\" content=\"#090b0c\">\n  <meta name=\"color-scheme\" content=\"dark\">\n  <title>Tiền của Điền</title>\n  <link rel=\"manifest\" href=\"./manifest.webmanifest?v=18\">\n  <link rel=\"icon\" href=\"./icon.svg\" type=\"image/svg+xml\">\n<style>\n:root{--bg:#090b0c;--panel:#121517;--field:#0c0f11;--line:#252b2f;--text:#f4f7f8;--muted:#899197;--accent:#00e68a;--bad:#ff6670;--warn:#f2c14e}\n*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;background:var(--bg);overflow:auto}body{font-family:Inter,ui-sans-serif,system-ui,-apple-system,\"Segoe UI\",sans-serif;color:var(--text)}button,input{font:inherit}.app{height:100dvh;min-height:530px;max-width:620px;margin:0 auto;padding:max(12px,env(safe-area-inset-top)) 14px max(12px,env(safe-area-inset-bottom));display:grid;grid-template-rows:auto auto auto minmax(115px,1fr);gap:10px;background:radial-gradient(circle at 90% -10%,rgba(0,230,138,.12),transparent 36%)}header{display:flex;justify-content:space-between;align-items:center;gap:12px}.route{font-size:11px;font-weight:800;letter-spacing:.06em;color:var(--accent)}h1{margin:2px 0 0;font-size:27px;line-height:1;letter-spacing:-.045em}.version{display:inline-block;margin-top:5px;font-size:9px;font-weight:900;letter-spacing:.08em;color:var(--accent);opacity:.8}.install{border:1px solid var(--line);background:var(--panel);color:var(--accent);font-size:11px;font-weight:850;padding:8px 11px;border-radius:10px;cursor:pointer}.hidden{display:none!important}.tabs{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:7px}.tab{height:34px;border:1px solid var(--line);border-radius:10px;background:#101315;color:var(--muted);font-size:12px;font-weight:900;letter-spacing:.04em;cursor:pointer}.tab.active{color:#07110d;background:var(--accent);border-color:var(--accent)}.panel{border:1px solid var(--line);background:linear-gradient(180deg,#15191b,var(--panel));border-radius:17px;padding:12px}.inputs{display:grid;grid-template-columns:1fr 1fr;gap:10px}.inputs label.wide{grid-column:1/-1}.inputs label>span{display:flex;justify-content:space-between;align-items:center;gap:6px;font-size:11px;font-weight:780;color:#c7cdd0;margin:0 2px 5px}.inputs small{font-size:8px;color:var(--muted);font-weight:900;letter-spacing:.07em}.field{height:45px;display:flex;align-items:center;border:1px solid var(--line);background:var(--field);border-radius:12px;overflow:hidden}.field:focus-within{border-color:var(--accent);box-shadow:0 0 0 2px rgba(0,230,138,.08)}.field.rate-highlight{background:linear-gradient(180deg,rgba(0,230,138,.18),rgba(0,230,138,.08));border-color:rgba(0,230,138,.62);box-shadow:inset 0 0 0 1px rgba(0,230,138,.06)}.field.rate-highlight input{color:#f7fffb}.field.rate-highlight b{color:var(--accent)}.field input{width:100%;min-width:0;height:100%;border:0;outline:0;background:transparent;color:var(--text);padding:0 11px;font-size:16px;font-weight:800}.field input::placeholder{color:#535b60;font-size:12px;font-weight:650}.field b{font-size:9px;color:var(--muted);padding:0 10px}.received{display:block;margin:5px 3px 0;color:var(--muted);font-size:10px;line-height:1.15;font-style:normal;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.result-card{min-height:0;border:1px solid #284439;background:linear-gradient(180deg,#142119,#101613);border-radius:18px;padding:14px;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center}.result-card span{font-size:10px;color:var(--muted);font-weight:900;letter-spacing:.12em}.result-card strong{font-size:clamp(30px,8vw,46px);line-height:1.03;margin:8px 0 4px;letter-spacing:-.055em}.result-card b{font-size:16px}.good{color:var(--accent)!important}.bad{color:var(--bad)!important}.neutral{color:var(--warn)!important}\n@media(max-width:390px){.app{padding-left:10px;padding-right:10px;gap:8px}.panel{padding:10px}.inputs{gap:8px}.field{height:41px}.field input{font-size:14px}h1{font-size:23px}.received{font-size:9px;margin-top:4px}.result-card{padding:11px}.result-card strong{font-size:29px}.tab{height:31px;font-size:11px}}\n@media(max-height:690px){.app{gap:7px;padding-top:7px;padding-bottom:7px}.route{font-size:9px}h1{font-size:20px}.tabs{gap:5px}.tab{height:28px;font-size:10px}.panel{padding:8px}.inputs{gap:6px}.inputs label>span{font-size:9px;margin-bottom:3px}.field{height:33px}.field input{font-size:13px}.received{font-size:8px;margin-top:3px}.result-card{padding:8px}.result-card strong{font-size:26px;margin:4px 0 2px}}\n.fx-tools{grid-column:1/-1;border-top:1px solid var(--line);padding-top:9px;min-width:0}\n.fx-controls{display:flex;align-items:center;justify-content:space-between;gap:8px}\n.fx-toggle,.fx-refresh{min-height:32px;border:1px solid var(--line);border-radius:9px;background:var(--field);color:var(--muted);padding:5px 10px;font-size:11px;font-weight:800;cursor:pointer}\n.fx-toggle{display:inline-flex;align-items:center;gap:7px}\n.fx-toggle.enabled{color:var(--accent);border-color:#285d46;background:#11251c}\n.fx-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:currentColor}\n.fx-refresh{color:var(--text)}.fx-refresh:disabled{opacity:.45;cursor:default}\n.fx-tools p{margin:5px 0 0;font-size:9px;line-height:1.4;color:var(--muted);overflow-wrap:anywhere}\n.fx-tools a{color:var(--muted);text-underline-offset:2px}\n.fx-tools .fx-warning{color:var(--warn)}\n.field.auto-rate{border-style:dashed}.field.auto-rate input{cursor:default}\n.rub-note{grid-column:1/-1;margin:0 2px;color:var(--warn);font-size:10px;line-height:1.35}\n.result-note{margin:8px 0 0;font-size:9px;line-height:1.4;color:var(--muted);font-weight:500;letter-spacing:0}\n.usd-reference{display:block;margin:4px 3px 0;font-size:10px;line-height:1.35;font-style:normal;font-weight:650;color:#73c6a3;overflow-wrap:anywhere}\n.usd-reference.stale{color:var(--warn)}\nbutton:focus-visible{outline:2px solid var(--accent);outline-offset:3px}\n@media(max-width:390px){.tabs{gap:5px}.fx-toggle,.fx-refresh{font-size:10px;padding:5px 8px}}\n@media(max-height:690px){.fx-tools{padding-top:6px}.fx-tools p{font-size:8px;margin-top:3px}.fx-toggle,.fx-refresh{min-height:28px;font-size:10px}.rub-note{font-size:9px}.result-note{font-size:8px;margin-top:5px}.usd-reference{font-size:9px;margin-top:3px}}\n\n</style>\n</head>\n<body>\n  <main class=\"app\">\n    <header>\n      <div>\n        <div class=\"route\" id=\"routeText\">VND → USDT → EUR → VND</div>\n        <h1>Tiền của Điền</h1><span class=\"version\">v18 · TỶ GIÁ USD THAM KHẢO</span>\n      </div>\n      <button id=\"installBtn\" class=\"install hidden\">Cài app</button>\n    </header>\n\n    <nav class=\"tabs\" aria-label=\"Loại vòng tiền\">\n      <button type=\"button\" class=\"tab\" data-page=\"cad\">CAD</button>\n      <button type=\"button\" class=\"tab\" data-page=\"try\">TRY</button>\n      <button type=\"button\" class=\"tab active\" data-page=\"vnd\">VND</button>\n      <button type=\"button\" class=\"tab\" data-page=\"jpy\">JPY</button>\n      <button type=\"button\" class=\"tab\" data-page=\"rub\">RUB</button>\n    </nav>\n\n    <section class=\"panel inputs\">\n      <label class=\"wide\">\n        <span>Vốn ban đầu</span>\n        <div class=\"field\"><input aria-label=\"Vốn ban đầu\" id=\"capital\" inputmode=\"numeric\" value=\"100.000.000\"><b id=\"capitalUnit\">VND</b></div>\n      </label>\n\n      <label>\n        <span id=\"rate1Label\">USDT / VND <small>P2P</small></span>\n        <div class=\"field\"><input id=\"rate1\" inputmode=\"decimal\" placeholder=\"Ví dụ 26.300\"><b id=\"rate1Unit\">VND</b></div>\n        <em class=\"received\" id=\"received1\">Nhận: — USDT</em>\n        <em class=\"usd-reference hidden\" id=\"usdReference1\" aria-live=\"polite\"></em>\n      </label>\n\n      <label>\n        <span id=\"rate2Label\">USDT / EUR <small>P2P</small></span>\n        <div class=\"field\"><input id=\"rate2\" inputmode=\"decimal\" placeholder=\"Ví dụ 0,8600\"><b id=\"rate2Unit\">EUR</b></div>\n        <em class=\"received\" id=\"received2\">Nhận: — EUR</em>\n        <em class=\"usd-reference hidden\" id=\"usdReference2\" aria-live=\"polite\"></em>\n      </label>\n\n      <label class=\"wide\">\n        <span id=\"rate3Label\">EUR / VND</span>\n        <div class=\"field\"><input id=\"rate3\" inputmode=\"decimal\" placeholder=\"Ví dụ 30.700\"><b id=\"rate3Unit\">VND</b></div>\n        <em class=\"received\" id=\"received3\">Nhận: — VND</em>\n        <em class=\"usd-reference hidden\" id=\"usdReference3\" aria-live=\"polite\"></em>\n      </label>\n\n      <p id=\"rubNote\" class=\"rub-note hidden\">Bước USD/RUB quy ước 1 USDT = 1 USD. Giá mua USDT thực tế có thể khác.</p>\n      <div class=\"fx-tools\">\n        <div class=\"fx-controls\">\n          <button type=\"button\" id=\"fxAuto\" class=\"fx-toggle enabled\" role=\"switch\" aria-checked=\"true\" aria-label=\"Tự động điền các ô tỷ giá pháp định\"><i class=\"fx-dot\" aria-hidden=\"true\"></i><span id=\"fxAutoText\">Tự điền: Bật</span></button>\n          <button type=\"button\" id=\"fxRefresh\" class=\"fx-refresh\">Cập nhật</button>\n        </div>\n        <p id=\"fxStatus\" role=\"status\" aria-live=\"polite\">Đang lấy tỷ giá pháp định…</p>\n        <p><a href=\"https://www.exchangerate-api.com\" target=\"_blank\" rel=\"noopener noreferrer\">Rates By Exchange Rate API</a> · Tham khảo, cập nhật hằng ngày.</p>\n      </div>\n    </section>\n\n    <section class=\"result-card\">\n      <span>LÃI / LỖ</span>\n      <strong id=\"profit\">—</strong>\n      <b id=\"roi\">—</b>\n      <p id=\"resultNote\" class=\"result-note\">Ước tính · chưa trừ phí giao dịch</p>\n    </section>\n  </main>\n\n\n\n<script>\n'use strict';\nconst $ = id => document.getElementById(id);\nconst fmt0 = new Intl.NumberFormat('vi-VN', {maximumFractionDigits: 0});\nconst fmt2 = new Intl.NumberFormat('vi-VN', {maximumFractionDigits: 2});\nconst fmt4 = new Intl.NumberFormat('vi-VN', {maximumFractionDigits: 4});\nconst fmtRate = new Intl.NumberFormat('vi-VN', {useGrouping: false, maximumFractionDigits: 6});\nconst memoryStorage = new Map();\nfunction stored(name) {\n  try { return localStorage.getItem(name) ?? memoryStorage.get(name) ?? null; }\n  catch (_) { return memoryStorage.get(name) ?? null; }\n}\nfunction remember(name, value) {\n  memoryStorage.set(name, String(value));\n  try { localStorage.setItem(name, String(value)); } catch (_) {}\n}\n\n// A/B always means the amount of B for ONE unit of A.\n// Only explicit fiat pairs have an fx property. USDT is never fetched or\n// inferred from the provider's USD rate, except the disclosed RUB convention.\nconst PAGES = {\n  cad: {\n    route: 'CAD → EUR → USDT → CAD', capital: 'CAD', highlight: 0,\n    rates: [\n      {label: 'EUR / CAD', unit: 'CAD', placeholder: 'Ví dụ 1,5500', receive: 'EUR', op: 'divide', fx: ['EUR', 'CAD']},\n      {label: 'USDT / EUR', tag: 'P2P', unit: 'EUR', placeholder: 'Ví dụ 0,8900', receive: 'USDT', op: 'divide'},\n      {label: 'USDT / CAD', tag: 'P2P', unit: 'CAD', placeholder: 'Ví dụ 1,3900', receive: 'CAD', op: 'multiply'}\n    ]\n  },\n  try: {\n    route: 'TRY → EUR → USDT → TRY', capital: 'TRY', highlight: 3,\n    rates: [\n      {label: 'EUR / TRY', unit: 'TRY', placeholder: 'Ví dụ 48,50', receive: 'EUR', op: 'divide', fx: ['EUR', 'TRY']},\n      {label: 'USDT / EUR', tag: 'P2P', unit: 'EUR', placeholder: 'Ví dụ 0,8550', receive: 'USDT', op: 'divide'},\n      {label: 'USDT / TRY', tag: 'P2P', unit: 'TRY', placeholder: 'Ví dụ 41,50', receive: 'TRY', op: 'multiply'}\n    ]\n  },\n  vnd: {\n    route: 'VND → USDT → EUR → VND', capital: 'VND', highlight: 1,\n    rates: [\n      {label: 'USDT / VND', tag: 'P2P', unit: 'VND', placeholder: 'Ví dụ 26.300', receive: 'USDT', op: 'divide', vndThousands: true},\n      {label: 'USDT / EUR', tag: 'P2P', unit: 'EUR', placeholder: 'Ví dụ 0,8600', receive: 'EUR', op: 'multiply'},\n      {label: 'EUR / VND', unit: 'VND', placeholder: 'Ví dụ 30.700', receive: 'VND', op: 'multiply', vndThousands: true, fx: ['EUR', 'VND']}\n    ]\n  },\n  jpy: {\n    route: 'VND → JPY → USDT → VND', capital: 'VND', highlight: 2,\n    rates: [\n      {label: 'JPY / VND', unit: 'VND', placeholder: 'Ví dụ 165,50', receive: 'JPY', op: 'divide', fx: ['JPY', 'VND']},\n      {label: 'USDT / JPY', tag: 'P2P', unit: 'JPY', placeholder: 'Ví dụ 155,00', receive: 'USDT', op: 'divide'},\n      {label: 'USDT / VND', tag: 'P2P', unit: 'VND', placeholder: 'Ví dụ 26.300', receive: 'VND', op: 'multiply', vndThousands: true}\n    ]\n  },\n  rub: {\n    route: 'VND → RUB → USDT → VND', capital: 'VND', highlight: 3,\n    rates: [\n      {label: 'RUB / VND', unit: 'VND', placeholder: 'Ví dụ 310,50', receive: 'RUB', op: 'divide', fx: ['RUB', 'VND']},\n      {label: 'USD / RUB', unit: 'RUB', placeholder: 'Ví dụ 83,50', receive: 'USDT', op: 'divide', fx: ['USD', 'RUB']},\n      {label: 'USDT / VND', tag: 'P2P', unit: 'VND', placeholder: 'Ví dụ 26.300', receive: 'VND', op: 'multiply', vndThousands: true}\n    ]\n  }\n};\n\nfunction migrateVndTab() {\n  const legacy = {capital: 'tiendien_capitalVnd', rate1: 'tiendien_usdtVnd', rate2: 'tiendien_usdtEur', rate3: 'tiendien_eurVnd'};\n  for (const id of ['capital', 'rate1', 'rate2', 'rate3']) {\n    const target = `tiendien_vnd_${id}`;\n    const value = stored(`tiendien_eur_${id}`) ?? stored(legacy[id]);\n    if (stored(target) === null && value !== null) remember(target, value);\n  }\n}\nmigrateVndTab();\n// CAD now has a different starting currency and different quote positions.\n// Keep its new inputs separate so VND capital / unrelated old quotes cannot\n// acquire a new currency label. Only the unchanged USDT/CAD quote migrates.\nconst oldUsdtCad = stored('tiendien_cad_rate2');\nif (stored('tiendien_cad_eur_usdt_rate3') === null && oldUsdtCad !== null) {\n  remember('tiendien_cad_eur_usdt_rate3', oldUsdtCad);\n}\nlet page = stored('tiendien_page');\nif (page === 'eur' || !PAGES[page]) page = 'vnd';\n\nfunction capitalNum(value) {\n  const number = Number(String(value ?? '').replace(/\\D/g, ''));\n  return Number.isFinite(number) ? number : 0;\n}\nfunction rateNum(value, thousands = false) {\n  let text = String(value ?? '').trim().replace(/\\s/g, '');\n  if (!text) return 0;\n  if (text.includes(',')) text = text.replace(/\\./g, '').replace(',', '.');\n  else if (thousands && /^\\d{1,3}(?:\\.\\d{3})+$/.test(text)) text = text.replace(/\\./g, '');\n  const number = Number(text);\n  return Number.isFinite(number) ? number : 0;\n}\nfunction formatCapital() {\n  const digits = $('capital').value.replace(/\\D/g, '');\n  $('capital').value = digits ? fmt0.format(capitalNum(digits)) : '';\n}\nfunction money(value, unit) { return `${value >= 0 ? '+' : '−'}${(unit === 'CAD' ? fmt2 : fmt0).format(Math.abs(value))} ${unit}`; }\nfunction pct(value) { return `${value >= 0 ? '+' : ''}${fmt2.format(value)}%`; }\nfunction tone(element, value) {\n  element.classList.remove('good', 'bad', 'neutral');\n  element.classList.add(value > 0.01 ? 'good' : value < -0.01 ? 'bad' : 'neutral');\n}\nfunction formatReceived(value, unit) {\n  if (!(value > 0 && Number.isFinite(value))) return `Nhận: — ${unit}`;\n  return `Nhận: ${(unit === 'VND' || unit === 'TRY' ? fmt2 : fmt4).format(value)} ${unit}`;\n}\nfunction key(name) { return `tiendien_${page === 'cad' ? 'cad_eur_usdt' : page}_${name}`; }\nfunction save() {\n  remember(key('capital'), $('capital').value);\n  PAGES[page].rates.forEach((rate, index) => {\n    // Keep the last manually entered fiat quote separate from the live cache.\n    if (!fxEnabled || !rate.fx) remember(key(`rate${index + 1}`), $(`rate${index + 1}`).value);\n  });\n}\n\nconst FX_URL = 'https://open.er-api.com/v6/latest/USD';\nconst FX_CACHE_KEY = 'tiendien_fx_usd_v16';\nconst FX_AUTO_KEY = 'tiendien_fx_auto_v16';\nconst FX_ATTEMPT_KEY = 'tiendien_fx_attempt_v16';\nconst FX_CODES = ['USD', 'EUR', 'CAD', 'TRY', 'JPY', 'VND', 'RUB'];\nlet fxEnabled = stored(FX_AUTO_KEY) !== '0';\nlet fxError = '';\nlet fxBusy = false;\nlet fxRequest = null;\nlet fxLastAttempt = Number(stored(FX_ATTEMPT_KEY)) || 0;\n\nfunction validateFx(payload) {\n  if (!payload || payload.result !== 'success' || payload.base_code !== 'USD' || !payload.rates) throw new Error('Invalid FX data');\n  for (const code of FX_CODES) {\n    const rate = payload.rates[code];\n    if (typeof rate !== 'number' || !Number.isFinite(rate) || rate <= 0) throw new Error('Invalid FX rate');\n  }\n  if (Math.abs(payload.rates.USD - 1) > 0.000001) throw new Error('Invalid FX base');\n  const last = payload.time_last_update_unix;\n  const next = payload.time_next_update_unix;\n  if (!Number.isFinite(last) || !Number.isFinite(next) || last <= 0 || next <= last || last * 1000 > Date.now() + 300000) throw new Error('Invalid FX timestamp');\n  return payload;\n}\nfunction readFxCache() {\n  try {\n    const cached = JSON.parse(stored(FX_CACHE_KEY) || 'null');\n    if (!cached || !Number.isFinite(cached.fetchedAt) || cached.fetchedAt <= 0 || cached.fetchedAt > Date.now() + 300000) return null;\n    validateFx(cached.payload);\n    return cached;\n  } catch (_) { return null; }\n}\nlet fxSnapshot = readFxCache();\nfunction fxIsDue() {\n  return !fxSnapshot || Date.now() >= fxSnapshot.payload.time_next_update_unix * 1000 + 60000;\n}\nfunction crossRate(base, quote) {\n  if (!fxSnapshot) return 0;\n  return fxSnapshot.payload.rates[quote] / fxSnapshot.payload.rates[base];\n}\nfunction renderUsdReferences() {\n  // Benchmarks are read-only display data. Never substitute them for P2P\n  // USDT inputs or use them in the route's received/profit calculations.\n  PAGES[page].rates.forEach((rate, index) => {\n    const reference = $(`usdReference${index + 1}`);\n    const pair = rate.label.split('/').map(code => code.trim());\n    const hasUsdt = pair.includes('USDT');\n    reference.classList.toggle('hidden', !hasUsdt);\n    reference.classList.toggle('stale', hasUsdt && Boolean(fxSnapshot) && (fxIsDue() || Boolean(fxError)));\n    if (!hasUsdt) {\n      reference.textContent = '';\n      reference.setAttribute('title', '');\n      return;\n    }\n    const currency = pair.find(code => code !== 'USDT');\n    const label = `USD / ${currency}`;\n    if (fxSnapshot) {\n      const value = crossRate('USD', currency);\n      const qualifier = fxError ? ' · giá lưu' : fxIsDue() ? ' · giá cũ' : '';\n      reference.textContent = `${label}: ${fmt4.format(value)}${qualifier}`;\n      const timestamp = new Date(fxSnapshot.payload.time_last_update_unix * 1000).toLocaleString('vi-VN', {timeZone: 'Asia/Ho_Chi_Minh'});\n      reference.setAttribute('title', `1 USD = ${fmt4.format(value)} ${currency}. Tỷ giá tham khảo từ ExchangeRate-API, lúc ${timestamp} (giờ VN).`);\n    } else {\n      reference.textContent = `${label}: ${fxBusy ? 'đang tải…' : fxError ? 'chưa tải được' : '—'}`;\n      reference.setAttribute('title', 'Chưa có dữ liệu tỷ giá pháp định; không suy ra từ giá USDT nhập tay.');\n    }\n  });\n}\nfunction applyFxToPage() {\n  if (!fxEnabled || !fxSnapshot) return;\n  PAGES[page].rates.forEach((rate, index) => {\n    if (!rate.fx) return;\n    const value = crossRate(...rate.fx);\n    const input = $(`rate${index + 1}`);\n    input.value = fmtRate.format(value);\n    input.dataset.fxSource = 'api';\n  });\n}\nfunction renderFxStatus() {\n  $('fxAuto').setAttribute('aria-checked', String(fxEnabled));\n  $('fxAuto').classList.toggle('enabled', fxEnabled);\n  $('fxAutoText').textContent = `Tự điền: ${fxEnabled ? 'Bật' : 'Tắt'}`;\n  $('fxRefresh').disabled = fxBusy;\n  $('fxRefresh').textContent = fxBusy ? 'Đang tải…' : 'Cập nhật';\n  $('fxStatus').classList.toggle('fx-warning', Boolean(fxError) || (fxIsDue() && Boolean(fxSnapshot)));\n  const manualPrefix = fxEnabled ? '' : 'Ô giá nhập tay. ';\n  if (fxSnapshot) {\n    const date = new Intl.DateTimeFormat('vi-VN', {dateStyle: 'short', timeStyle: 'short', timeZone: 'Asia/Ho_Chi_Minh'}).format(new Date(fxSnapshot.payload.time_last_update_unix * 1000));\n    const prefix = fxError ? `${fxError} · đang dùng giá lưu lúc ` : fxIsDue() ? 'Giá cũ từ ' : 'Tỷ giá lúc ';\n    $('fxStatus').textContent = `${manualPrefix}${prefix}${date} (giờ VN). USDT nhập tay.`;\n  } else if (fxError) {\n    $('fxStatus').textContent = `${manualPrefix}${fxError}. ${fxEnabled ? 'Tắt Tự điền để nhập tay.' : 'USD tham khảo chưa có dữ liệu.'}`;\n  } else {\n    $('fxStatus').textContent = manualPrefix + (fxBusy ? 'Đang lấy tỷ giá pháp định… USDT nhập tay.' : 'Chưa có tỷ giá tự động. USDT nhập tay.');\n  }\n  PAGES[page].rates.forEach((rate, index) => {\n    const input = $(`rate${index + 1}`);\n    const automatic = Boolean(rate.fx && fxEnabled);\n    input.readOnly = automatic;\n    input.setAttribute('aria-readonly', String(automatic));\n    const tag = rate.fx ? (automatic ? (fxSnapshot ? 'TỰ ĐỘNG' : input.value ? 'ĐÃ LƯU' : 'CHỜ GIÁ') : 'NHẬP TAY') : rate.tag;\n    $(`rate${index + 1}Label`).innerHTML = `${rate.label}${tag ? ` <small>${tag}</small>` : ''}`;\n    input.closest('.field').classList.toggle('auto-rate', automatic);\n  });\n  $('resultNote').textContent = fxEnabled ? 'Ước tính theo tỷ giá tham khảo · chưa trừ phí' : 'Ước tính · chưa trừ phí giao dịch';\n  renderUsdReferences();\n}\n\nasync function refreshFx({force = false} = {}) {\n  // The feed also powers USD reference lines while auto-fill is disabled.\n  if (fxRequest) return fxRequest;\n  if (!force && !fxIsDue()) { renderFxStatus(); return; }\n  const elapsed = Date.now() - fxLastAttempt;\n  // One scheduled attempt every five minutes when offline/unavailable; manual\n  // refresh is limited to once a minute. A fresh daily snapshot needs no poll.\n  if (elapsed >= 0 && elapsed < (force ? 60000 : 300000)) { renderFxStatus(); return; }\n  fxLastAttempt = Date.now();\n  remember(FX_ATTEMPT_KEY, fxLastAttempt);\n  fxBusy = true;\n  renderFxStatus();\n  fxRequest = (async () => {\n    const controller = new AbortController();\n    const timeout = setTimeout(() => controller.abort(), 10000);\n    try {\n      const response = await fetch(FX_URL, {cache: 'no-store', credentials: 'omit', signal: controller.signal});\n      if (!response.ok) throw new Error(response.status === 429 ? 'RATE_LIMIT' : 'FETCH_FAILED');\n      const payload = validateFx(await response.json());\n      if (fxSnapshot && payload.time_last_update_unix < fxSnapshot.payload.time_last_update_unix) throw new Error('Older FX response');\n      fxSnapshot = {payload, fetchedAt: Date.now()};\n      remember(FX_CACHE_KEY, JSON.stringify(fxSnapshot));\n      fxError = '';\n      // The user may have switched tabs or disabled auto while fetch awaited.\n      if (fxEnabled) { applyFxToPage(); calculate(); }\n    } catch (error) {\n      fxError = error.message === 'RATE_LIMIT' ? 'Nguồn đang giới hạn truy cập' : 'Không tải được tỷ giá';\n    } finally {\n      clearTimeout(timeout);\n      fxBusy = false;\n      fxRequest = null;\n      renderFxStatus();\n    }\n  })();\n  return fxRequest;\n}\n\nfunction restorePage() {\n  $('capital').value = stored(key('capital')) ?? (page === 'cad' ? '10.000' : page === 'try' ? '100.000' : '100.000.000');\n  ['rate1', 'rate2', 'rate3'].forEach(id => {\n    $(id).value = stored(key(id)) ?? '';\n    delete $(id).dataset.fxSource;\n  });\n  formatCapital();\n}\nfunction renderPage() {\n  const config = PAGES[page];\n  $('routeText').textContent = config.route;\n  $('capitalUnit').textContent = config.capital;\n  config.rates.forEach((rate, index) => {\n    const input = $(`rate${index + 1}`);\n    $(`rate${index + 1}Unit`).textContent = rate.unit;\n    input.placeholder = rate.placeholder;\n    input.setAttribute('aria-label', `${rate.label}: số ${rate.unit} cho một ${rate.label.split(' / ')[0]}`);\n    input.closest('.field').classList.toggle('rate-highlight', index + 1 === config.highlight);\n  });\n  document.querySelectorAll('.tab').forEach(button => {\n    const active = button.dataset.page === page;\n    button.classList.toggle('active', active);\n    button.setAttribute('aria-pressed', String(active));\n  });\n  $('rubNote').classList.toggle('hidden', page !== 'rub');\n  remember('tiendien_page', page);\n  restorePage();\n  applyFxToPage();\n  renderFxStatus();\n  calculate();\n}\nfunction calculate() {\n  const config = PAGES[page];\n  const capital = capitalNum($('capital').value);\n  let amount = capital;\n  config.rates.forEach((rate, index) => {\n    const quote = rateNum($(`rate${index + 1}`).value, Boolean(rate.vndThousands));\n    amount = amount > 0 && quote > 0 ? (rate.op === 'divide' ? amount / quote : amount * quote) : 0;\n    if (!Number.isFinite(amount)) amount = 0;\n    $(`received${index + 1}`).textContent = formatReceived(amount, rate.receive);\n  });\n  if (!(capital > 0 && amount > 0)) {\n    $('profit').textContent = '—'; $('roi').textContent = '—';\n    $('profit').className = ''; $('roi').className = '';\n  } else {\n    const profit = amount - capital;\n    const roi = profit / capital * 100;\n    if (Number.isFinite(profit) && Number.isFinite(roi)) {\n      $('profit').textContent = money(profit, config.capital);\n      $('roi').textContent = pct(roi);\n      tone($('profit'), profit); tone($('roi'), profit);\n    } else {\n      $('profit').textContent = '—'; $('roi').textContent = '—';\n      $('profit').className = ''; $('roi').className = '';\n    }\n  }\n  save();\n}\n\n$('capital').addEventListener('input', () => { formatCapital(); calculate(); });\n['rate1', 'rate2', 'rate3'].forEach(id => $(id).addEventListener('input', calculate));\ndocument.querySelectorAll('.tab').forEach(button => button.addEventListener('click', () => {\n  save(); page = button.dataset.page; renderPage(); refreshFx();\n}));\n$('fxAuto').addEventListener('click', () => {\n  save();\n  fxEnabled = !fxEnabled;\n  remember(FX_AUTO_KEY, fxEnabled ? '1' : '0');\n  if (fxEnabled) applyFxToPage();\n  else {\n    PAGES[page].rates.forEach((rate, index) => {\n      if (!rate.fx) return;\n      const manual = stored(key(`rate${index + 1}`));\n      if (manual !== null) $(`rate${index + 1}`).value = manual;\n      delete $(`rate${index + 1}`).dataset.fxSource;\n    });\n  }\n  renderFxStatus(); calculate();\n  if (fxEnabled) refreshFx();\n});\n$('fxRefresh').addEventListener('click', () => refreshFx({force: true}));\nwindow.addEventListener('online', () => refreshFx());\ndocument.addEventListener('visibilitychange', () => { if (!document.hidden) refreshFx(); });\nsetInterval(() => { if (!document.hidden) refreshFx(); }, 60000);\n\nlet deferredPrompt = null;\nwindow.addEventListener('beforeinstallprompt', event => {\n  event.preventDefault(); deferredPrompt = event; $('installBtn').classList.remove('hidden');\n});\n$('installBtn').addEventListener('click', async () => {\n  if (!deferredPrompt) return;\n  deferredPrompt.prompt(); await deferredPrompt.userChoice;\n  deferredPrompt = null; $('installBtn').classList.add('hidden');\n});\n\n// Retire this app's old cache without touching other apps on the same origin.\n(async () => {\n  try {\n    if ('serviceWorker' in navigator) {\n      const scope = new URL('./', location.href).href;\n      const registrations = await navigator.serviceWorker.getRegistrations();\n      for (const registration of registrations) if (registration.scope === scope) await registration.unregister();\n    }\n    if ('caches' in window) {\n      for (const name of await caches.keys()) if (/^(tien-cua-dien|tiendien)[-_]/.test(name)) await caches.delete(name);\n    }\n  } catch (_) {}\n})();\nrenderPage();\nrefreshFx();\n\n</script>\n</body>\n</html>\n"},"/v17.html":{"type":"text/html; charset=utf-8","body":"<!doctype html>\n<html lang=\"vi\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta http-equiv=\"Cache-Control\" content=\"no-cache, no-store, must-revalidate\">\n  <meta http-equiv=\"Pragma\" content=\"no-cache\">\n  <meta http-equiv=\"Expires\" content=\"0\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n  <meta name=\"theme-color\" content=\"#090b0c\">\n  <meta name=\"color-scheme\" content=\"dark\">\n  <title>Tiền của Điền</title>\n  <link rel=\"manifest\" href=\"./manifest.webmanifest?v=18\">\n  <link rel=\"icon\" href=\"./icon.svg\" type=\"image/svg+xml\">\n<style>\n:root{--bg:#090b0c;--panel:#121517;--field:#0c0f11;--line:#252b2f;--text:#f4f7f8;--muted:#899197;--accent:#00e68a;--bad:#ff6670;--warn:#f2c14e}\n*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;background:var(--bg);overflow:auto}body{font-family:Inter,ui-sans-serif,system-ui,-apple-system,\"Segoe UI\",sans-serif;color:var(--text)}button,input{font:inherit}.app{height:100dvh;min-height:530px;max-width:620px;margin:0 auto;padding:max(12px,env(safe-area-inset-top)) 14px max(12px,env(safe-area-inset-bottom));display:grid;grid-template-rows:auto auto auto minmax(115px,1fr);gap:10px;background:radial-gradient(circle at 90% -10%,rgba(0,230,138,.12),transparent 36%)}header{display:flex;justify-content:space-between;align-items:center;gap:12px}.route{font-size:11px;font-weight:800;letter-spacing:.06em;color:var(--accent)}h1{margin:2px 0 0;font-size:27px;line-height:1;letter-spacing:-.045em}.version{display:inline-block;margin-top:5px;font-size:9px;font-weight:900;letter-spacing:.08em;color:var(--accent);opacity:.8}.install{border:1px solid var(--line);background:var(--panel);color:var(--accent);font-size:11px;font-weight:850;padding:8px 11px;border-radius:10px;cursor:pointer}.hidden{display:none!important}.tabs{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:7px}.tab{height:34px;border:1px solid var(--line);border-radius:10px;background:#101315;color:var(--muted);font-size:12px;font-weight:900;letter-spacing:.04em;cursor:pointer}.tab.active{color:#07110d;background:var(--accent);border-color:var(--accent)}.panel{border:1px solid var(--line);background:linear-gradient(180deg,#15191b,var(--panel));border-radius:17px;padding:12px}.inputs{display:grid;grid-template-columns:1fr 1fr;gap:10px}.inputs label.wide{grid-column:1/-1}.inputs label>span{display:flex;justify-content:space-between;align-items:center;gap:6px;font-size:11px;font-weight:780;color:#c7cdd0;margin:0 2px 5px}.inputs small{font-size:8px;color:var(--muted);font-weight:900;letter-spacing:.07em}.field{height:45px;display:flex;align-items:center;border:1px solid var(--line);background:var(--field);border-radius:12px;overflow:hidden}.field:focus-within{border-color:var(--accent);box-shadow:0 0 0 2px rgba(0,230,138,.08)}.field.rate-highlight{background:linear-gradient(180deg,rgba(0,230,138,.18),rgba(0,230,138,.08));border-color:rgba(0,230,138,.62);box-shadow:inset 0 0 0 1px rgba(0,230,138,.06)}.field.rate-highlight input{color:#f7fffb}.field.rate-highlight b{color:var(--accent)}.field input{width:100%;min-width:0;height:100%;border:0;outline:0;background:transparent;color:var(--text);padding:0 11px;font-size:16px;font-weight:800}.field input::placeholder{color:#535b60;font-size:12px;font-weight:650}.field b{font-size:9px;color:var(--muted);padding:0 10px}.received{display:block;margin:5px 3px 0;color:var(--muted);font-size:10px;line-height:1.15;font-style:normal;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.result-card{min-height:0;border:1px solid #284439;background:linear-gradient(180deg,#142119,#101613);border-radius:18px;padding:14px;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center}.result-card span{font-size:10px;color:var(--muted);font-weight:900;letter-spacing:.12em}.result-card strong{font-size:clamp(30px,8vw,46px);line-height:1.03;margin:8px 0 4px;letter-spacing:-.055em}.result-card b{font-size:16px}.good{color:var(--accent)!important}.bad{color:var(--bad)!important}.neutral{color:var(--warn)!important}\n@media(max-width:390px){.app{padding-left:10px;padding-right:10px;gap:8px}.panel{padding:10px}.inputs{gap:8px}.field{height:41px}.field input{font-size:14px}h1{font-size:23px}.received{font-size:9px;margin-top:4px}.result-card{padding:11px}.result-card strong{font-size:29px}.tab{height:31px;font-size:11px}}\n@media(max-height:690px){.app{gap:7px;padding-top:7px;padding-bottom:7px}.route{font-size:9px}h1{font-size:20px}.tabs{gap:5px}.tab{height:28px;font-size:10px}.panel{padding:8px}.inputs{gap:6px}.inputs label>span{font-size:9px;margin-bottom:3px}.field{height:33px}.field input{font-size:13px}.received{font-size:8px;margin-top:3px}.result-card{padding:8px}.result-card strong{font-size:26px;margin:4px 0 2px}}\n.fx-tools{grid-column:1/-1;border-top:1px solid var(--line);padding-top:9px;min-width:0}\n.fx-controls{display:flex;align-items:center;justify-content:space-between;gap:8px}\n.fx-toggle,.fx-refresh{min-height:32px;border:1px solid var(--line);border-radius:9px;background:var(--field);color:var(--muted);padding:5px 10px;font-size:11px;font-weight:800;cursor:pointer}\n.fx-toggle{display:inline-flex;align-items:center;gap:7px}\n.fx-toggle.enabled{color:var(--accent);border-color:#285d46;background:#11251c}\n.fx-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:currentColor}\n.fx-refresh{color:var(--text)}.fx-refresh:disabled{opacity:.45;cursor:default}\n.fx-tools p{margin:5px 0 0;font-size:9px;line-height:1.4;color:var(--muted);overflow-wrap:anywhere}\n.fx-tools a{color:var(--muted);text-underline-offset:2px}\n.fx-tools .fx-warning{color:var(--warn)}\n.field.auto-rate{border-style:dashed}.field.auto-rate input{cursor:default}\n.rub-note{grid-column:1/-1;margin:0 2px;color:var(--warn);font-size:10px;line-height:1.35}\n.result-note{margin:8px 0 0;font-size:9px;line-height:1.4;color:var(--muted);font-weight:500;letter-spacing:0}\n.usd-reference{display:block;margin:4px 3px 0;font-size:10px;line-height:1.35;font-style:normal;font-weight:650;color:#73c6a3;overflow-wrap:anywhere}\n.usd-reference.stale{color:var(--warn)}\nbutton:focus-visible{outline:2px solid var(--accent);outline-offset:3px}\n@media(max-width:390px){.tabs{gap:5px}.fx-toggle,.fx-refresh{font-size:10px;padding:5px 8px}}\n@media(max-height:690px){.fx-tools{padding-top:6px}.fx-tools p{font-size:8px;margin-top:3px}.fx-toggle,.fx-refresh{min-height:28px;font-size:10px}.rub-note{font-size:9px}.result-note{font-size:8px;margin-top:5px}.usd-reference{font-size:9px;margin-top:3px}}\n\n</style>\n</head>\n<body>\n  <main class=\"app\">\n    <header>\n      <div>\n        <div class=\"route\" id=\"routeText\">VND → USDT → EUR → VND</div>\n        <h1>Tiền của Điền</h1><span class=\"version\">v18 · TỶ GIÁ USD THAM KHẢO</span>\n      </div>\n      <button id=\"installBtn\" class=\"install hidden\">Cài app</button>\n    </header>\n\n    <nav class=\"tabs\" aria-label=\"Loại vòng tiền\">\n      <button type=\"button\" class=\"tab\" data-page=\"cad\">CAD</button>\n      <button type=\"button\" class=\"tab\" data-page=\"try\">TRY</button>\n      <button type=\"button\" class=\"tab active\" data-page=\"vnd\">VND</button>\n      <button type=\"button\" class=\"tab\" data-page=\"jpy\">JPY</button>\n      <button type=\"button\" class=\"tab\" data-page=\"rub\">RUB</button>\n    </nav>\n\n    <section class=\"panel inputs\">\n      <label class=\"wide\">\n        <span>Vốn ban đầu</span>\n        <div class=\"field\"><input aria-label=\"Vốn ban đầu\" id=\"capital\" inputmode=\"numeric\" value=\"100.000.000\"><b id=\"capitalUnit\">VND</b></div>\n      </label>\n\n      <label>\n        <span id=\"rate1Label\">USDT / VND <small>P2P</small></span>\n        <div class=\"field\"><input id=\"rate1\" inputmode=\"decimal\" placeholder=\"Ví dụ 26.300\"><b id=\"rate1Unit\">VND</b></div>\n        <em class=\"received\" id=\"received1\">Nhận: — USDT</em>\n        <em class=\"usd-reference hidden\" id=\"usdReference1\" aria-live=\"polite\"></em>\n      </label>\n\n      <label>\n        <span id=\"rate2Label\">USDT / EUR <small>P2P</small></span>\n        <div class=\"field\"><input id=\"rate2\" inputmode=\"decimal\" placeholder=\"Ví dụ 0,8600\"><b id=\"rate2Unit\">EUR</b></div>\n        <em class=\"received\" id=\"received2\">Nhận: — EUR</em>\n        <em class=\"usd-reference hidden\" id=\"usdReference2\" aria-live=\"polite\"></em>\n      </label>\n\n      <label class=\"wide\">\n        <span id=\"rate3Label\">EUR / VND</span>\n        <div class=\"field\"><input id=\"rate3\" inputmode=\"decimal\" placeholder=\"Ví dụ 30.700\"><b id=\"rate3Unit\">VND</b></div>\n        <em class=\"received\" id=\"received3\">Nhận: — VND</em>\n        <em class=\"usd-reference hidden\" id=\"usdReference3\" aria-live=\"polite\"></em>\n      </label>\n\n      <p id=\"rubNote\" class=\"rub-note hidden\">Bước USD/RUB quy ước 1 USDT = 1 USD. Giá mua USDT thực tế có thể khác.</p>\n      <div class=\"fx-tools\">\n        <div class=\"fx-controls\">\n          <button type=\"button\" id=\"fxAuto\" class=\"fx-toggle enabled\" role=\"switch\" aria-checked=\"true\" aria-label=\"Tự động điền các ô tỷ giá pháp định\"><i class=\"fx-dot\" aria-hidden=\"true\"></i><span id=\"fxAutoText\">Tự điền: Bật</span></button>\n          <button type=\"button\" id=\"fxRefresh\" class=\"fx-refresh\">Cập nhật</button>\n        </div>\n        <p id=\"fxStatus\" role=\"status\" aria-live=\"polite\">Đang lấy tỷ giá pháp định…</p>\n        <p><a href=\"https://www.exchangerate-api.com\" target=\"_blank\" rel=\"noopener noreferrer\">Rates By Exchange Rate API</a> · Tham khảo, cập nhật hằng ngày.</p>\n      </div>\n    </section>\n\n    <section class=\"result-card\">\n      <span>LÃI / LỖ</span>\n      <strong id=\"profit\">—</strong>\n      <b id=\"roi\">—</b>\n      <p id=\"resultNote\" class=\"result-note\">Ước tính · chưa trừ phí giao dịch</p>\n    </section>\n  </main>\n\n\n\n<script>\n'use strict';\nconst $ = id => document.getElementById(id);\nconst fmt0 = new Intl.NumberFormat('vi-VN', {maximumFractionDigits: 0});\nconst fmt2 = new Intl.NumberFormat('vi-VN', {maximumFractionDigits: 2});\nconst fmt4 = new Intl.NumberFormat('vi-VN', {maximumFractionDigits: 4});\nconst fmtRate = new Intl.NumberFormat('vi-VN', {useGrouping: false, maximumFractionDigits: 6});\nconst memoryStorage = new Map();\nfunction stored(name) {\n  try { return localStorage.getItem(name) ?? memoryStorage.get(name) ?? null; }\n  catch (_) { return memoryStorage.get(name) ?? null; }\n}\nfunction remember(name, value) {\n  memoryStorage.set(name, String(value));\n  try { localStorage.setItem(name, String(value)); } catch (_) {}\n}\n\n// A/B always means the amount of B for ONE unit of A.\n// Only explicit fiat pairs have an fx property. USDT is never fetched or\n// inferred from the provider's USD rate, except the disclosed RUB convention.\nconst PAGES = {\n  cad: {\n    route: 'CAD → EUR → USDT → CAD', capital: 'CAD', highlight: 0,\n    rates: [\n      {label: 'EUR / CAD', unit: 'CAD', placeholder: 'Ví dụ 1,5500', receive: 'EUR', op: 'divide', fx: ['EUR', 'CAD']},\n      {label: 'USDT / EUR', tag: 'P2P', unit: 'EUR', placeholder: 'Ví dụ 0,8900', receive: 'USDT', op: 'divide'},\n      {label: 'USDT / CAD', tag: 'P2P', unit: 'CAD', placeholder: 'Ví dụ 1,3900', receive: 'CAD', op: 'multiply'}\n    ]\n  },\n  try: {\n    route: 'TRY → EUR → USDT → TRY', capital: 'TRY', highlight: 3,\n    rates: [\n      {label: 'EUR / TRY', unit: 'TRY', placeholder: 'Ví dụ 48,50', receive: 'EUR', op: 'divide', fx: ['EUR', 'TRY']},\n      {label: 'USDT / EUR', tag: 'P2P', unit: 'EUR', placeholder: 'Ví dụ 0,8550', receive: 'USDT', op: 'divide'},\n      {label: 'USDT / TRY', tag: 'P2P', unit: 'TRY', placeholder: 'Ví dụ 41,50', receive: 'TRY', op: 'multiply'}\n    ]\n  },\n  vnd: {\n    route: 'VND → USDT → EUR → VND', capital: 'VND', highlight: 1,\n    rates: [\n      {label: 'USDT / VND', tag: 'P2P', unit: 'VND', placeholder: 'Ví dụ 26.300', receive: 'USDT', op: 'divide', vndThousands: true},\n      {label: 'USDT / EUR', tag: 'P2P', unit: 'EUR', placeholder: 'Ví dụ 0,8600', receive: 'EUR', op: 'multiply'},\n      {label: 'EUR / VND', unit: 'VND', placeholder: 'Ví dụ 30.700', receive: 'VND', op: 'multiply', vndThousands: true, fx: ['EUR', 'VND']}\n    ]\n  },\n  jpy: {\n    route: 'VND → JPY → USDT → VND', capital: 'VND', highlight: 2,\n    rates: [\n      {label: 'JPY / VND', unit: 'VND', placeholder: 'Ví dụ 165,50', receive: 'JPY', op: 'divide', fx: ['JPY', 'VND']},\n      {label: 'USDT / JPY', tag: 'P2P', unit: 'JPY', placeholder: 'Ví dụ 155,00', receive: 'USDT', op: 'divide'},\n      {label: 'USDT / VND', tag: 'P2P', unit: 'VND', placeholder: 'Ví dụ 26.300', receive: 'VND', op: 'multiply', vndThousands: true}\n    ]\n  },\n  rub: {\n    route: 'VND → RUB → USDT → VND', capital: 'VND', highlight: 3,\n    rates: [\n      {label: 'RUB / VND', unit: 'VND', placeholder: 'Ví dụ 310,50', receive: 'RUB', op: 'divide', fx: ['RUB', 'VND']},\n      {label: 'USD / RUB', unit: 'RUB', placeholder: 'Ví dụ 83,50', receive: 'USDT', op: 'divide', fx: ['USD', 'RUB']},\n      {label: 'USDT / VND', tag: 'P2P', unit: 'VND', placeholder: 'Ví dụ 26.300', receive: 'VND', op: 'multiply', vndThousands: true}\n    ]\n  }\n};\n\nfunction migrateVndTab() {\n  const legacy = {capital: 'tiendien_capitalVnd', rate1: 'tiendien_usdtVnd', rate2: 'tiendien_usdtEur', rate3: 'tiendien_eurVnd'};\n  for (const id of ['capital', 'rate1', 'rate2', 'rate3']) {\n    const target = `tiendien_vnd_${id}`;\n    const value = stored(`tiendien_eur_${id}`) ?? stored(legacy[id]);\n    if (stored(target) === null && value !== null) remember(target, value);\n  }\n}\nmigrateVndTab();\n// CAD now has a different starting currency and different quote positions.\n// Keep its new inputs separate so VND capital / unrelated old quotes cannot\n// acquire a new currency label. Only the unchanged USDT/CAD quote migrates.\nconst oldUsdtCad = stored('tiendien_cad_rate2');\nif (stored('tiendien_cad_eur_usdt_rate3') === null && oldUsdtCad !== null) {\n  remember('tiendien_cad_eur_usdt_rate3', oldUsdtCad);\n}\nlet page = stored('tiendien_page');\nif (page === 'eur' || !PAGES[page]) page = 'vnd';\n\nfunction capitalNum(value) {\n  const number = Number(String(value ?? '').replace(/\\D/g, ''));\n  return Number.isFinite(number) ? number : 0;\n}\nfunction rateNum(value, thousands = false) {\n  let text = String(value ?? '').trim().replace(/\\s/g, '');\n  if (!text) return 0;\n  if (text.includes(',')) text = text.replace(/\\./g, '').replace(',', '.');\n  else if (thousands && /^\\d{1,3}(?:\\.\\d{3})+$/.test(text)) text = text.replace(/\\./g, '');\n  const number = Number(text);\n  return Number.isFinite(number) ? number : 0;\n}\nfunction formatCapital() {\n  const digits = $('capital').value.replace(/\\D/g, '');\n  $('capital').value = digits ? fmt0.format(capitalNum(digits)) : '';\n}\nfunction money(value, unit) { return `${value >= 0 ? '+' : '−'}${(unit === 'CAD' ? fmt2 : fmt0).format(Math.abs(value))} ${unit}`; }\nfunction pct(value) { return `${value >= 0 ? '+' : ''}${fmt2.format(value)}%`; }\nfunction tone(element, value) {\n  element.classList.remove('good', 'bad', 'neutral');\n  element.classList.add(value > 0.01 ? 'good' : value < -0.01 ? 'bad' : 'neutral');\n}\nfunction formatReceived(value, unit) {\n  if (!(value > 0 && Number.isFinite(value))) return `Nhận: — ${unit}`;\n  return `Nhận: ${(unit === 'VND' || unit === 'TRY' ? fmt2 : fmt4).format(value)} ${unit}`;\n}\nfunction key(name) { return `tiendien_${page === 'cad' ? 'cad_eur_usdt' : page}_${name}`; }\nfunction save() {\n  remember(key('capital'), $('capital').value);\n  PAGES[page].rates.forEach((rate, index) => {\n    // Keep the last manually entered fiat quote separate from the live cache.\n    if (!fxEnabled || !rate.fx) remember(key(`rate${index + 1}`), $(`rate${index + 1}`).value);\n  });\n}\n\nconst FX_URL = 'https://open.er-api.com/v6/latest/USD';\nconst FX_CACHE_KEY = 'tiendien_fx_usd_v16';\nconst FX_AUTO_KEY = 'tiendien_fx_auto_v16';\nconst FX_ATTEMPT_KEY = 'tiendien_fx_attempt_v16';\nconst FX_CODES = ['USD', 'EUR', 'CAD', 'TRY', 'JPY', 'VND', 'RUB'];\nlet fxEnabled = stored(FX_AUTO_KEY) !== '0';\nlet fxError = '';\nlet fxBusy = false;\nlet fxRequest = null;\nlet fxLastAttempt = Number(stored(FX_ATTEMPT_KEY)) || 0;\n\nfunction validateFx(payload) {\n  if (!payload || payload.result !== 'success' || payload.base_code !== 'USD' || !payload.rates) throw new Error('Invalid FX data');\n  for (const code of FX_CODES) {\n    const rate = payload.rates[code];\n    if (typeof rate !== 'number' || !Number.isFinite(rate) || rate <= 0) throw new Error('Invalid FX rate');\n  }\n  if (Math.abs(payload.rates.USD - 1) > 0.000001) throw new Error('Invalid FX base');\n  const last = payload.time_last_update_unix;\n  const next = payload.time_next_update_unix;\n  if (!Number.isFinite(last) || !Number.isFinite(next) || last <= 0 || next <= last || last * 1000 > Date.now() + 300000) throw new Error('Invalid FX timestamp');\n  return payload;\n}\nfunction readFxCache() {\n  try {\n    const cached = JSON.parse(stored(FX_CACHE_KEY) || 'null');\n    if (!cached || !Number.isFinite(cached.fetchedAt) || cached.fetchedAt <= 0 || cached.fetchedAt > Date.now() + 300000) return null;\n    validateFx(cached.payload);\n    return cached;\n  } catch (_) { return null; }\n}\nlet fxSnapshot = readFxCache();\nfunction fxIsDue() {\n  return !fxSnapshot || Date.now() >= fxSnapshot.payload.time_next_update_unix * 1000 + 60000;\n}\nfunction crossRate(base, quote) {\n  if (!fxSnapshot) return 0;\n  return fxSnapshot.payload.rates[quote] / fxSnapshot.payload.rates[base];\n}\nfunction renderUsdReferences() {\n  // Benchmarks are read-only display data. Never substitute them for P2P\n  // USDT inputs or use them in the route's received/profit calculations.\n  PAGES[page].rates.forEach((rate, index) => {\n    const reference = $(`usdReference${index + 1}`);\n    const pair = rate.label.split('/').map(code => code.trim());\n    const hasUsdt = pair.includes('USDT');\n    reference.classList.toggle('hidden', !hasUsdt);\n    reference.classList.toggle('stale', hasUsdt && Boolean(fxSnapshot) && (fxIsDue() || Boolean(fxError)));\n    if (!hasUsdt) {\n      reference.textContent = '';\n      reference.setAttribute('title', '');\n      return;\n    }\n    const currency = pair.find(code => code !== 'USDT');\n    const label = `USD / ${currency}`;\n    if (fxSnapshot) {\n      const value = crossRate('USD', currency);\n      const qualifier = fxError ? ' · giá lưu' : fxIsDue() ? ' · giá cũ' : '';\n      reference.textContent = `${label}: ${fmt4.format(value)}${qualifier}`;\n      const timestamp = new Date(fxSnapshot.payload.time_last_update_unix * 1000).toLocaleString('vi-VN', {timeZone: 'Asia/Ho_Chi_Minh'});\n      reference.setAttribute('title', `1 USD = ${fmt4.format(value)} ${currency}. Tỷ giá tham khảo từ ExchangeRate-API, lúc ${timestamp} (giờ VN).`);\n    } else {\n      reference.textContent = `${label}: ${fxBusy ? 'đang tải…' : fxError ? 'chưa tải được' : '—'}`;\n      reference.setAttribute('title', 'Chưa có dữ liệu tỷ giá pháp định; không suy ra từ giá USDT nhập tay.');\n    }\n  });\n}\nfunction applyFxToPage() {\n  if (!fxEnabled || !fxSnapshot) return;\n  PAGES[page].rates.forEach((rate, index) => {\n    if (!rate.fx) return;\n    const value = crossRate(...rate.fx);\n    const input = $(`rate${index + 1}`);\n    input.value = fmtRate.format(value);\n    input.dataset.fxSource = 'api';\n  });\n}\nfunction renderFxStatus() {\n  $('fxAuto').setAttribute('aria-checked', String(fxEnabled));\n  $('fxAuto').classList.toggle('enabled', fxEnabled);\n  $('fxAutoText').textContent = `Tự điền: ${fxEnabled ? 'Bật' : 'Tắt'}`;\n  $('fxRefresh').disabled = fxBusy;\n  $('fxRefresh').textContent = fxBusy ? 'Đang tải…' : 'Cập nhật';\n  $('fxStatus').classList.toggle('fx-warning', Boolean(fxError) || (fxIsDue() && Boolean(fxSnapshot)));\n  const manualPrefix = fxEnabled ? '' : 'Ô giá nhập tay. ';\n  if (fxSnapshot) {\n    const date = new Intl.DateTimeFormat('vi-VN', {dateStyle: 'short', timeStyle: 'short', timeZone: 'Asia/Ho_Chi_Minh'}).format(new Date(fxSnapshot.payload.time_last_update_unix * 1000));\n    const prefix = fxError ? `${fxError} · đang dùng giá lưu lúc ` : fxIsDue() ? 'Giá cũ từ ' : 'Tỷ giá lúc ';\n    $('fxStatus').textContent = `${manualPrefix}${prefix}${date} (giờ VN). USDT nhập tay.`;\n  } else if (fxError) {\n    $('fxStatus').textContent = `${manualPrefix}${fxError}. ${fxEnabled ? 'Tắt Tự điền để nhập tay.' : 'USD tham khảo chưa có dữ liệu.'}`;\n  } else {\n    $('fxStatus').textContent = manualPrefix + (fxBusy ? 'Đang lấy tỷ giá pháp định… USDT nhập tay.' : 'Chưa có tỷ giá tự động. USDT nhập tay.');\n  }\n  PAGES[page].rates.forEach((rate, index) => {\n    const input = $(`rate${index + 1}`);\n    const automatic = Boolean(rate.fx && fxEnabled);\n    input.readOnly = automatic;\n    input.setAttribute('aria-readonly', String(automatic));\n    const tag = rate.fx ? (automatic ? (fxSnapshot ? 'TỰ ĐỘNG' : input.value ? 'ĐÃ LƯU' : 'CHỜ GIÁ') : 'NHẬP TAY') : rate.tag;\n    $(`rate${index + 1}Label`).innerHTML = `${rate.label}${tag ? ` <small>${tag}</small>` : ''}`;\n    input.closest('.field').classList.toggle('auto-rate', automatic);\n  });\n  $('resultNote').textContent = fxEnabled ? 'Ước tính theo tỷ giá tham khảo · chưa trừ phí' : 'Ước tính · chưa trừ phí giao dịch';\n  renderUsdReferences();\n}\n\nasync function refreshFx({force = false} = {}) {\n  // The feed also powers USD reference lines while auto-fill is disabled.\n  if (fxRequest) return fxRequest;\n  if (!force && !fxIsDue()) { renderFxStatus(); return; }\n  const elapsed = Date.now() - fxLastAttempt;\n  // One scheduled attempt every five minutes when offline/unavailable; manual\n  // refresh is limited to once a minute. A fresh daily snapshot needs no poll.\n  if (elapsed >= 0 && elapsed < (force ? 60000 : 300000)) { renderFxStatus(); return; }\n  fxLastAttempt = Date.now();\n  remember(FX_ATTEMPT_KEY, fxLastAttempt);\n  fxBusy = true;\n  renderFxStatus();\n  fxRequest = (async () => {\n    const controller = new AbortController();\n    const timeout = setTimeout(() => controller.abort(), 10000);\n    try {\n      const response = await fetch(FX_URL, {cache: 'no-store', credentials: 'omit', signal: controller.signal});\n      if (!response.ok) throw new Error(response.status === 429 ? 'RATE_LIMIT' : 'FETCH_FAILED');\n      const payload = validateFx(await response.json());\n      if (fxSnapshot && payload.time_last_update_unix < fxSnapshot.payload.time_last_update_unix) throw new Error('Older FX response');\n      fxSnapshot = {payload, fetchedAt: Date.now()};\n      remember(FX_CACHE_KEY, JSON.stringify(fxSnapshot));\n      fxError = '';\n      // The user may have switched tabs or disabled auto while fetch awaited.\n      if (fxEnabled) { applyFxToPage(); calculate(); }\n    } catch (error) {\n      fxError = error.message === 'RATE_LIMIT' ? 'Nguồn đang giới hạn truy cập' : 'Không tải được tỷ giá';\n    } finally {\n      clearTimeout(timeout);\n      fxBusy = false;\n      fxRequest = null;\n      renderFxStatus();\n    }\n  })();\n  return fxRequest;\n}\n\nfunction restorePage() {\n  $('capital').value = stored(key('capital')) ?? (page === 'cad' ? '10.000' : page === 'try' ? '100.000' : '100.000.000');\n  ['rate1', 'rate2', 'rate3'].forEach(id => {\n    $(id).value = stored(key(id)) ?? '';\n    delete $(id).dataset.fxSource;\n  });\n  formatCapital();\n}\nfunction renderPage() {\n  const config = PAGES[page];\n  $('routeText').textContent = config.route;\n  $('capitalUnit').textContent = config.capital;\n  config.rates.forEach((rate, index) => {\n    const input = $(`rate${index + 1}`);\n    $(`rate${index + 1}Unit`).textContent = rate.unit;\n    input.placeholder = rate.placeholder;\n    input.setAttribute('aria-label', `${rate.label}: số ${rate.unit} cho một ${rate.label.split(' / ')[0]}`);\n    input.closest('.field').classList.toggle('rate-highlight', index + 1 === config.highlight);\n  });\n  document.querySelectorAll('.tab').forEach(button => {\n    const active = button.dataset.page === page;\n    button.classList.toggle('active', active);\n    button.setAttribute('aria-pressed', String(active));\n  });\n  $('rubNote').classList.toggle('hidden', page !== 'rub');\n  remember('tiendien_page', page);\n  restorePage();\n  applyFxToPage();\n  renderFxStatus();\n  calculate();\n}\nfunction calculate() {\n  const config = PAGES[page];\n  const capital = capitalNum($('capital').value);\n  let amount = capital;\n  config.rates.forEach((rate, index) => {\n    const quote = rateNum($(`rate${index + 1}`).value, Boolean(rate.vndThousands));\n    amount = amount > 0 && quote > 0 ? (rate.op === 'divide' ? amount / quote : amount * quote) : 0;\n    if (!Number.isFinite(amount)) amount = 0;\n    $(`received${index + 1}`).textContent = formatReceived(amount, rate.receive);\n  });\n  if (!(capital > 0 && amount > 0)) {\n    $('profit').textContent = '—'; $('roi').textContent = '—';\n    $('profit').className = ''; $('roi').className = '';\n  } else {\n    const profit = amount - capital;\n    const roi = profit / capital * 100;\n    if (Number.isFinite(profit) && Number.isFinite(roi)) {\n      $('profit').textContent = money(profit, config.capital);\n      $('roi').textContent = pct(roi);\n      tone($('profit'), profit); tone($('roi'), profit);\n    } else {\n      $('profit').textContent = '—'; $('roi').textContent = '—';\n      $('profit').className = ''; $('roi').className = '';\n    }\n  }\n  save();\n}\n\n$('capital').addEventListener('input', () => { formatCapital(); calculate(); });\n['rate1', 'rate2', 'rate3'].forEach(id => $(id).addEventListener('input', calculate));\ndocument.querySelectorAll('.tab').forEach(button => button.addEventListener('click', () => {\n  save(); page = button.dataset.page; renderPage(); refreshFx();\n}));\n$('fxAuto').addEventListener('click', () => {\n  save();\n  fxEnabled = !fxEnabled;\n  remember(FX_AUTO_KEY, fxEnabled ? '1' : '0');\n  if (fxEnabled) applyFxToPage();\n  else {\n    PAGES[page].rates.forEach((rate, index) => {\n      if (!rate.fx) return;\n      const manual = stored(key(`rate${index + 1}`));\n      if (manual !== null) $(`rate${index + 1}`).value = manual;\n      delete $(`rate${index + 1}`).dataset.fxSource;\n    });\n  }\n  renderFxStatus(); calculate();\n  if (fxEnabled) refreshFx();\n});\n$('fxRefresh').addEventListener('click', () => refreshFx({force: true}));\nwindow.addEventListener('online', () => refreshFx());\ndocument.addEventListener('visibilitychange', () => { if (!document.hidden) refreshFx(); });\nsetInterval(() => { if (!document.hidden) refreshFx(); }, 60000);\n\nlet deferredPrompt = null;\nwindow.addEventListener('beforeinstallprompt', event => {\n  event.preventDefault(); deferredPrompt = event; $('installBtn').classList.remove('hidden');\n});\n$('installBtn').addEventListener('click', async () => {\n  if (!deferredPrompt) return;\n  deferredPrompt.prompt(); await deferredPrompt.userChoice;\n  deferredPrompt = null; $('installBtn').classList.add('hidden');\n});\n\n// Retire this app's old cache without touching other apps on the same origin.\n(async () => {\n  try {\n    if ('serviceWorker' in navigator) {\n      const scope = new URL('./', location.href).href;\n      const registrations = await navigator.serviceWorker.getRegistrations();\n      for (const registration of registrations) if (registration.scope === scope) await registration.unregister();\n    }\n    if ('caches' in window) {\n      for (const name of await caches.keys()) if (/^(tien-cua-dien|tiendien)[-_]/.test(name)) await caches.delete(name);\n    }\n  } catch (_) {}\n})();\nrenderPage();\nrefreshFx();\n\n</script>\n</body>\n</html>\n"},"/v16.html":{"type":"text/html; charset=utf-8","body":"<!doctype html>\n<html lang=\"vi\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta http-equiv=\"Cache-Control\" content=\"no-cache, no-store, must-revalidate\">\n  <meta http-equiv=\"Pragma\" content=\"no-cache\">\n  <meta http-equiv=\"Expires\" content=\"0\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n  <meta name=\"theme-color\" content=\"#090b0c\">\n  <meta name=\"color-scheme\" content=\"dark\">\n  <title>Tiền của Điền</title>\n  <link rel=\"manifest\" href=\"./manifest.webmanifest?v=18\">\n  <link rel=\"icon\" href=\"./icon.svg\" type=\"image/svg+xml\">\n<style>\n:root{--bg:#090b0c;--panel:#121517;--field:#0c0f11;--line:#252b2f;--text:#f4f7f8;--muted:#899197;--accent:#00e68a;--bad:#ff6670;--warn:#f2c14e}\n*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;background:var(--bg);overflow:auto}body{font-family:Inter,ui-sans-serif,system-ui,-apple-system,\"Segoe UI\",sans-serif;color:var(--text)}button,input{font:inherit}.app{height:100dvh;min-height:530px;max-width:620px;margin:0 auto;padding:max(12px,env(safe-area-inset-top)) 14px max(12px,env(safe-area-inset-bottom));display:grid;grid-template-rows:auto auto auto minmax(115px,1fr);gap:10px;background:radial-gradient(circle at 90% -10%,rgba(0,230,138,.12),transparent 36%)}header{display:flex;justify-content:space-between;align-items:center;gap:12px}.route{font-size:11px;font-weight:800;letter-spacing:.06em;color:var(--accent)}h1{margin:2px 0 0;font-size:27px;line-height:1;letter-spacing:-.045em}.version{display:inline-block;margin-top:5px;font-size:9px;font-weight:900;letter-spacing:.08em;color:var(--accent);opacity:.8}.install{border:1px solid var(--line);background:var(--panel);color:var(--accent);font-size:11px;font-weight:850;padding:8px 11px;border-radius:10px;cursor:pointer}.hidden{display:none!important}.tabs{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:7px}.tab{height:34px;border:1px solid var(--line);border-radius:10px;background:#101315;color:var(--muted);font-size:12px;font-weight:900;letter-spacing:.04em;cursor:pointer}.tab.active{color:#07110d;background:var(--accent);border-color:var(--accent)}.panel{border:1px solid var(--line);background:linear-gradient(180deg,#15191b,var(--panel));border-radius:17px;padding:12px}.inputs{display:grid;grid-template-columns:1fr 1fr;gap:10px}.inputs label.wide{grid-column:1/-1}.inputs label>span{display:flex;justify-content:space-between;align-items:center;gap:6px;font-size:11px;font-weight:780;color:#c7cdd0;margin:0 2px 5px}.inputs small{font-size:8px;color:var(--muted);font-weight:900;letter-spacing:.07em}.field{height:45px;display:flex;align-items:center;border:1px solid var(--line);background:var(--field);border-radius:12px;overflow:hidden}.field:focus-within{border-color:var(--accent);box-shadow:0 0 0 2px rgba(0,230,138,.08)}.field.rate-highlight{background:linear-gradient(180deg,rgba(0,230,138,.18),rgba(0,230,138,.08));border-color:rgba(0,230,138,.62);box-shadow:inset 0 0 0 1px rgba(0,230,138,.06)}.field.rate-highlight input{color:#f7fffb}.field.rate-highlight b{color:var(--accent)}.field input{width:100%;min-width:0;height:100%;border:0;outline:0;background:transparent;color:var(--text);padding:0 11px;font-size:16px;font-weight:800}.field input::placeholder{color:#535b60;font-size:12px;font-weight:650}.field b{font-size:9px;color:var(--muted);padding:0 10px}.received{display:block;margin:5px 3px 0;color:var(--muted);font-size:10px;line-height:1.15;font-style:normal;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.result-card{min-height:0;border:1px solid #284439;background:linear-gradient(180deg,#142119,#101613);border-radius:18px;padding:14px;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center}.result-card span{font-size:10px;color:var(--muted);font-weight:900;letter-spacing:.12em}.result-card strong{font-size:clamp(30px,8vw,46px);line-height:1.03;margin:8px 0 4px;letter-spacing:-.055em}.result-card b{font-size:16px}.good{color:var(--accent)!important}.bad{color:var(--bad)!important}.neutral{color:var(--warn)!important}\n@media(max-width:390px){.app{padding-left:10px;padding-right:10px;gap:8px}.panel{padding:10px}.inputs{gap:8px}.field{height:41px}.field input{font-size:14px}h1{font-size:23px}.received{font-size:9px;margin-top:4px}.result-card{padding:11px}.result-card strong{font-size:29px}.tab{height:31px;font-size:11px}}\n@media(max-height:690px){.app{gap:7px;padding-top:7px;padding-bottom:7px}.route{font-size:9px}h1{font-size:20px}.tabs{gap:5px}.tab{height:28px;font-size:10px}.panel{padding:8px}.inputs{gap:6px}.inputs label>span{font-size:9px;margin-bottom:3px}.field{height:33px}.field input{font-size:13px}.received{font-size:8px;margin-top:3px}.result-card{padding:8px}.result-card strong{font-size:26px;margin:4px 0 2px}}\n.fx-tools{grid-column:1/-1;border-top:1px solid var(--line);padding-top:9px;min-width:0}\n.fx-controls{display:flex;align-items:center;justify-content:space-between;gap:8px}\n.fx-toggle,.fx-refresh{min-height:32px;border:1px solid var(--line);border-radius:9px;background:var(--field);color:var(--muted);padding:5px 10px;font-size:11px;font-weight:800;cursor:pointer}\n.fx-toggle{display:inline-flex;align-items:center;gap:7px}\n.fx-toggle.enabled{color:var(--accent);border-color:#285d46;background:#11251c}\n.fx-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:currentColor}\n.fx-refresh{color:var(--text)}.fx-refresh:disabled{opacity:.45;cursor:default}\n.fx-tools p{margin:5px 0 0;font-size:9px;line-height:1.4;color:var(--muted);overflow-wrap:anywhere}\n.fx-tools a{color:var(--muted);text-underline-offset:2px}\n.fx-tools .fx-warning{color:var(--warn)}\n.field.auto-rate{border-style:dashed}.field.auto-rate input{cursor:default}\n.rub-note{grid-column:1/-1;margin:0 2px;color:var(--warn);font-size:10px;line-height:1.35}\n.result-note{margin:8px 0 0;font-size:9px;line-height:1.4;color:var(--muted);font-weight:500;letter-spacing:0}\n.usd-reference{display:block;margin:4px 3px 0;font-size:10px;line-height:1.35;font-style:normal;font-weight:650;color:#73c6a3;overflow-wrap:anywhere}\n.usd-reference.stale{color:var(--warn)}\nbutton:focus-visible{outline:2px solid var(--accent);outline-offset:3px}\n@media(max-width:390px){.tabs{gap:5px}.fx-toggle,.fx-refresh{font-size:10px;padding:5px 8px}}\n@media(max-height:690px){.fx-tools{padding-top:6px}.fx-tools p{font-size:8px;margin-top:3px}.fx-toggle,.fx-refresh{min-height:28px;font-size:10px}.rub-note{font-size:9px}.result-note{font-size:8px;margin-top:5px}.usd-reference{font-size:9px;margin-top:3px}}\n\n</style>\n</head>\n<body>\n  <main class=\"app\">\n    <header>\n      <div>\n        <div class=\"route\" id=\"routeText\">VND → USDT → EUR → VND</div>\n        <h1>Tiền của Điền</h1><span class=\"version\">v18 · TỶ GIÁ USD THAM KHẢO</span>\n      </div>\n      <button id=\"installBtn\" class=\"install hidden\">Cài app</button>\n    </header>\n\n    <nav class=\"tabs\" aria-label=\"Loại vòng tiền\">\n      <button type=\"button\" class=\"tab\" data-page=\"cad\">CAD</button>\n      <button type=\"button\" class=\"tab\" data-page=\"try\">TRY</button>\n      <button type=\"button\" class=\"tab active\" data-page=\"vnd\">VND</button>\n      <button type=\"button\" class=\"tab\" data-page=\"jpy\">JPY</button>\n      <button type=\"button\" class=\"tab\" data-page=\"rub\">RUB</button>\n    </nav>\n\n    <section class=\"panel inputs\">\n      <label class=\"wide\">\n        <span>Vốn ban đầu</span>\n        <div class=\"field\"><input aria-label=\"Vốn ban đầu\" id=\"capital\" inputmode=\"numeric\" value=\"100.000.000\"><b id=\"capitalUnit\">VND</b></div>\n      </label>\n\n      <label>\n        <span id=\"rate1Label\">USDT / VND <small>P2P</small></span>\n        <div class=\"field\"><input id=\"rate1\" inputmode=\"decimal\" placeholder=\"Ví dụ 26.300\"><b id=\"rate1Unit\">VND</b></div>\n        <em class=\"received\" id=\"received1\">Nhận: — USDT</em>\n        <em class=\"usd-reference hidden\" id=\"usdReference1\" aria-live=\"polite\"></em>\n      </label>\n\n      <label>\n        <span id=\"rate2Label\">USDT / EUR <small>P2P</small></span>\n        <div class=\"field\"><input id=\"rate2\" inputmode=\"decimal\" placeholder=\"Ví dụ 0,8600\"><b id=\"rate2Unit\">EUR</b></div>\n        <em class=\"received\" id=\"received2\">Nhận: — EUR</em>\n        <em class=\"usd-reference hidden\" id=\"usdReference2\" aria-live=\"polite\"></em>\n      </label>\n\n      <label class=\"wide\">\n        <span id=\"rate3Label\">EUR / VND</span>\n        <div class=\"field\"><input id=\"rate3\" inputmode=\"decimal\" placeholder=\"Ví dụ 30.700\"><b id=\"rate3Unit\">VND</b></div>\n        <em class=\"received\" id=\"received3\">Nhận: — VND</em>\n        <em class=\"usd-reference hidden\" id=\"usdReference3\" aria-live=\"polite\"></em>\n      </label>\n\n      <p id=\"rubNote\" class=\"rub-note hidden\">Bước USD/RUB quy ước 1 USDT = 1 USD. Giá mua USDT thực tế có thể khác.</p>\n      <div class=\"fx-tools\">\n        <div class=\"fx-controls\">\n          <button type=\"button\" id=\"fxAuto\" class=\"fx-toggle enabled\" role=\"switch\" aria-checked=\"true\" aria-label=\"Tự động điền các ô tỷ giá pháp định\"><i class=\"fx-dot\" aria-hidden=\"true\"></i><span id=\"fxAutoText\">Tự điền: Bật</span></button>\n          <button type=\"button\" id=\"fxRefresh\" class=\"fx-refresh\">Cập nhật</button>\n        </div>\n        <p id=\"fxStatus\" role=\"status\" aria-live=\"polite\">Đang lấy tỷ giá pháp định…</p>\n        <p><a href=\"https://www.exchangerate-api.com\" target=\"_blank\" rel=\"noopener noreferrer\">Rates By Exchange Rate API</a> · Tham khảo, cập nhật hằng ngày.</p>\n      </div>\n    </section>\n\n    <section class=\"result-card\">\n      <span>LÃI / LỖ</span>\n      <strong id=\"profit\">—</strong>\n      <b id=\"roi\">—</b>\n      <p id=\"resultNote\" class=\"result-note\">Ước tính · chưa trừ phí giao dịch</p>\n    </section>\n  </main>\n\n\n\n<script>\n'use strict';\nconst $ = id => document.getElementById(id);\nconst fmt0 = new Intl.NumberFormat('vi-VN', {maximumFractionDigits: 0});\nconst fmt2 = new Intl.NumberFormat('vi-VN', {maximumFractionDigits: 2});\nconst fmt4 = new Intl.NumberFormat('vi-VN', {maximumFractionDigits: 4});\nconst fmtRate = new Intl.NumberFormat('vi-VN', {useGrouping: false, maximumFractionDigits: 6});\nconst memoryStorage = new Map();\nfunction stored(name) {\n  try { return localStorage.getItem(name) ?? memoryStorage.get(name) ?? null; }\n  catch (_) { return memoryStorage.get(name) ?? null; }\n}\nfunction remember(name, value) {\n  memoryStorage.set(name, String(value));\n  try { localStorage.setItem(name, String(value)); } catch (_) {}\n}\n\n// A/B always means the amount of B for ONE unit of A.\n// Only explicit fiat pairs have an fx property. USDT is never fetched or\n// inferred from the provider's USD rate, except the disclosed RUB convention.\nconst PAGES = {\n  cad: {\n    route: 'CAD → EUR → USDT → CAD', capital: 'CAD', highlight: 0,\n    rates: [\n      {label: 'EUR / CAD', unit: 'CAD', placeholder: 'Ví dụ 1,5500', receive: 'EUR', op: 'divide', fx: ['EUR', 'CAD']},\n      {label: 'USDT / EUR', tag: 'P2P', unit: 'EUR', placeholder: 'Ví dụ 0,8900', receive: 'USDT', op: 'divide'},\n      {label: 'USDT / CAD', tag: 'P2P', unit: 'CAD', placeholder: 'Ví dụ 1,3900', receive: 'CAD', op: 'multiply'}\n    ]\n  },\n  try: {\n    route: 'TRY → EUR → USDT → TRY', capital: 'TRY', highlight: 3,\n    rates: [\n      {label: 'EUR / TRY', unit: 'TRY', placeholder: 'Ví dụ 48,50', receive: 'EUR', op: 'divide', fx: ['EUR', 'TRY']},\n      {label: 'USDT / EUR', tag: 'P2P', unit: 'EUR', placeholder: 'Ví dụ 0,8550', receive: 'USDT', op: 'divide'},\n      {label: 'USDT / TRY', tag: 'P2P', unit: 'TRY', placeholder: 'Ví dụ 41,50', receive: 'TRY', op: 'multiply'}\n    ]\n  },\n  vnd: {\n    route: 'VND → USDT → EUR → VND', capital: 'VND', highlight: 1,\n    rates: [\n      {label: 'USDT / VND', tag: 'P2P', unit: 'VND', placeholder: 'Ví dụ 26.300', receive: 'USDT', op: 'divide', vndThousands: true},\n      {label: 'USDT / EUR', tag: 'P2P', unit: 'EUR', placeholder: 'Ví dụ 0,8600', receive: 'EUR', op: 'multiply'},\n      {label: 'EUR / VND', unit: 'VND', placeholder: 'Ví dụ 30.700', receive: 'VND', op: 'multiply', vndThousands: true, fx: ['EUR', 'VND']}\n    ]\n  },\n  jpy: {\n    route: 'VND → JPY → USDT → VND', capital: 'VND', highlight: 2,\n    rates: [\n      {label: 'JPY / VND', unit: 'VND', placeholder: 'Ví dụ 165,50', receive: 'JPY', op: 'divide', fx: ['JPY', 'VND']},\n      {label: 'USDT / JPY', tag: 'P2P', unit: 'JPY', placeholder: 'Ví dụ 155,00', receive: 'USDT', op: 'divide'},\n      {label: 'USDT / VND', tag: 'P2P', unit: 'VND', placeholder: 'Ví dụ 26.300', receive: 'VND', op: 'multiply', vndThousands: true}\n    ]\n  },\n  rub: {\n    route: 'VND → RUB → USDT → VND', capital: 'VND', highlight: 3,\n    rates: [\n      {label: 'RUB / VND', unit: 'VND', placeholder: 'Ví dụ 310,50', receive: 'RUB', op: 'divide', fx: ['RUB', 'VND']},\n      {label: 'USD / RUB', unit: 'RUB', placeholder: 'Ví dụ 83,50', receive: 'USDT', op: 'divide', fx: ['USD', 'RUB']},\n      {label: 'USDT / VND', tag: 'P2P', unit: 'VND', placeholder: 'Ví dụ 26.300', receive: 'VND', op: 'multiply', vndThousands: true}\n    ]\n  }\n};\n\nfunction migrateVndTab() {\n  const legacy = {capital: 'tiendien_capitalVnd', rate1: 'tiendien_usdtVnd', rate2: 'tiendien_usdtEur', rate3: 'tiendien_eurVnd'};\n  for (const id of ['capital', 'rate1', 'rate2', 'rate3']) {\n    const target = `tiendien_vnd_${id}`;\n    const value = stored(`tiendien_eur_${id}`) ?? stored(legacy[id]);\n    if (stored(target) === null && value !== null) remember(target, value);\n  }\n}\nmigrateVndTab();\n// CAD now has a different starting currency and different quote positions.\n// Keep its new inputs separate so VND capital / unrelated old quotes cannot\n// acquire a new currency label. Only the unchanged USDT/CAD quote migrates.\nconst oldUsdtCad = stored('tiendien_cad_rate2');\nif (stored('tiendien_cad_eur_usdt_rate3') === null && oldUsdtCad !== null) {\n  remember('tiendien_cad_eur_usdt_rate3', oldUsdtCad);\n}\nlet page = stored('tiendien_page');\nif (page === 'eur' || !PAGES[page]) page = 'vnd';\n\nfunction capitalNum(value) {\n  const number = Number(String(value ?? '').replace(/\\D/g, ''));\n  return Number.isFinite(number) ? number : 0;\n}\nfunction rateNum(value, thousands = false) {\n  let text = String(value ?? '').trim().replace(/\\s/g, '');\n  if (!text) return 0;\n  if (text.includes(',')) text = text.replace(/\\./g, '').replace(',', '.');\n  else if (thousands && /^\\d{1,3}(?:\\.\\d{3})+$/.test(text)) text = text.replace(/\\./g, '');\n  const number = Number(text);\n  return Number.isFinite(number) ? number : 0;\n}\nfunction formatCapital() {\n  const digits = $('capital').value.replace(/\\D/g, '');\n  $('capital').value = digits ? fmt0.format(capitalNum(digits)) : '';\n}\nfunction money(value, unit) { return `${value >= 0 ? '+' : '−'}${(unit === 'CAD' ? fmt2 : fmt0).format(Math.abs(value))} ${unit}`; }\nfunction pct(value) { return `${value >= 0 ? '+' : ''}${fmt2.format(value)}%`; }\nfunction tone(element, value) {\n  element.classList.remove('good', 'bad', 'neutral');\n  element.classList.add(value > 0.01 ? 'good' : value < -0.01 ? 'bad' : 'neutral');\n}\nfunction formatReceived(value, unit) {\n  if (!(value > 0 && Number.isFinite(value))) return `Nhận: — ${unit}`;\n  return `Nhận: ${(unit === 'VND' || unit === 'TRY' ? fmt2 : fmt4).format(value)} ${unit}`;\n}\nfunction key(name) { return `tiendien_${page === 'cad' ? 'cad_eur_usdt' : page}_${name}`; }\nfunction save() {\n  remember(key('capital'), $('capital').value);\n  PAGES[page].rates.forEach((rate, index) => {\n    // Keep the last manually entered fiat quote separate from the live cache.\n    if (!fxEnabled || !rate.fx) remember(key(`rate${index + 1}`), $(`rate${index + 1}`).value);\n  });\n}\n\nconst FX_URL = 'https://open.er-api.com/v6/latest/USD';\nconst FX_CACHE_KEY = 'tiendien_fx_usd_v16';\nconst FX_AUTO_KEY = 'tiendien_fx_auto_v16';\nconst FX_ATTEMPT_KEY = 'tiendien_fx_attempt_v16';\nconst FX_CODES = ['USD', 'EUR', 'CAD', 'TRY', 'JPY', 'VND', 'RUB'];\nlet fxEnabled = stored(FX_AUTO_KEY) !== '0';\nlet fxError = '';\nlet fxBusy = false;\nlet fxRequest = null;\nlet fxLastAttempt = Number(stored(FX_ATTEMPT_KEY)) || 0;\n\nfunction validateFx(payload) {\n  if (!payload || payload.result !== 'success' || payload.base_code !== 'USD' || !payload.rates) throw new Error('Invalid FX data');\n  for (const code of FX_CODES) {\n    const rate = payload.rates[code];\n    if (typeof rate !== 'number' || !Number.isFinite(rate) || rate <= 0) throw new Error('Invalid FX rate');\n  }\n  if (Math.abs(payload.rates.USD - 1) > 0.000001) throw new Error('Invalid FX base');\n  const last = payload.time_last_update_unix;\n  const next = payload.time_next_update_unix;\n  if (!Number.isFinite(last) || !Number.isFinite(next) || last <= 0 || next <= last || last * 1000 > Date.now() + 300000) throw new Error('Invalid FX timestamp');\n  return payload;\n}\nfunction readFxCache() {\n  try {\n    const cached = JSON.parse(stored(FX_CACHE_KEY) || 'null');\n    if (!cached || !Number.isFinite(cached.fetchedAt) || cached.fetchedAt <= 0 || cached.fetchedAt > Date.now() + 300000) return null;\n    validateFx(cached.payload);\n    return cached;\n  } catch (_) { return null; }\n}\nlet fxSnapshot = readFxCache();\nfunction fxIsDue() {\n  return !fxSnapshot || Date.now() >= fxSnapshot.payload.time_next_update_unix * 1000 + 60000;\n}\nfunction crossRate(base, quote) {\n  if (!fxSnapshot) return 0;\n  return fxSnapshot.payload.rates[quote] / fxSnapshot.payload.rates[base];\n}\nfunction renderUsdReferences() {\n  // Benchmarks are read-only display data. Never substitute them for P2P\n  // USDT inputs or use them in the route's received/profit calculations.\n  PAGES[page].rates.forEach((rate, index) => {\n    const reference = $(`usdReference${index + 1}`);\n    const pair = rate.label.split('/').map(code => code.trim());\n    const hasUsdt = pair.includes('USDT');\n    reference.classList.toggle('hidden', !hasUsdt);\n    reference.classList.toggle('stale', hasUsdt && Boolean(fxSnapshot) && (fxIsDue() || Boolean(fxError)));\n    if (!hasUsdt) {\n      reference.textContent = '';\n      reference.setAttribute('title', '');\n      return;\n    }\n    const currency = pair.find(code => code !== 'USDT');\n    const label = `USD / ${currency}`;\n    if (fxSnapshot) {\n      const value = crossRate('USD', currency);\n      const qualifier = fxError ? ' · giá lưu' : fxIsDue() ? ' · giá cũ' : '';\n      reference.textContent = `${label}: ${fmt4.format(value)}${qualifier}`;\n      const timestamp = new Date(fxSnapshot.payload.time_last_update_unix * 1000).toLocaleString('vi-VN', {timeZone: 'Asia/Ho_Chi_Minh'});\n      reference.setAttribute('title', `1 USD = ${fmt4.format(value)} ${currency}. Tỷ giá tham khảo từ ExchangeRate-API, lúc ${timestamp} (giờ VN).`);\n    } else {\n      reference.textContent = `${label}: ${fxBusy ? 'đang tải…' : fxError ? 'chưa tải được' : '—'}`;\n      reference.setAttribute('title', 'Chưa có dữ liệu tỷ giá pháp định; không suy ra từ giá USDT nhập tay.');\n    }\n  });\n}\nfunction applyFxToPage() {\n  if (!fxEnabled || !fxSnapshot) return;\n  PAGES[page].rates.forEach((rate, index) => {\n    if (!rate.fx) return;\n    const value = crossRate(...rate.fx);\n    const input = $(`rate${index + 1}`);\n    input.value = fmtRate.format(value);\n    input.dataset.fxSource = 'api';\n  });\n}\nfunction renderFxStatus() {\n  $('fxAuto').setAttribute('aria-checked', String(fxEnabled));\n  $('fxAuto').classList.toggle('enabled', fxEnabled);\n  $('fxAutoText').textContent = `Tự điền: ${fxEnabled ? 'Bật' : 'Tắt'}`;\n  $('fxRefresh').disabled = fxBusy;\n  $('fxRefresh').textContent = fxBusy ? 'Đang tải…' : 'Cập nhật';\n  $('fxStatus').classList.toggle('fx-warning', Boolean(fxError) || (fxIsDue() && Boolean(fxSnapshot)));\n  const manualPrefix = fxEnabled ? '' : 'Ô giá nhập tay. ';\n  if (fxSnapshot) {\n    const date = new Intl.DateTimeFormat('vi-VN', {dateStyle: 'short', timeStyle: 'short', timeZone: 'Asia/Ho_Chi_Minh'}).format(new Date(fxSnapshot.payload.time_last_update_unix * 1000));\n    const prefix = fxError ? `${fxError} · đang dùng giá lưu lúc ` : fxIsDue() ? 'Giá cũ từ ' : 'Tỷ giá lúc ';\n    $('fxStatus').textContent = `${manualPrefix}${prefix}${date} (giờ VN). USDT nhập tay.`;\n  } else if (fxError) {\n    $('fxStatus').textContent = `${manualPrefix}${fxError}. ${fxEnabled ? 'Tắt Tự điền để nhập tay.' : 'USD tham khảo chưa có dữ liệu.'}`;\n  } else {\n    $('fxStatus').textContent = manualPrefix + (fxBusy ? 'Đang lấy tỷ giá pháp định… USDT nhập tay.' : 'Chưa có tỷ giá tự động. USDT nhập tay.');\n  }\n  PAGES[page].rates.forEach((rate, index) => {\n    const input = $(`rate${index + 1}`);\n    const automatic = Boolean(rate.fx && fxEnabled);\n    input.readOnly = automatic;\n    input.setAttribute('aria-readonly', String(automatic));\n    const tag = rate.fx ? (automatic ? (fxSnapshot ? 'TỰ ĐỘNG' : input.value ? 'ĐÃ LƯU' : 'CHỜ GIÁ') : 'NHẬP TAY') : rate.tag;\n    $(`rate${index + 1}Label`).innerHTML = `${rate.label}${tag ? ` <small>${tag}</small>` : ''}`;\n    input.closest('.field').classList.toggle('auto-rate', automatic);\n  });\n  $('resultNote').textContent = fxEnabled ? 'Ước tính theo tỷ giá tham khảo · chưa trừ phí' : 'Ước tính · chưa trừ phí giao dịch';\n  renderUsdReferences();\n}\n\nasync function refreshFx({force = false} = {}) {\n  // The feed also powers USD reference lines while auto-fill is disabled.\n  if (fxRequest) return fxRequest;\n  if (!force && !fxIsDue()) { renderFxStatus(); return; }\n  const elapsed = Date.now() - fxLastAttempt;\n  // One scheduled attempt every five minutes when offline/unavailable; manual\n  // refresh is limited to once a minute. A fresh daily snapshot needs no poll.\n  if (elapsed >= 0 && elapsed < (force ? 60000 : 300000)) { renderFxStatus(); return; }\n  fxLastAttempt = Date.now();\n  remember(FX_ATTEMPT_KEY, fxLastAttempt);\n  fxBusy = true;\n  renderFxStatus();\n  fxRequest = (async () => {\n    const controller = new AbortController();\n    const timeout = setTimeout(() => controller.abort(), 10000);\n    try {\n      const response = await fetch(FX_URL, {cache: 'no-store', credentials: 'omit', signal: controller.signal});\n      if (!response.ok) throw new Error(response.status === 429 ? 'RATE_LIMIT' : 'FETCH_FAILED');\n      const payload = validateFx(await response.json());\n      if (fxSnapshot && payload.time_last_update_unix < fxSnapshot.payload.time_last_update_unix) throw new Error('Older FX response');\n      fxSnapshot = {payload, fetchedAt: Date.now()};\n      remember(FX_CACHE_KEY, JSON.stringify(fxSnapshot));\n      fxError = '';\n      // The user may have switched tabs or disabled auto while fetch awaited.\n      if (fxEnabled) { applyFxToPage(); calculate(); }\n    } catch (error) {\n      fxError = error.message === 'RATE_LIMIT' ? 'Nguồn đang giới hạn truy cập' : 'Không tải được tỷ giá';\n    } finally {\n      clearTimeout(timeout);\n      fxBusy = false;\n      fxRequest = null;\n      renderFxStatus();\n    }\n  })();\n  return fxRequest;\n}\n\nfunction restorePage() {\n  $('capital').value = stored(key('capital')) ?? (page === 'cad' ? '10.000' : page === 'try' ? '100.000' : '100.000.000');\n  ['rate1', 'rate2', 'rate3'].forEach(id => {\n    $(id).value = stored(key(id)) ?? '';\n    delete $(id).dataset.fxSource;\n  });\n  formatCapital();\n}\nfunction renderPage() {\n  const config = PAGES[page];\n  $('routeText').textContent = config.route;\n  $('capitalUnit').textContent = config.capital;\n  config.rates.forEach((rate, index) => {\n    const input = $(`rate${index + 1}`);\n    $(`rate${index + 1}Unit`).textContent = rate.unit;\n    input.placeholder = rate.placeholder;\n    input.setAttribute('aria-label', `${rate.label}: số ${rate.unit} cho một ${rate.label.split(' / ')[0]}`);\n    input.closest('.field').classList.toggle('rate-highlight', index + 1 === config.highlight);\n  });\n  document.querySelectorAll('.tab').forEach(button => {\n    const active = button.dataset.page === page;\n    button.classList.toggle('active', active);\n    button.setAttribute('aria-pressed', String(active));\n  });\n  $('rubNote').classList.toggle('hidden', page !== 'rub');\n  remember('tiendien_page', page);\n  restorePage();\n  applyFxToPage();\n  renderFxStatus();\n  calculate();\n}\nfunction calculate() {\n  const config = PAGES[page];\n  const capital = capitalNum($('capital').value);\n  let amount = capital;\n  config.rates.forEach((rate, index) => {\n    const quote = rateNum($(`rate${index + 1}`).value, Boolean(rate.vndThousands));\n    amount = amount > 0 && quote > 0 ? (rate.op === 'divide' ? amount / quote : amount * quote) : 0;\n    if (!Number.isFinite(amount)) amount = 0;\n    $(`received${index + 1}`).textContent = formatReceived(amount, rate.receive);\n  });\n  if (!(capital > 0 && amount > 0)) {\n    $('profit').textContent = '—'; $('roi').textContent = '—';\n    $('profit').className = ''; $('roi').className = '';\n  } else {\n    const profit = amount - capital;\n    const roi = profit / capital * 100;\n    if (Number.isFinite(profit) && Number.isFinite(roi)) {\n      $('profit').textContent = money(profit, config.capital);\n      $('roi').textContent = pct(roi);\n      tone($('profit'), profit); tone($('roi'), profit);\n    } else {\n      $('profit').textContent = '—'; $('roi').textContent = '—';\n      $('profit').className = ''; $('roi').className = '';\n    }\n  }\n  save();\n}\n\n$('capital').addEventListener('input', () => { formatCapital(); calculate(); });\n['rate1', 'rate2', 'rate3'].forEach(id => $(id).addEventListener('input', calculate));\ndocument.querySelectorAll('.tab').forEach(button => button.addEventListener('click', () => {\n  save(); page = button.dataset.page; renderPage(); refreshFx();\n}));\n$('fxAuto').addEventListener('click', () => {\n  save();\n  fxEnabled = !fxEnabled;\n  remember(FX_AUTO_KEY, fxEnabled ? '1' : '0');\n  if (fxEnabled) applyFxToPage();\n  else {\n    PAGES[page].rates.forEach((rate, index) => {\n      if (!rate.fx) return;\n      const manual = stored(key(`rate${index + 1}`));\n      if (manual !== null) $(`rate${index + 1}`).value = manual;\n      delete $(`rate${index + 1}`).dataset.fxSource;\n    });\n  }\n  renderFxStatus(); calculate();\n  if (fxEnabled) refreshFx();\n});\n$('fxRefresh').addEventListener('click', () => refreshFx({force: true}));\nwindow.addEventListener('online', () => refreshFx());\ndocument.addEventListener('visibilitychange', () => { if (!document.hidden) refreshFx(); });\nsetInterval(() => { if (!document.hidden) refreshFx(); }, 60000);\n\nlet deferredPrompt = null;\nwindow.addEventListener('beforeinstallprompt', event => {\n  event.preventDefault(); deferredPrompt = event; $('installBtn').classList.remove('hidden');\n});\n$('installBtn').addEventListener('click', async () => {\n  if (!deferredPrompt) return;\n  deferredPrompt.prompt(); await deferredPrompt.userChoice;\n  deferredPrompt = null; $('installBtn').classList.add('hidden');\n});\n\n// Retire this app's old cache without touching other apps on the same origin.\n(async () => {\n  try {\n    if ('serviceWorker' in navigator) {\n      const scope = new URL('./', location.href).href;\n      const registrations = await navigator.serviceWorker.getRegistrations();\n      for (const registration of registrations) if (registration.scope === scope) await registration.unregister();\n    }\n    if ('caches' in window) {\n      for (const name of await caches.keys()) if (/^(tien-cua-dien|tiendien)[-_]/.test(name)) await caches.delete(name);\n    }\n  } catch (_) {}\n})();\nrenderPage();\nrefreshFx();\n\n</script>\n</body>\n</html>\n"},"/v15.html":{"type":"text/html; charset=utf-8","body":"<!doctype html>\n<html lang=\"vi\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta http-equiv=\"Cache-Control\" content=\"no-cache, no-store, must-revalidate\">\n  <meta http-equiv=\"Pragma\" content=\"no-cache\">\n  <meta http-equiv=\"Expires\" content=\"0\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n  <meta name=\"theme-color\" content=\"#090b0c\">\n  <meta name=\"color-scheme\" content=\"dark\">\n  <title>Tiền của Điền</title>\n  <link rel=\"manifest\" href=\"./manifest.webmanifest?v=18\">\n  <link rel=\"icon\" href=\"./icon.svg\" type=\"image/svg+xml\">\n<style>\n:root{--bg:#090b0c;--panel:#121517;--field:#0c0f11;--line:#252b2f;--text:#f4f7f8;--muted:#899197;--accent:#00e68a;--bad:#ff6670;--warn:#f2c14e}\n*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;background:var(--bg);overflow:auto}body{font-family:Inter,ui-sans-serif,system-ui,-apple-system,\"Segoe UI\",sans-serif;color:var(--text)}button,input{font:inherit}.app{height:100dvh;min-height:530px;max-width:620px;margin:0 auto;padding:max(12px,env(safe-area-inset-top)) 14px max(12px,env(safe-area-inset-bottom));display:grid;grid-template-rows:auto auto auto minmax(115px,1fr);gap:10px;background:radial-gradient(circle at 90% -10%,rgba(0,230,138,.12),transparent 36%)}header{display:flex;justify-content:space-between;align-items:center;gap:12px}.route{font-size:11px;font-weight:800;letter-spacing:.06em;color:var(--accent)}h1{margin:2px 0 0;font-size:27px;line-height:1;letter-spacing:-.045em}.version{display:inline-block;margin-top:5px;font-size:9px;font-weight:900;letter-spacing:.08em;color:var(--accent);opacity:.8}.install{border:1px solid var(--line);background:var(--panel);color:var(--accent);font-size:11px;font-weight:850;padding:8px 11px;border-radius:10px;cursor:pointer}.hidden{display:none!important}.tabs{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:7px}.tab{height:34px;border:1px solid var(--line);border-radius:10px;background:#101315;color:var(--muted);font-size:12px;font-weight:900;letter-spacing:.04em;cursor:pointer}.tab.active{color:#07110d;background:var(--accent);border-color:var(--accent)}.panel{border:1px solid var(--line);background:linear-gradient(180deg,#15191b,var(--panel));border-radius:17px;padding:12px}.inputs{display:grid;grid-template-columns:1fr 1fr;gap:10px}.inputs label.wide{grid-column:1/-1}.inputs label>span{display:flex;justify-content:space-between;align-items:center;gap:6px;font-size:11px;font-weight:780;color:#c7cdd0;margin:0 2px 5px}.inputs small{font-size:8px;color:var(--muted);font-weight:900;letter-spacing:.07em}.field{height:45px;display:flex;align-items:center;border:1px solid var(--line);background:var(--field);border-radius:12px;overflow:hidden}.field:focus-within{border-color:var(--accent);box-shadow:0 0 0 2px rgba(0,230,138,.08)}.field.rate-highlight{background:linear-gradient(180deg,rgba(0,230,138,.18),rgba(0,230,138,.08));border-color:rgba(0,230,138,.62);box-shadow:inset 0 0 0 1px rgba(0,230,138,.06)}.field.rate-highlight input{color:#f7fffb}.field.rate-highlight b{color:var(--accent)}.field input{width:100%;min-width:0;height:100%;border:0;outline:0;background:transparent;color:var(--text);padding:0 11px;font-size:16px;font-weight:800}.field input::placeholder{color:#535b60;font-size:12px;font-weight:650}.field b{font-size:9px;color:var(--muted);padding:0 10px}.received{display:block;margin:5px 3px 0;color:var(--muted);font-size:10px;line-height:1.15;font-style:normal;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.result-card{min-height:0;border:1px solid #284439;background:linear-gradient(180deg,#142119,#101613);border-radius:18px;padding:14px;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center}.result-card span{font-size:10px;color:var(--muted);font-weight:900;letter-spacing:.12em}.result-card strong{font-size:clamp(30px,8vw,46px);line-height:1.03;margin:8px 0 4px;letter-spacing:-.055em}.result-card b{font-size:16px}.good{color:var(--accent)!important}.bad{color:var(--bad)!important}.neutral{color:var(--warn)!important}\n@media(max-width:390px){.app{padding-left:10px;padding-right:10px;gap:8px}.panel{padding:10px}.inputs{gap:8px}.field{height:41px}.field input{font-size:14px}h1{font-size:23px}.received{font-size:9px;margin-top:4px}.result-card{padding:11px}.result-card strong{font-size:29px}.tab{height:31px;font-size:11px}}\n@media(max-height:690px){.app{gap:7px;padding-top:7px;padding-bottom:7px}.route{font-size:9px}h1{font-size:20px}.tabs{gap:5px}.tab{height:28px;font-size:10px}.panel{padding:8px}.inputs{gap:6px}.inputs label>span{font-size:9px;margin-bottom:3px}.field{height:33px}.field input{font-size:13px}.received{font-size:8px;margin-top:3px}.result-card{padding:8px}.result-card strong{font-size:26px;margin:4px 0 2px}}\n.fx-tools{grid-column:1/-1;border-top:1px solid var(--line);padding-top:9px;min-width:0}\n.fx-controls{display:flex;align-items:center;justify-content:space-between;gap:8px}\n.fx-toggle,.fx-refresh{min-height:32px;border:1px solid var(--line);border-radius:9px;background:var(--field);color:var(--muted);padding:5px 10px;font-size:11px;font-weight:800;cursor:pointer}\n.fx-toggle{display:inline-flex;align-items:center;gap:7px}\n.fx-toggle.enabled{color:var(--accent);border-color:#285d46;background:#11251c}\n.fx-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:currentColor}\n.fx-refresh{color:var(--text)}.fx-refresh:disabled{opacity:.45;cursor:default}\n.fx-tools p{margin:5px 0 0;font-size:9px;line-height:1.4;color:var(--muted);overflow-wrap:anywhere}\n.fx-tools a{color:var(--muted);text-underline-offset:2px}\n.fx-tools .fx-warning{color:var(--warn)}\n.field.auto-rate{border-style:dashed}.field.auto-rate input{cursor:default}\n.rub-note{grid-column:1/-1;margin:0 2px;color:var(--warn);font-size:10px;line-height:1.35}\n.result-note{margin:8px 0 0;font-size:9px;line-height:1.4;color:var(--muted);font-weight:500;letter-spacing:0}\n.usd-reference{display:block;margin:4px 3px 0;font-size:10px;line-height:1.35;font-style:normal;font-weight:650;color:#73c6a3;overflow-wrap:anywhere}\n.usd-reference.stale{color:var(--warn)}\nbutton:focus-visible{outline:2px solid var(--accent);outline-offset:3px}\n@media(max-width:390px){.tabs{gap:5px}.fx-toggle,.fx-refresh{font-size:10px;padding:5px 8px}}\n@media(max-height:690px){.fx-tools{padding-top:6px}.fx-tools p{font-size:8px;margin-top:3px}.fx-toggle,.fx-refresh{min-height:28px;font-size:10px}.rub-note{font-size:9px}.result-note{font-size:8px;margin-top:5px}.usd-reference{font-size:9px;margin-top:3px}}\n\n</style>\n</head>\n<body>\n  <main class=\"app\">\n    <header>\n      <div>\n        <div class=\"route\" id=\"routeText\">VND → USDT → EUR → VND</div>\n        <h1>Tiền của Điền</h1><span class=\"version\">v18 · TỶ GIÁ USD THAM KHẢO</span>\n      </div>\n      <button id=\"installBtn\" class=\"install hidden\">Cài app</button>\n    </header>\n\n    <nav class=\"tabs\" aria-label=\"Loại vòng tiền\">\n      <button type=\"button\" class=\"tab\" data-page=\"cad\">CAD</button>\n      <button type=\"button\" class=\"tab\" data-page=\"try\">TRY</button>\n      <button type=\"button\" class=\"tab active\" data-page=\"vnd\">VND</button>\n      <button type=\"button\" class=\"tab\" data-page=\"jpy\">JPY</button>\n      <button type=\"button\" class=\"tab\" data-page=\"rub\">RUB</button>\n    </nav>\n\n    <section class=\"panel inputs\">\n      <label class=\"wide\">\n        <span>Vốn ban đầu</span>\n        <div class=\"field\"><input aria-label=\"Vốn ban đầu\" id=\"capital\" inputmode=\"numeric\" value=\"100.000.000\"><b id=\"capitalUnit\">VND</b></div>\n      </label>\n\n      <label>\n        <span id=\"rate1Label\">USDT / VND <small>P2P</small></span>\n        <div class=\"field\"><input id=\"rate1\" inputmode=\"decimal\" placeholder=\"Ví dụ 26.300\"><b id=\"rate1Unit\">VND</b></div>\n        <em class=\"received\" id=\"received1\">Nhận: — USDT</em>\n        <em class=\"usd-reference hidden\" id=\"usdReference1\" aria-live=\"polite\"></em>\n      </label>\n\n      <label>\n        <span id=\"rate2Label\">USDT / EUR <small>P2P</small></span>\n        <div class=\"field\"><input id=\"rate2\" inputmode=\"decimal\" placeholder=\"Ví dụ 0,8600\"><b id=\"rate2Unit\">EUR</b></div>\n        <em class=\"received\" id=\"received2\">Nhận: — EUR</em>\n        <em class=\"usd-reference hidden\" id=\"usdReference2\" aria-live=\"polite\"></em>\n      </label>\n\n      <label class=\"wide\">\n        <span id=\"rate3Label\">EUR / VND</span>\n        <div class=\"field\"><input id=\"rate3\" inputmode=\"decimal\" placeholder=\"Ví dụ 30.700\"><b id=\"rate3Unit\">VND</b></div>\n        <em class=\"received\" id=\"received3\">Nhận: — VND</em>\n        <em class=\"usd-reference hidden\" id=\"usdReference3\" aria-live=\"polite\"></em>\n      </label>\n\n      <p id=\"rubNote\" class=\"rub-note hidden\">Bước USD/RUB quy ước 1 USDT = 1 USD. Giá mua USDT thực tế có thể khác.</p>\n      <div class=\"fx-tools\">\n        <div class=\"fx-controls\">\n          <button type=\"button\" id=\"fxAuto\" class=\"fx-toggle enabled\" role=\"switch\" aria-checked=\"true\" aria-label=\"Tự động điền các ô tỷ giá pháp định\"><i class=\"fx-dot\" aria-hidden=\"true\"></i><span id=\"fxAutoText\">Tự điền: Bật</span></button>\n          <button type=\"button\" id=\"fxRefresh\" class=\"fx-refresh\">Cập nhật</button>\n        </div>\n        <p id=\"fxStatus\" role=\"status\" aria-live=\"polite\">Đang lấy tỷ giá pháp định…</p>\n        <p><a href=\"https://www.exchangerate-api.com\" target=\"_blank\" rel=\"noopener noreferrer\">Rates By Exchange Rate API</a> · Tham khảo, cập nhật hằng ngày.</p>\n      </div>\n    </section>\n\n    <section class=\"result-card\">\n      <span>LÃI / LỖ</span>\n      <strong id=\"profit\">—</strong>\n      <b id=\"roi\">—</b>\n      <p id=\"resultNote\" class=\"result-note\">Ước tính · chưa trừ phí giao dịch</p>\n    </section>\n  </main>\n\n\n\n<script>\n'use strict';\nconst $ = id => document.getElementById(id);\nconst fmt0 = new Intl.NumberFormat('vi-VN', {maximumFractionDigits: 0});\nconst fmt2 = new Intl.NumberFormat('vi-VN', {maximumFractionDigits: 2});\nconst fmt4 = new Intl.NumberFormat('vi-VN', {maximumFractionDigits: 4});\nconst fmtRate = new Intl.NumberFormat('vi-VN', {useGrouping: false, maximumFractionDigits: 6});\nconst memoryStorage = new Map();\nfunction stored(name) {\n  try { return localStorage.getItem(name) ?? memoryStorage.get(name) ?? null; }\n  catch (_) { return memoryStorage.get(name) ?? null; }\n}\nfunction remember(name, value) {\n  memoryStorage.set(name, String(value));\n  try { localStorage.setItem(name, String(value)); } catch (_) {}\n}\n\n// A/B always means the amount of B for ONE unit of A.\n// Only explicit fiat pairs have an fx property. USDT is never fetched or\n// inferred from the provider's USD rate, except the disclosed RUB convention.\nconst PAGES = {\n  cad: {\n    route: 'CAD → EUR → USDT → CAD', capital: 'CAD', highlight: 0,\n    rates: [\n      {label: 'EUR / CAD', unit: 'CAD', placeholder: 'Ví dụ 1,5500', receive: 'EUR', op: 'divide', fx: ['EUR', 'CAD']},\n      {label: 'USDT / EUR', tag: 'P2P', unit: 'EUR', placeholder: 'Ví dụ 0,8900', receive: 'USDT', op: 'divide'},\n      {label: 'USDT / CAD', tag: 'P2P', unit: 'CAD', placeholder: 'Ví dụ 1,3900', receive: 'CAD', op: 'multiply'}\n    ]\n  },\n  try: {\n    route: 'TRY → EUR → USDT → TRY', capital: 'TRY', highlight: 3,\n    rates: [\n      {label: 'EUR / TRY', unit: 'TRY', placeholder: 'Ví dụ 48,50', receive: 'EUR', op: 'divide', fx: ['EUR', 'TRY']},\n      {label: 'USDT / EUR', tag: 'P2P', unit: 'EUR', placeholder: 'Ví dụ 0,8550', receive: 'USDT', op: 'divide'},\n      {label: 'USDT / TRY', tag: 'P2P', unit: 'TRY', placeholder: 'Ví dụ 41,50', receive: 'TRY', op: 'multiply'}\n    ]\n  },\n  vnd: {\n    route: 'VND → USDT → EUR → VND', capital: 'VND', highlight: 1,\n    rates: [\n      {label: 'USDT / VND', tag: 'P2P', unit: 'VND', placeholder: 'Ví dụ 26.300', receive: 'USDT', op: 'divide', vndThousands: true},\n      {label: 'USDT / EUR', tag: 'P2P', unit: 'EUR', placeholder: 'Ví dụ 0,8600', receive: 'EUR', op: 'multiply'},\n      {label: 'EUR / VND', unit: 'VND', placeholder: 'Ví dụ 30.700', receive: 'VND', op: 'multiply', vndThousands: true, fx: ['EUR', 'VND']}\n    ]\n  },\n  jpy: {\n    route: 'VND → JPY → USDT → VND', capital: 'VND', highlight: 2,\n    rates: [\n      {label: 'JPY / VND', unit: 'VND', placeholder: 'Ví dụ 165,50', receive: 'JPY', op: 'divide', fx: ['JPY', 'VND']},\n      {label: 'USDT / JPY', tag: 'P2P', unit: 'JPY', placeholder: 'Ví dụ 155,00', receive: 'USDT', op: 'divide'},\n      {label: 'USDT / VND', tag: 'P2P', unit: 'VND', placeholder: 'Ví dụ 26.300', receive: 'VND', op: 'multiply', vndThousands: true}\n    ]\n  },\n  rub: {\n    route: 'VND → RUB → USDT → VND', capital: 'VND', highlight: 3,\n    rates: [\n      {label: 'RUB / VND', unit: 'VND', placeholder: 'Ví dụ 310,50', receive: 'RUB', op: 'divide', fx: ['RUB', 'VND']},\n      {label: 'USD / RUB', unit: 'RUB', placeholder: 'Ví dụ 83,50', receive: 'USDT', op: 'divide', fx: ['USD', 'RUB']},\n      {label: 'USDT / VND', tag: 'P2P', unit: 'VND', placeholder: 'Ví dụ 26.300', receive: 'VND', op: 'multiply', vndThousands: true}\n    ]\n  }\n};\n\nfunction migrateVndTab() {\n  const legacy = {capital: 'tiendien_capitalVnd', rate1: 'tiendien_usdtVnd', rate2: 'tiendien_usdtEur', rate3: 'tiendien_eurVnd'};\n  for (const id of ['capital', 'rate1', 'rate2', 'rate3']) {\n    const target = `tiendien_vnd_${id}`;\n    const value = stored(`tiendien_eur_${id}`) ?? stored(legacy[id]);\n    if (stored(target) === null && value !== null) remember(target, value);\n  }\n}\nmigrateVndTab();\n// CAD now has a different starting currency and different quote positions.\n// Keep its new inputs separate so VND capital / unrelated old quotes cannot\n// acquire a new currency label. Only the unchanged USDT/CAD quote migrates.\nconst oldUsdtCad = stored('tiendien_cad_rate2');\nif (stored('tiendien_cad_eur_usdt_rate3') === null && oldUsdtCad !== null) {\n  remember('tiendien_cad_eur_usdt_rate3', oldUsdtCad);\n}\nlet page = stored('tiendien_page');\nif (page === 'eur' || !PAGES[page]) page = 'vnd';\n\nfunction capitalNum(value) {\n  const number = Number(String(value ?? '').replace(/\\D/g, ''));\n  return Number.isFinite(number) ? number : 0;\n}\nfunction rateNum(value, thousands = false) {\n  let text = String(value ?? '').trim().replace(/\\s/g, '');\n  if (!text) return 0;\n  if (text.includes(',')) text = text.replace(/\\./g, '').replace(',', '.');\n  else if (thousands && /^\\d{1,3}(?:\\.\\d{3})+$/.test(text)) text = text.replace(/\\./g, '');\n  const number = Number(text);\n  return Number.isFinite(number) ? number : 0;\n}\nfunction formatCapital() {\n  const digits = $('capital').value.replace(/\\D/g, '');\n  $('capital').value = digits ? fmt0.format(capitalNum(digits)) : '';\n}\nfunction money(value, unit) { return `${value >= 0 ? '+' : '−'}${(unit === 'CAD' ? fmt2 : fmt0).format(Math.abs(value))} ${unit}`; }\nfunction pct(value) { return `${value >= 0 ? '+' : ''}${fmt2.format(value)}%`; }\nfunction tone(element, value) {\n  element.classList.remove('good', 'bad', 'neutral');\n  element.classList.add(value > 0.01 ? 'good' : value < -0.01 ? 'bad' : 'neutral');\n}\nfunction formatReceived(value, unit) {\n  if (!(value > 0 && Number.isFinite(value))) return `Nhận: — ${unit}`;\n  return `Nhận: ${(unit === 'VND' || unit === 'TRY' ? fmt2 : fmt4).format(value)} ${unit}`;\n}\nfunction key(name) { return `tiendien_${page === 'cad' ? 'cad_eur_usdt' : page}_${name}`; }\nfunction save() {\n  remember(key('capital'), $('capital').value);\n  PAGES[page].rates.forEach((rate, index) => {\n    // Keep the last manually entered fiat quote separate from the live cache.\n    if (!fxEnabled || !rate.fx) remember(key(`rate${index + 1}`), $(`rate${index + 1}`).value);\n  });\n}\n\nconst FX_URL = 'https://open.er-api.com/v6/latest/USD';\nconst FX_CACHE_KEY = 'tiendien_fx_usd_v16';\nconst FX_AUTO_KEY = 'tiendien_fx_auto_v16';\nconst FX_ATTEMPT_KEY = 'tiendien_fx_attempt_v16';\nconst FX_CODES = ['USD', 'EUR', 'CAD', 'TRY', 'JPY', 'VND', 'RUB'];\nlet fxEnabled = stored(FX_AUTO_KEY) !== '0';\nlet fxError = '';\nlet fxBusy = false;\nlet fxRequest = null;\nlet fxLastAttempt = Number(stored(FX_ATTEMPT_KEY)) || 0;\n\nfunction validateFx(payload) {\n  if (!payload || payload.result !== 'success' || payload.base_code !== 'USD' || !payload.rates) throw new Error('Invalid FX data');\n  for (const code of FX_CODES) {\n    const rate = payload.rates[code];\n    if (typeof rate !== 'number' || !Number.isFinite(rate) || rate <= 0) throw new Error('Invalid FX rate');\n  }\n  if (Math.abs(payload.rates.USD - 1) > 0.000001) throw new Error('Invalid FX base');\n  const last = payload.time_last_update_unix;\n  const next = payload.time_next_update_unix;\n  if (!Number.isFinite(last) || !Number.isFinite(next) || last <= 0 || next <= last || last * 1000 > Date.now() + 300000) throw new Error('Invalid FX timestamp');\n  return payload;\n}\nfunction readFxCache() {\n  try {\n    const cached = JSON.parse(stored(FX_CACHE_KEY) || 'null');\n    if (!cached || !Number.isFinite(cached.fetchedAt) || cached.fetchedAt <= 0 || cached.fetchedAt > Date.now() + 300000) return null;\n    validateFx(cached.payload);\n    return cached;\n  } catch (_) { return null; }\n}\nlet fxSnapshot = readFxCache();\nfunction fxIsDue() {\n  return !fxSnapshot || Date.now() >= fxSnapshot.payload.time_next_update_unix * 1000 + 60000;\n}\nfunction crossRate(base, quote) {\n  if (!fxSnapshot) return 0;\n  return fxSnapshot.payload.rates[quote] / fxSnapshot.payload.rates[base];\n}\nfunction renderUsdReferences() {\n  // Benchmarks are read-only display data. Never substitute them for P2P\n  // USDT inputs or use them in the route's received/profit calculations.\n  PAGES[page].rates.forEach((rate, index) => {\n    const reference = $(`usdReference${index + 1}`);\n    const pair = rate.label.split('/').map(code => code.trim());\n    const hasUsdt = pair.includes('USDT');\n    reference.classList.toggle('hidden', !hasUsdt);\n    reference.classList.toggle('stale', hasUsdt && Boolean(fxSnapshot) && (fxIsDue() || Boolean(fxError)));\n    if (!hasUsdt) {\n      reference.textContent = '';\n      reference.setAttribute('title', '');\n      return;\n    }\n    const currency = pair.find(code => code !== 'USDT');\n    const label = `USD / ${currency}`;\n    if (fxSnapshot) {\n      const value = crossRate('USD', currency);\n      const qualifier = fxError ? ' · giá lưu' : fxIsDue() ? ' · giá cũ' : '';\n      reference.textContent = `${label}: ${fmt4.format(value)}${qualifier}`;\n      const timestamp = new Date(fxSnapshot.payload.time_last_update_unix * 1000).toLocaleString('vi-VN', {timeZone: 'Asia/Ho_Chi_Minh'});\n      reference.setAttribute('title', `1 USD = ${fmt4.format(value)} ${currency}. Tỷ giá tham khảo từ ExchangeRate-API, lúc ${timestamp} (giờ VN).`);\n    } else {\n      reference.textContent = `${label}: ${fxBusy ? 'đang tải…' : fxError ? 'chưa tải được' : '—'}`;\n      reference.setAttribute('title', 'Chưa có dữ liệu tỷ giá pháp định; không suy ra từ giá USDT nhập tay.');\n    }\n  });\n}\nfunction applyFxToPage() {\n  if (!fxEnabled || !fxSnapshot) return;\n  PAGES[page].rates.forEach((rate, index) => {\n    if (!rate.fx) return;\n    const value = crossRate(...rate.fx);\n    const input = $(`rate${index + 1}`);\n    input.value = fmtRate.format(value);\n    input.dataset.fxSource = 'api';\n  });\n}\nfunction renderFxStatus() {\n  $('fxAuto').setAttribute('aria-checked', String(fxEnabled));\n  $('fxAuto').classList.toggle('enabled', fxEnabled);\n  $('fxAutoText').textContent = `Tự điền: ${fxEnabled ? 'Bật' : 'Tắt'}`;\n  $('fxRefresh').disabled = fxBusy;\n  $('fxRefresh').textContent = fxBusy ? 'Đang tải…' : 'Cập nhật';\n  $('fxStatus').classList.toggle('fx-warning', Boolean(fxError) || (fxIsDue() && Boolean(fxSnapshot)));\n  const manualPrefix = fxEnabled ? '' : 'Ô giá nhập tay. ';\n  if (fxSnapshot) {\n    const date = new Intl.DateTimeFormat('vi-VN', {dateStyle: 'short', timeStyle: 'short', timeZone: 'Asia/Ho_Chi_Minh'}).format(new Date(fxSnapshot.payload.time_last_update_unix * 1000));\n    const prefix = fxError ? `${fxError} · đang dùng giá lưu lúc ` : fxIsDue() ? 'Giá cũ từ ' : 'Tỷ giá lúc ';\n    $('fxStatus').textContent = `${manualPrefix}${prefix}${date} (giờ VN). USDT nhập tay.`;\n  } else if (fxError) {\n    $('fxStatus').textContent = `${manualPrefix}${fxError}. ${fxEnabled ? 'Tắt Tự điền để nhập tay.' : 'USD tham khảo chưa có dữ liệu.'}`;\n  } else {\n    $('fxStatus').textContent = manualPrefix + (fxBusy ? 'Đang lấy tỷ giá pháp định… USDT nhập tay.' : 'Chưa có tỷ giá tự động. USDT nhập tay.');\n  }\n  PAGES[page].rates.forEach((rate, index) => {\n    const input = $(`rate${index + 1}`);\n    const automatic = Boolean(rate.fx && fxEnabled);\n    input.readOnly = automatic;\n    input.setAttribute('aria-readonly', String(automatic));\n    const tag = rate.fx ? (automatic ? (fxSnapshot ? 'TỰ ĐỘNG' : input.value ? 'ĐÃ LƯU' : 'CHỜ GIÁ') : 'NHẬP TAY') : rate.tag;\n    $(`rate${index + 1}Label`).innerHTML = `${rate.label}${tag ? ` <small>${tag}</small>` : ''}`;\n    input.closest('.field').classList.toggle('auto-rate', automatic);\n  });\n  $('resultNote').textContent = fxEnabled ? 'Ước tính theo tỷ giá tham khảo · chưa trừ phí' : 'Ước tính · chưa trừ phí giao dịch';\n  renderUsdReferences();\n}\n\nasync function refreshFx({force = false} = {}) {\n  // The feed also powers USD reference lines while auto-fill is disabled.\n  if (fxRequest) return fxRequest;\n  if (!force && !fxIsDue()) { renderFxStatus(); return; }\n  const elapsed = Date.now() - fxLastAttempt;\n  // One scheduled attempt every five minutes when offline/unavailable; manual\n  // refresh is limited to once a minute. A fresh daily snapshot needs no poll.\n  if (elapsed >= 0 && elapsed < (force ? 60000 : 300000)) { renderFxStatus(); return; }\n  fxLastAttempt = Date.now();\n  remember(FX_ATTEMPT_KEY, fxLastAttempt);\n  fxBusy = true;\n  renderFxStatus();\n  fxRequest = (async () => {\n    const controller = new AbortController();\n    const timeout = setTimeout(() => controller.abort(), 10000);\n    try {\n      const response = await fetch(FX_URL, {cache: 'no-store', credentials: 'omit', signal: controller.signal});\n      if (!response.ok) throw new Error(response.status === 429 ? 'RATE_LIMIT' : 'FETCH_FAILED');\n      const payload = validateFx(await response.json());\n      if (fxSnapshot && payload.time_last_update_unix < fxSnapshot.payload.time_last_update_unix) throw new Error('Older FX response');\n      fxSnapshot = {payload, fetchedAt: Date.now()};\n      remember(FX_CACHE_KEY, JSON.stringify(fxSnapshot));\n      fxError = '';\n      // The user may have switched tabs or disabled auto while fetch awaited.\n      if (fxEnabled) { applyFxToPage(); calculate(); }\n    } catch (error) {\n      fxError = error.message === 'RATE_LIMIT' ? 'Nguồn đang giới hạn truy cập' : 'Không tải được tỷ giá';\n    } finally {\n      clearTimeout(timeout);\n      fxBusy = false;\n      fxRequest = null;\n      renderFxStatus();\n    }\n  })();\n  return fxRequest;\n}\n\nfunction restorePage() {\n  $('capital').value = stored(key('capital')) ?? (page === 'cad' ? '10.000' : page === 'try' ? '100.000' : '100.000.000');\n  ['rate1', 'rate2', 'rate3'].forEach(id => {\n    $(id).value = stored(key(id)) ?? '';\n    delete $(id).dataset.fxSource;\n  });\n  formatCapital();\n}\nfunction renderPage() {\n  const config = PAGES[page];\n  $('routeText').textContent = config.route;\n  $('capitalUnit').textContent = config.capital;\n  config.rates.forEach((rate, index) => {\n    const input = $(`rate${index + 1}`);\n    $(`rate${index + 1}Unit`).textContent = rate.unit;\n    input.placeholder = rate.placeholder;\n    input.setAttribute('aria-label', `${rate.label}: số ${rate.unit} cho một ${rate.label.split(' / ')[0]}`);\n    input.closest('.field').classList.toggle('rate-highlight', index + 1 === config.highlight);\n  });\n  document.querySelectorAll('.tab').forEach(button => {\n    const active = button.dataset.page === page;\n    button.classList.toggle('active', active);\n    button.setAttribute('aria-pressed', String(active));\n  });\n  $('rubNote').classList.toggle('hidden', page !== 'rub');\n  remember('tiendien_page', page);\n  restorePage();\n  applyFxToPage();\n  renderFxStatus();\n  calculate();\n}\nfunction calculate() {\n  const config = PAGES[page];\n  const capital = capitalNum($('capital').value);\n  let amount = capital;\n  config.rates.forEach((rate, index) => {\n    const quote = rateNum($(`rate${index + 1}`).value, Boolean(rate.vndThousands));\n    amount = amount > 0 && quote > 0 ? (rate.op === 'divide' ? amount / quote : amount * quote) : 0;\n    if (!Number.isFinite(amount)) amount = 0;\n    $(`received${index + 1}`).textContent = formatReceived(amount, rate.receive);\n  });\n  if (!(capital > 0 && amount > 0)) {\n    $('profit').textContent = '—'; $('roi').textContent = '—';\n    $('profit').className = ''; $('roi').className = '';\n  } else {\n    const profit = amount - capital;\n    const roi = profit / capital * 100;\n    if (Number.isFinite(profit) && Number.isFinite(roi)) {\n      $('profit').textContent = money(profit, config.capital);\n      $('roi').textContent = pct(roi);\n      tone($('profit'), profit); tone($('roi'), profit);\n    } else {\n      $('profit').textContent = '—'; $('roi').textContent = '—';\n      $('profit').className = ''; $('roi').className = '';\n    }\n  }\n  save();\n}\n\n$('capital').addEventListener('input', () => { formatCapital(); calculate(); });\n['rate1', 'rate2', 'rate3'].forEach(id => $(id).addEventListener('input', calculate));\ndocument.querySelectorAll('.tab').forEach(button => button.addEventListener('click', () => {\n  save(); page = button.dataset.page; renderPage(); refreshFx();\n}));\n$('fxAuto').addEventListener('click', () => {\n  save();\n  fxEnabled = !fxEnabled;\n  remember(FX_AUTO_KEY, fxEnabled ? '1' : '0');\n  if (fxEnabled) applyFxToPage();\n  else {\n    PAGES[page].rates.forEach((rate, index) => {\n      if (!rate.fx) return;\n      const manual = stored(key(`rate${index + 1}`));\n      if (manual !== null) $(`rate${index + 1}`).value = manual;\n      delete $(`rate${index + 1}`).dataset.fxSource;\n    });\n  }\n  renderFxStatus(); calculate();\n  if (fxEnabled) refreshFx();\n});\n$('fxRefresh').addEventListener('click', () => refreshFx({force: true}));\nwindow.addEventListener('online', () => refreshFx());\ndocument.addEventListener('visibilitychange', () => { if (!document.hidden) refreshFx(); });\nsetInterval(() => { if (!document.hidden) refreshFx(); }, 60000);\n\nlet deferredPrompt = null;\nwindow.addEventListener('beforeinstallprompt', event => {\n  event.preventDefault(); deferredPrompt = event; $('installBtn').classList.remove('hidden');\n});\n$('installBtn').addEventListener('click', async () => {\n  if (!deferredPrompt) return;\n  deferredPrompt.prompt(); await deferredPrompt.userChoice;\n  deferredPrompt = null; $('installBtn').classList.add('hidden');\n});\n\n// Retire this app's old cache without touching other apps on the same origin.\n(async () => {\n  try {\n    if ('serviceWorker' in navigator) {\n      const scope = new URL('./', location.href).href;\n      const registrations = await navigator.serviceWorker.getRegistrations();\n      for (const registration of registrations) if (registration.scope === scope) await registration.unregister();\n    }\n    if ('caches' in window) {\n      for (const name of await caches.keys()) if (/^(tien-cua-dien|tiendien)[-_]/.test(name)) await caches.delete(name);\n    }\n  } catch (_) {}\n})();\nrenderPage();\nrefreshFx();\n\n</script>\n</body>\n</html>\n"},"/offline-calculator.html":{"type":"text/html; charset=utf-8","body":"<!doctype html>\n<html lang=\"vi\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta http-equiv=\"Cache-Control\" content=\"no-cache, no-store, must-revalidate\">\n  <meta http-equiv=\"Pragma\" content=\"no-cache\">\n  <meta http-equiv=\"Expires\" content=\"0\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n  <meta name=\"theme-color\" content=\"#090b0c\">\n  <meta name=\"color-scheme\" content=\"dark\">\n  <title>Tiền của Điền</title>\n  <link rel=\"manifest\" href=\"./manifest.webmanifest?v=18\">\n  <link rel=\"icon\" href=\"./icon.svg\" type=\"image/svg+xml\">\n<style>\n:root{--bg:#090b0c;--panel:#121517;--field:#0c0f11;--line:#252b2f;--text:#f4f7f8;--muted:#899197;--accent:#00e68a;--bad:#ff6670;--warn:#f2c14e}\n*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;background:var(--bg);overflow:auto}body{font-family:Inter,ui-sans-serif,system-ui,-apple-system,\"Segoe UI\",sans-serif;color:var(--text)}button,input{font:inherit}.app{height:100dvh;min-height:530px;max-width:620px;margin:0 auto;padding:max(12px,env(safe-area-inset-top)) 14px max(12px,env(safe-area-inset-bottom));display:grid;grid-template-rows:auto auto auto minmax(115px,1fr);gap:10px;background:radial-gradient(circle at 90% -10%,rgba(0,230,138,.12),transparent 36%)}header{display:flex;justify-content:space-between;align-items:center;gap:12px}.route{font-size:11px;font-weight:800;letter-spacing:.06em;color:var(--accent)}h1{margin:2px 0 0;font-size:27px;line-height:1;letter-spacing:-.045em}.version{display:inline-block;margin-top:5px;font-size:9px;font-weight:900;letter-spacing:.08em;color:var(--accent);opacity:.8}.install{border:1px solid var(--line);background:var(--panel);color:var(--accent);font-size:11px;font-weight:850;padding:8px 11px;border-radius:10px;cursor:pointer}.hidden{display:none!important}.tabs{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:7px}.tab{height:34px;border:1px solid var(--line);border-radius:10px;background:#101315;color:var(--muted);font-size:12px;font-weight:900;letter-spacing:.04em;cursor:pointer}.tab.active{color:#07110d;background:var(--accent);border-color:var(--accent)}.panel{border:1px solid var(--line);background:linear-gradient(180deg,#15191b,var(--panel));border-radius:17px;padding:12px}.inputs{display:grid;grid-template-columns:1fr 1fr;gap:10px}.inputs label.wide{grid-column:1/-1}.inputs label>span{display:flex;justify-content:space-between;align-items:center;gap:6px;font-size:11px;font-weight:780;color:#c7cdd0;margin:0 2px 5px}.inputs small{font-size:8px;color:var(--muted);font-weight:900;letter-spacing:.07em}.field{height:45px;display:flex;align-items:center;border:1px solid var(--line);background:var(--field);border-radius:12px;overflow:hidden}.field:focus-within{border-color:var(--accent);box-shadow:0 0 0 2px rgba(0,230,138,.08)}.field.rate-highlight{background:linear-gradient(180deg,rgba(0,230,138,.18),rgba(0,230,138,.08));border-color:rgba(0,230,138,.62);box-shadow:inset 0 0 0 1px rgba(0,230,138,.06)}.field.rate-highlight input{color:#f7fffb}.field.rate-highlight b{color:var(--accent)}.field input{width:100%;min-width:0;height:100%;border:0;outline:0;background:transparent;color:var(--text);padding:0 11px;font-size:16px;font-weight:800}.field input::placeholder{color:#535b60;font-size:12px;font-weight:650}.field b{font-size:9px;color:var(--muted);padding:0 10px}.received{display:block;margin:5px 3px 0;color:var(--muted);font-size:10px;line-height:1.15;font-style:normal;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.result-card{min-height:0;border:1px solid #284439;background:linear-gradient(180deg,#142119,#101613);border-radius:18px;padding:14px;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center}.result-card span{font-size:10px;color:var(--muted);font-weight:900;letter-spacing:.12em}.result-card strong{font-size:clamp(30px,8vw,46px);line-height:1.03;margin:8px 0 4px;letter-spacing:-.055em}.result-card b{font-size:16px}.good{color:var(--accent)!important}.bad{color:var(--bad)!important}.neutral{color:var(--warn)!important}\n@media(max-width:390px){.app{padding-left:10px;padding-right:10px;gap:8px}.panel{padding:10px}.inputs{gap:8px}.field{height:41px}.field input{font-size:14px}h1{font-size:23px}.received{font-size:9px;margin-top:4px}.result-card{padding:11px}.result-card strong{font-size:29px}.tab{height:31px;font-size:11px}}\n@media(max-height:690px){.app{gap:7px;padding-top:7px;padding-bottom:7px}.route{font-size:9px}h1{font-size:20px}.tabs{gap:5px}.tab{height:28px;font-size:10px}.panel{padding:8px}.inputs{gap:6px}.inputs label>span{font-size:9px;margin-bottom:3px}.field{height:33px}.field input{font-size:13px}.received{font-size:8px;margin-top:3px}.result-card{padding:8px}.result-card strong{font-size:26px;margin:4px 0 2px}}\n.fx-tools{grid-column:1/-1;border-top:1px solid var(--line);padding-top:9px;min-width:0}\n.fx-controls{display:flex;align-items:center;justify-content:space-between;gap:8px}\n.fx-toggle,.fx-refresh{min-height:32px;border:1px solid var(--line);border-radius:9px;background:var(--field);color:var(--muted);padding:5px 10px;font-size:11px;font-weight:800;cursor:pointer}\n.fx-toggle{display:inline-flex;align-items:center;gap:7px}\n.fx-toggle.enabled{color:var(--accent);border-color:#285d46;background:#11251c}\n.fx-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:currentColor}\n.fx-refresh{color:var(--text)}.fx-refresh:disabled{opacity:.45;cursor:default}\n.fx-tools p{margin:5px 0 0;font-size:9px;line-height:1.4;color:var(--muted);overflow-wrap:anywhere}\n.fx-tools a{color:var(--muted);text-underline-offset:2px}\n.fx-tools .fx-warning{color:var(--warn)}\n.field.auto-rate{border-style:dashed}.field.auto-rate input{cursor:default}\n.rub-note{grid-column:1/-1;margin:0 2px;color:var(--warn);font-size:10px;line-height:1.35}\n.result-note{margin:8px 0 0;font-size:9px;line-height:1.4;color:var(--muted);font-weight:500;letter-spacing:0}\n.usd-reference{display:block;margin:4px 3px 0;font-size:10px;line-height:1.35;font-style:normal;font-weight:650;color:#73c6a3;overflow-wrap:anywhere}\n.usd-reference.stale{color:var(--warn)}\nbutton:focus-visible{outline:2px solid var(--accent);outline-offset:3px}\n@media(max-width:390px){.tabs{gap:5px}.fx-toggle,.fx-refresh{font-size:10px;padding:5px 8px}}\n@media(max-height:690px){.fx-tools{padding-top:6px}.fx-tools p{font-size:8px;margin-top:3px}.fx-toggle,.fx-refresh{min-height:28px;font-size:10px}.rub-note{font-size:9px}.result-note{font-size:8px;margin-top:5px}.usd-reference{font-size:9px;margin-top:3px}}\n\n</style>\n</head>\n<body>\n  <main class=\"app\">\n    <header>\n      <div>\n        <div class=\"route\" id=\"routeText\">VND → USDT → EUR → VND</div>\n        <h1>Tiền của Điền</h1><span class=\"version\">v18 · TỶ GIÁ USD THAM KHẢO</span>\n      </div>\n      <button id=\"installBtn\" class=\"install hidden\">Cài app</button>\n    </header>\n\n    <nav class=\"tabs\" aria-label=\"Loại vòng tiền\">\n      <button type=\"button\" class=\"tab\" data-page=\"cad\">CAD</button>\n      <button type=\"button\" class=\"tab\" data-page=\"try\">TRY</button>\n      <button type=\"button\" class=\"tab active\" data-page=\"vnd\">VND</button>\n      <button type=\"button\" class=\"tab\" data-page=\"jpy\">JPY</button>\n      <button type=\"button\" class=\"tab\" data-page=\"rub\">RUB</button>\n    </nav>\n\n    <section class=\"panel inputs\">\n      <label class=\"wide\">\n        <span>Vốn ban đầu</span>\n        <div class=\"field\"><input aria-label=\"Vốn ban đầu\" id=\"capital\" inputmode=\"numeric\" value=\"100.000.000\"><b id=\"capitalUnit\">VND</b></div>\n      </label>\n\n      <label>\n        <span id=\"rate1Label\">USDT / VND <small>P2P</small></span>\n        <div class=\"field\"><input id=\"rate1\" inputmode=\"decimal\" placeholder=\"Ví dụ 26.300\"><b id=\"rate1Unit\">VND</b></div>\n        <em class=\"received\" id=\"received1\">Nhận: — USDT</em>\n        <em class=\"usd-reference hidden\" id=\"usdReference1\" aria-live=\"polite\"></em>\n      </label>\n\n      <label>\n        <span id=\"rate2Label\">USDT / EUR <small>P2P</small></span>\n        <div class=\"field\"><input id=\"rate2\" inputmode=\"decimal\" placeholder=\"Ví dụ 0,8600\"><b id=\"rate2Unit\">EUR</b></div>\n        <em class=\"received\" id=\"received2\">Nhận: — EUR</em>\n        <em class=\"usd-reference hidden\" id=\"usdReference2\" aria-live=\"polite\"></em>\n      </label>\n\n      <label class=\"wide\">\n        <span id=\"rate3Label\">EUR / VND</span>\n        <div class=\"field\"><input id=\"rate3\" inputmode=\"decimal\" placeholder=\"Ví dụ 30.700\"><b id=\"rate3Unit\">VND</b></div>\n        <em class=\"received\" id=\"received3\">Nhận: — VND</em>\n        <em class=\"usd-reference hidden\" id=\"usdReference3\" aria-live=\"polite\"></em>\n      </label>\n\n      <p id=\"rubNote\" class=\"rub-note hidden\">Bước USD/RUB quy ước 1 USDT = 1 USD. Giá mua USDT thực tế có thể khác.</p>\n      <div class=\"fx-tools\">\n        <div class=\"fx-controls\">\n          <button type=\"button\" id=\"fxAuto\" class=\"fx-toggle enabled\" role=\"switch\" aria-checked=\"true\" aria-label=\"Tự động điền các ô tỷ giá pháp định\"><i class=\"fx-dot\" aria-hidden=\"true\"></i><span id=\"fxAutoText\">Tự điền: Bật</span></button>\n          <button type=\"button\" id=\"fxRefresh\" class=\"fx-refresh\">Cập nhật</button>\n        </div>\n        <p id=\"fxStatus\" role=\"status\" aria-live=\"polite\">Đang lấy tỷ giá pháp định…</p>\n        <p><a href=\"https://www.exchangerate-api.com\" target=\"_blank\" rel=\"noopener noreferrer\">Rates By Exchange Rate API</a> · Tham khảo, cập nhật hằng ngày.</p>\n      </div>\n    </section>\n\n    <section class=\"result-card\">\n      <span>LÃI / LỖ</span>\n      <strong id=\"profit\">—</strong>\n      <b id=\"roi\">—</b>\n      <p id=\"resultNote\" class=\"result-note\">Ước tính · chưa trừ phí giao dịch</p>\n    </section>\n  </main>\n\n\n\n<script>\n'use strict';\nconst $ = id => document.getElementById(id);\nconst fmt0 = new Intl.NumberFormat('vi-VN', {maximumFractionDigits: 0});\nconst fmt2 = new Intl.NumberFormat('vi-VN', {maximumFractionDigits: 2});\nconst fmt4 = new Intl.NumberFormat('vi-VN', {maximumFractionDigits: 4});\nconst fmtRate = new Intl.NumberFormat('vi-VN', {useGrouping: false, maximumFractionDigits: 6});\nconst memoryStorage = new Map();\nfunction stored(name) {\n  try { return localStorage.getItem(name) ?? memoryStorage.get(name) ?? null; }\n  catch (_) { return memoryStorage.get(name) ?? null; }\n}\nfunction remember(name, value) {\n  memoryStorage.set(name, String(value));\n  try { localStorage.setItem(name, String(value)); } catch (_) {}\n}\n\n// A/B always means the amount of B for ONE unit of A.\n// Only explicit fiat pairs have an fx property. USDT is never fetched or\n// inferred from the provider's USD rate, except the disclosed RUB convention.\nconst PAGES = {\n  cad: {\n    route: 'CAD → EUR → USDT → CAD', capital: 'CAD', highlight: 0,\n    rates: [\n      {label: 'EUR / CAD', unit: 'CAD', placeholder: 'Ví dụ 1,5500', receive: 'EUR', op: 'divide', fx: ['EUR', 'CAD']},\n      {label: 'USDT / EUR', tag: 'P2P', unit: 'EUR', placeholder: 'Ví dụ 0,8900', receive: 'USDT', op: 'divide'},\n      {label: 'USDT / CAD', tag: 'P2P', unit: 'CAD', placeholder: 'Ví dụ 1,3900', receive: 'CAD', op: 'multiply'}\n    ]\n  },\n  try: {\n    route: 'TRY → EUR → USDT → TRY', capital: 'TRY', highlight: 3,\n    rates: [\n      {label: 'EUR / TRY', unit: 'TRY', placeholder: 'Ví dụ 48,50', receive: 'EUR', op: 'divide', fx: ['EUR', 'TRY']},\n      {label: 'USDT / EUR', tag: 'P2P', unit: 'EUR', placeholder: 'Ví dụ 0,8550', receive: 'USDT', op: 'divide'},\n      {label: 'USDT / TRY', tag: 'P2P', unit: 'TRY', placeholder: 'Ví dụ 41,50', receive: 'TRY', op: 'multiply'}\n    ]\n  },\n  vnd: {\n    route: 'VND → USDT → EUR → VND', capital: 'VND', highlight: 1,\n    rates: [\n      {label: 'USDT / VND', tag: 'P2P', unit: 'VND', placeholder: 'Ví dụ 26.300', receive: 'USDT', op: 'divide', vndThousands: true},\n      {label: 'USDT / EUR', tag: 'P2P', unit: 'EUR', placeholder: 'Ví dụ 0,8600', receive: 'EUR', op: 'multiply'},\n      {label: 'EUR / VND', unit: 'VND', placeholder: 'Ví dụ 30.700', receive: 'VND', op: 'multiply', vndThousands: true, fx: ['EUR', 'VND']}\n    ]\n  },\n  jpy: {\n    route: 'VND → JPY → USDT → VND', capital: 'VND', highlight: 2,\n    rates: [\n      {label: 'JPY / VND', unit: 'VND', placeholder: 'Ví dụ 165,50', receive: 'JPY', op: 'divide', fx: ['JPY', 'VND']},\n      {label: 'USDT / JPY', tag: 'P2P', unit: 'JPY', placeholder: 'Ví dụ 155,00', receive: 'USDT', op: 'divide'},\n      {label: 'USDT / VND', tag: 'P2P', unit: 'VND', placeholder: 'Ví dụ 26.300', receive: 'VND', op: 'multiply', vndThousands: true}\n    ]\n  },\n  rub: {\n    route: 'VND → RUB → USDT → VND', capital: 'VND', highlight: 3,\n    rates: [\n      {label: 'RUB / VND', unit: 'VND', placeholder: 'Ví dụ 310,50', receive: 'RUB', op: 'divide', fx: ['RUB', 'VND']},\n      {label: 'USD / RUB', unit: 'RUB', placeholder: 'Ví dụ 83,50', receive: 'USDT', op: 'divide', fx: ['USD', 'RUB']},\n      {label: 'USDT / VND', tag: 'P2P', unit: 'VND', placeholder: 'Ví dụ 26.300', receive: 'VND', op: 'multiply', vndThousands: true}\n    ]\n  }\n};\n\nfunction migrateVndTab() {\n  const legacy = {capital: 'tiendien_capitalVnd', rate1: 'tiendien_usdtVnd', rate2: 'tiendien_usdtEur', rate3: 'tiendien_eurVnd'};\n  for (const id of ['capital', 'rate1', 'rate2', 'rate3']) {\n    const target = `tiendien_vnd_${id}`;\n    const value = stored(`tiendien_eur_${id}`) ?? stored(legacy[id]);\n    if (stored(target) === null && value !== null) remember(target, value);\n  }\n}\nmigrateVndTab();\n// CAD now has a different starting currency and different quote positions.\n// Keep its new inputs separate so VND capital / unrelated old quotes cannot\n// acquire a new currency label. Only the unchanged USDT/CAD quote migrates.\nconst oldUsdtCad = stored('tiendien_cad_rate2');\nif (stored('tiendien_cad_eur_usdt_rate3') === null && oldUsdtCad !== null) {\n  remember('tiendien_cad_eur_usdt_rate3', oldUsdtCad);\n}\nlet page = stored('tiendien_page');\nif (page === 'eur' || !PAGES[page]) page = 'vnd';\n\nfunction capitalNum(value) {\n  const number = Number(String(value ?? '').replace(/\\D/g, ''));\n  return Number.isFinite(number) ? number : 0;\n}\nfunction rateNum(value, thousands = false) {\n  let text = String(value ?? '').trim().replace(/\\s/g, '');\n  if (!text) return 0;\n  if (text.includes(',')) text = text.replace(/\\./g, '').replace(',', '.');\n  else if (thousands && /^\\d{1,3}(?:\\.\\d{3})+$/.test(text)) text = text.replace(/\\./g, '');\n  const number = Number(text);\n  return Number.isFinite(number) ? number : 0;\n}\nfunction formatCapital() {\n  const digits = $('capital').value.replace(/\\D/g, '');\n  $('capital').value = digits ? fmt0.format(capitalNum(digits)) : '';\n}\nfunction money(value, unit) { return `${value >= 0 ? '+' : '−'}${(unit === 'CAD' ? fmt2 : fmt0).format(Math.abs(value))} ${unit}`; }\nfunction pct(value) { return `${value >= 0 ? '+' : ''}${fmt2.format(value)}%`; }\nfunction tone(element, value) {\n  element.classList.remove('good', 'bad', 'neutral');\n  element.classList.add(value > 0.01 ? 'good' : value < -0.01 ? 'bad' : 'neutral');\n}\nfunction formatReceived(value, unit) {\n  if (!(value > 0 && Number.isFinite(value))) return `Nhận: — ${unit}`;\n  return `Nhận: ${(unit === 'VND' || unit === 'TRY' ? fmt2 : fmt4).format(value)} ${unit}`;\n}\nfunction key(name) { return `tiendien_${page === 'cad' ? 'cad_eur_usdt' : page}_${name}`; }\nfunction save() {\n  remember(key('capital'), $('capital').value);\n  PAGES[page].rates.forEach((rate, index) => {\n    // Keep the last manually entered fiat quote separate from the live cache.\n    if (!fxEnabled || !rate.fx) remember(key(`rate${index + 1}`), $(`rate${index + 1}`).value);\n  });\n}\n\nconst FX_URL = 'https://open.er-api.com/v6/latest/USD';\nconst FX_CACHE_KEY = 'tiendien_fx_usd_v16';\nconst FX_AUTO_KEY = 'tiendien_fx_auto_v16';\nconst FX_ATTEMPT_KEY = 'tiendien_fx_attempt_v16';\nconst FX_CODES = ['USD', 'EUR', 'CAD', 'TRY', 'JPY', 'VND', 'RUB'];\nlet fxEnabled = stored(FX_AUTO_KEY) !== '0';\nlet fxError = '';\nlet fxBusy = false;\nlet fxRequest = null;\nlet fxLastAttempt = Number(stored(FX_ATTEMPT_KEY)) || 0;\n\nfunction validateFx(payload) {\n  if (!payload || payload.result !== 'success' || payload.base_code !== 'USD' || !payload.rates) throw new Error('Invalid FX data');\n  for (const code of FX_CODES) {\n    const rate = payload.rates[code];\n    if (typeof rate !== 'number' || !Number.isFinite(rate) || rate <= 0) throw new Error('Invalid FX rate');\n  }\n  if (Math.abs(payload.rates.USD - 1) > 0.000001) throw new Error('Invalid FX base');\n  const last = payload.time_last_update_unix;\n  const next = payload.time_next_update_unix;\n  if (!Number.isFinite(last) || !Number.isFinite(next) || last <= 0 || next <= last || last * 1000 > Date.now() + 300000) throw new Error('Invalid FX timestamp');\n  return payload;\n}\nfunction readFxCache() {\n  try {\n    const cached = JSON.parse(stored(FX_CACHE_KEY) || 'null');\n    if (!cached || !Number.isFinite(cached.fetchedAt) || cached.fetchedAt <= 0 || cached.fetchedAt > Date.now() + 300000) return null;\n    validateFx(cached.payload);\n    return cached;\n  } catch (_) { return null; }\n}\nlet fxSnapshot = readFxCache();\nfunction fxIsDue() {\n  return !fxSnapshot || Date.now() >= fxSnapshot.payload.time_next_update_unix * 1000 + 60000;\n}\nfunction crossRate(base, quote) {\n  if (!fxSnapshot) return 0;\n  return fxSnapshot.payload.rates[quote] / fxSnapshot.payload.rates[base];\n}\nfunction renderUsdReferences() {\n  // Benchmarks are read-only display data. Never substitute them for P2P\n  // USDT inputs or use them in the route's received/profit calculations.\n  PAGES[page].rates.forEach((rate, index) => {\n    const reference = $(`usdReference${index + 1}`);\n    const pair = rate.label.split('/').map(code => code.trim());\n    const hasUsdt = pair.includes('USDT');\n    reference.classList.toggle('hidden', !hasUsdt);\n    reference.classList.toggle('stale', hasUsdt && Boolean(fxSnapshot) && (fxIsDue() || Boolean(fxError)));\n    if (!hasUsdt) {\n      reference.textContent = '';\n      reference.setAttribute('title', '');\n      return;\n    }\n    const currency = pair.find(code => code !== 'USDT');\n    const label = `USD / ${currency}`;\n    if (fxSnapshot) {\n      const value = crossRate('USD', currency);\n      const qualifier = fxError ? ' · giá lưu' : fxIsDue() ? ' · giá cũ' : '';\n      reference.textContent = `${label}: ${fmt4.format(value)}${qualifier}`;\n      const timestamp = new Date(fxSnapshot.payload.time_last_update_unix * 1000).toLocaleString('vi-VN', {timeZone: 'Asia/Ho_Chi_Minh'});\n      reference.setAttribute('title', `1 USD = ${fmt4.format(value)} ${currency}. Tỷ giá tham khảo từ ExchangeRate-API, lúc ${timestamp} (giờ VN).`);\n    } else {\n      reference.textContent = `${label}: ${fxBusy ? 'đang tải…' : fxError ? 'chưa tải được' : '—'}`;\n      reference.setAttribute('title', 'Chưa có dữ liệu tỷ giá pháp định; không suy ra từ giá USDT nhập tay.');\n    }\n  });\n}\nfunction applyFxToPage() {\n  if (!fxEnabled || !fxSnapshot) return;\n  PAGES[page].rates.forEach((rate, index) => {\n    if (!rate.fx) return;\n    const value = crossRate(...rate.fx);\n    const input = $(`rate${index + 1}`);\n    input.value = fmtRate.format(value);\n    input.dataset.fxSource = 'api';\n  });\n}\nfunction renderFxStatus() {\n  $('fxAuto').setAttribute('aria-checked', String(fxEnabled));\n  $('fxAuto').classList.toggle('enabled', fxEnabled);\n  $('fxAutoText').textContent = `Tự điền: ${fxEnabled ? 'Bật' : 'Tắt'}`;\n  $('fxRefresh').disabled = fxBusy;\n  $('fxRefresh').textContent = fxBusy ? 'Đang tải…' : 'Cập nhật';\n  $('fxStatus').classList.toggle('fx-warning', Boolean(fxError) || (fxIsDue() && Boolean(fxSnapshot)));\n  const manualPrefix = fxEnabled ? '' : 'Ô giá nhập tay. ';\n  if (fxSnapshot) {\n    const date = new Intl.DateTimeFormat('vi-VN', {dateStyle: 'short', timeStyle: 'short', timeZone: 'Asia/Ho_Chi_Minh'}).format(new Date(fxSnapshot.payload.time_last_update_unix * 1000));\n    const prefix = fxError ? `${fxError} · đang dùng giá lưu lúc ` : fxIsDue() ? 'Giá cũ từ ' : 'Tỷ giá lúc ';\n    $('fxStatus').textContent = `${manualPrefix}${prefix}${date} (giờ VN). USDT nhập tay.`;\n  } else if (fxError) {\n    $('fxStatus').textContent = `${manualPrefix}${fxError}. ${fxEnabled ? 'Tắt Tự điền để nhập tay.' : 'USD tham khảo chưa có dữ liệu.'}`;\n  } else {\n    $('fxStatus').textContent = manualPrefix + (fxBusy ? 'Đang lấy tỷ giá pháp định… USDT nhập tay.' : 'Chưa có tỷ giá tự động. USDT nhập tay.');\n  }\n  PAGES[page].rates.forEach((rate, index) => {\n    const input = $(`rate${index + 1}`);\n    const automatic = Boolean(rate.fx && fxEnabled);\n    input.readOnly = automatic;\n    input.setAttribute('aria-readonly', String(automatic));\n    const tag = rate.fx ? (automatic ? (fxSnapshot ? 'TỰ ĐỘNG' : input.value ? 'ĐÃ LƯU' : 'CHỜ GIÁ') : 'NHẬP TAY') : rate.tag;\n    $(`rate${index + 1}Label`).innerHTML = `${rate.label}${tag ? ` <small>${tag}</small>` : ''}`;\n    input.closest('.field').classList.toggle('auto-rate', automatic);\n  });\n  $('resultNote').textContent = fxEnabled ? 'Ước tính theo tỷ giá tham khảo · chưa trừ phí' : 'Ước tính · chưa trừ phí giao dịch';\n  renderUsdReferences();\n}\n\nasync function refreshFx({force = false} = {}) {\n  // The feed also powers USD reference lines while auto-fill is disabled.\n  if (fxRequest) return fxRequest;\n  if (!force && !fxIsDue()) { renderFxStatus(); return; }\n  const elapsed = Date.now() - fxLastAttempt;\n  // One scheduled attempt every five minutes when offline/unavailable; manual\n  // refresh is limited to once a minute. A fresh daily snapshot needs no poll.\n  if (elapsed >= 0 && elapsed < (force ? 60000 : 300000)) { renderFxStatus(); return; }\n  fxLastAttempt = Date.now();\n  remember(FX_ATTEMPT_KEY, fxLastAttempt);\n  fxBusy = true;\n  renderFxStatus();\n  fxRequest = (async () => {\n    const controller = new AbortController();\n    const timeout = setTimeout(() => controller.abort(), 10000);\n    try {\n      const response = await fetch(FX_URL, {cache: 'no-store', credentials: 'omit', signal: controller.signal});\n      if (!response.ok) throw new Error(response.status === 429 ? 'RATE_LIMIT' : 'FETCH_FAILED');\n      const payload = validateFx(await response.json());\n      if (fxSnapshot && payload.time_last_update_unix < fxSnapshot.payload.time_last_update_unix) throw new Error('Older FX response');\n      fxSnapshot = {payload, fetchedAt: Date.now()};\n      remember(FX_CACHE_KEY, JSON.stringify(fxSnapshot));\n      fxError = '';\n      // The user may have switched tabs or disabled auto while fetch awaited.\n      if (fxEnabled) { applyFxToPage(); calculate(); }\n    } catch (error) {\n      fxError = error.message === 'RATE_LIMIT' ? 'Nguồn đang giới hạn truy cập' : 'Không tải được tỷ giá';\n    } finally {\n      clearTimeout(timeout);\n      fxBusy = false;\n      fxRequest = null;\n      renderFxStatus();\n    }\n  })();\n  return fxRequest;\n}\n\nfunction restorePage() {\n  $('capital').value = stored(key('capital')) ?? (page === 'cad' ? '10.000' : page === 'try' ? '100.000' : '100.000.000');\n  ['rate1', 'rate2', 'rate3'].forEach(id => {\n    $(id).value = stored(key(id)) ?? '';\n    delete $(id).dataset.fxSource;\n  });\n  formatCapital();\n}\nfunction renderPage() {\n  const config = PAGES[page];\n  $('routeText').textContent = config.route;\n  $('capitalUnit').textContent = config.capital;\n  config.rates.forEach((rate, index) => {\n    const input = $(`rate${index + 1}`);\n    $(`rate${index + 1}Unit`).textContent = rate.unit;\n    input.placeholder = rate.placeholder;\n    input.setAttribute('aria-label', `${rate.label}: số ${rate.unit} cho một ${rate.label.split(' / ')[0]}`);\n    input.closest('.field').classList.toggle('rate-highlight', index + 1 === config.highlight);\n  });\n  document.querySelectorAll('.tab').forEach(button => {\n    const active = button.dataset.page === page;\n    button.classList.toggle('active', active);\n    button.setAttribute('aria-pressed', String(active));\n  });\n  $('rubNote').classList.toggle('hidden', page !== 'rub');\n  remember('tiendien_page', page);\n  restorePage();\n  applyFxToPage();\n  renderFxStatus();\n  calculate();\n}\nfunction calculate() {\n  const config = PAGES[page];\n  const capital = capitalNum($('capital').value);\n  let amount = capital;\n  config.rates.forEach((rate, index) => {\n    const quote = rateNum($(`rate${index + 1}`).value, Boolean(rate.vndThousands));\n    amount = amount > 0 && quote > 0 ? (rate.op === 'divide' ? amount / quote : amount * quote) : 0;\n    if (!Number.isFinite(amount)) amount = 0;\n    $(`received${index + 1}`).textContent = formatReceived(amount, rate.receive);\n  });\n  if (!(capital > 0 && amount > 0)) {\n    $('profit').textContent = '—'; $('roi').textContent = '—';\n    $('profit').className = ''; $('roi').className = '';\n  } else {\n    const profit = amount - capital;\n    const roi = profit / capital * 100;\n    if (Number.isFinite(profit) && Number.isFinite(roi)) {\n      $('profit').textContent = money(profit, config.capital);\n      $('roi').textContent = pct(roi);\n      tone($('profit'), profit); tone($('roi'), profit);\n    } else {\n      $('profit').textContent = '—'; $('roi').textContent = '—';\n      $('profit').className = ''; $('roi').className = '';\n    }\n  }\n  save();\n}\n\n$('capital').addEventListener('input', () => { formatCapital(); calculate(); });\n['rate1', 'rate2', 'rate3'].forEach(id => $(id).addEventListener('input', calculate));\ndocument.querySelectorAll('.tab').forEach(button => button.addEventListener('click', () => {\n  save(); page = button.dataset.page; renderPage(); refreshFx();\n}));\n$('fxAuto').addEventListener('click', () => {\n  save();\n  fxEnabled = !fxEnabled;\n  remember(FX_AUTO_KEY, fxEnabled ? '1' : '0');\n  if (fxEnabled) applyFxToPage();\n  else {\n    PAGES[page].rates.forEach((rate, index) => {\n      if (!rate.fx) return;\n      const manual = stored(key(`rate${index + 1}`));\n      if (manual !== null) $(`rate${index + 1}`).value = manual;\n      delete $(`rate${index + 1}`).dataset.fxSource;\n    });\n  }\n  renderFxStatus(); calculate();\n  if (fxEnabled) refreshFx();\n});\n$('fxRefresh').addEventListener('click', () => refreshFx({force: true}));\nwindow.addEventListener('online', () => refreshFx());\ndocument.addEventListener('visibilitychange', () => { if (!document.hidden) refreshFx(); });\nsetInterval(() => { if (!document.hidden) refreshFx(); }, 60000);\n\nlet deferredPrompt = null;\nwindow.addEventListener('beforeinstallprompt', event => {\n  event.preventDefault(); deferredPrompt = event; $('installBtn').classList.remove('hidden');\n});\n$('installBtn').addEventListener('click', async () => {\n  if (!deferredPrompt) return;\n  deferredPrompt.prompt(); await deferredPrompt.userChoice;\n  deferredPrompt = null; $('installBtn').classList.add('hidden');\n});\n\n// Retire this app's old cache without touching other apps on the same origin.\n(async () => {\n  try {\n    if ('serviceWorker' in navigator) {\n      const scope = new URL('./', location.href).href;\n      const registrations = await navigator.serviceWorker.getRegistrations();\n      for (const registration of registrations) if (registration.scope === scope) await registration.unregister();\n    }\n    if ('caches' in window) {\n      for (const name of await caches.keys()) if (/^(tien-cua-dien|tiendien)[-_]/.test(name)) await caches.delete(name);\n    }\n  } catch (_) {}\n})();\nrenderPage();\nrefreshFx();\n\n</script>\n</body>\n</html>\n"},"/styles.css":{"type":"text/css; charset=utf-8","body":":root{--bg:#090b0c;--panel:#121517;--field:#0c0f11;--line:#252b2f;--text:#f4f7f8;--muted:#899197;--accent:#00e68a;--bad:#ff6670;--warn:#f2c14e}\n*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;background:var(--bg);overflow:auto}body{font-family:Inter,ui-sans-serif,system-ui,-apple-system,\"Segoe UI\",sans-serif;color:var(--text)}button,input{font:inherit}.app{height:100dvh;min-height:530px;max-width:620px;margin:0 auto;padding:max(12px,env(safe-area-inset-top)) 14px max(12px,env(safe-area-inset-bottom));display:grid;grid-template-rows:auto auto auto minmax(115px,1fr);gap:10px;background:radial-gradient(circle at 90% -10%,rgba(0,230,138,.12),transparent 36%)}header{display:flex;justify-content:space-between;align-items:center;gap:12px}.route{font-size:11px;font-weight:800;letter-spacing:.06em;color:var(--accent)}h1{margin:2px 0 0;font-size:27px;line-height:1;letter-spacing:-.045em}.version{display:inline-block;margin-top:5px;font-size:9px;font-weight:900;letter-spacing:.08em;color:var(--accent);opacity:.8}.install{border:1px solid var(--line);background:var(--panel);color:var(--accent);font-size:11px;font-weight:850;padding:8px 11px;border-radius:10px;cursor:pointer}.hidden{display:none!important}.tabs{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:7px}.tab{height:34px;border:1px solid var(--line);border-radius:10px;background:#101315;color:var(--muted);font-size:12px;font-weight:900;letter-spacing:.04em;cursor:pointer}.tab.active{color:#07110d;background:var(--accent);border-color:var(--accent)}.panel{border:1px solid var(--line);background:linear-gradient(180deg,#15191b,var(--panel));border-radius:17px;padding:12px}.inputs{display:grid;grid-template-columns:1fr 1fr;gap:10px}.inputs label.wide{grid-column:1/-1}.inputs label>span{display:flex;justify-content:space-between;align-items:center;gap:6px;font-size:11px;font-weight:780;color:#c7cdd0;margin:0 2px 5px}.inputs small{font-size:8px;color:var(--muted);font-weight:900;letter-spacing:.07em}.field{height:45px;display:flex;align-items:center;border:1px solid var(--line);background:var(--field);border-radius:12px;overflow:hidden}.field:focus-within{border-color:var(--accent);box-shadow:0 0 0 2px rgba(0,230,138,.08)}.field.rate-highlight{background:linear-gradient(180deg,rgba(0,230,138,.18),rgba(0,230,138,.08));border-color:rgba(0,230,138,.62);box-shadow:inset 0 0 0 1px rgba(0,230,138,.06)}.field.rate-highlight input{color:#f7fffb}.field.rate-highlight b{color:var(--accent)}.field input{width:100%;min-width:0;height:100%;border:0;outline:0;background:transparent;color:var(--text);padding:0 11px;font-size:16px;font-weight:800}.field input::placeholder{color:#535b60;font-size:12px;font-weight:650}.field b{font-size:9px;color:var(--muted);padding:0 10px}.received{display:block;margin:5px 3px 0;color:var(--muted);font-size:10px;line-height:1.15;font-style:normal;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.result-card{min-height:0;border:1px solid #284439;background:linear-gradient(180deg,#142119,#101613);border-radius:18px;padding:14px;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center}.result-card span{font-size:10px;color:var(--muted);font-weight:900;letter-spacing:.12em}.result-card strong{font-size:clamp(30px,8vw,46px);line-height:1.03;margin:8px 0 4px;letter-spacing:-.055em}.result-card b{font-size:16px}.good{color:var(--accent)!important}.bad{color:var(--bad)!important}.neutral{color:var(--warn)!important}\n@media(max-width:390px){.app{padding-left:10px;padding-right:10px;gap:8px}.panel{padding:10px}.inputs{gap:8px}.field{height:41px}.field input{font-size:14px}h1{font-size:23px}.received{font-size:9px;margin-top:4px}.result-card{padding:11px}.result-card strong{font-size:29px}.tab{height:31px;font-size:11px}}\n@media(max-height:690px){.app{gap:7px;padding-top:7px;padding-bottom:7px}.route{font-size:9px}h1{font-size:20px}.tabs{gap:5px}.tab{height:28px;font-size:10px}.panel{padding:8px}.inputs{gap:6px}.inputs label>span{font-size:9px;margin-bottom:3px}.field{height:33px}.field input{font-size:13px}.received{font-size:8px;margin-top:3px}.result-card{padding:8px}.result-card strong{font-size:26px;margin:4px 0 2px}}\n.fx-tools{grid-column:1/-1;border-top:1px solid var(--line);padding-top:9px;min-width:0}\n.fx-controls{display:flex;align-items:center;justify-content:space-between;gap:8px}\n.fx-toggle,.fx-refresh{min-height:32px;border:1px solid var(--line);border-radius:9px;background:var(--field);color:var(--muted);padding:5px 10px;font-size:11px;font-weight:800;cursor:pointer}\n.fx-toggle{display:inline-flex;align-items:center;gap:7px}\n.fx-toggle.enabled{color:var(--accent);border-color:#285d46;background:#11251c}\n.fx-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:currentColor}\n.fx-refresh{color:var(--text)}.fx-refresh:disabled{opacity:.45;cursor:default}\n.fx-tools p{margin:5px 0 0;font-size:9px;line-height:1.4;color:var(--muted);overflow-wrap:anywhere}\n.fx-tools a{color:var(--muted);text-underline-offset:2px}\n.fx-tools .fx-warning{color:var(--warn)}\n.field.auto-rate{border-style:dashed}.field.auto-rate input{cursor:default}\n.rub-note{grid-column:1/-1;margin:0 2px;color:var(--warn);font-size:10px;line-height:1.35}\n.result-note{margin:8px 0 0;font-size:9px;line-height:1.4;color:var(--muted);font-weight:500;letter-spacing:0}\n.usd-reference{display:block;margin:4px 3px 0;font-size:10px;line-height:1.35;font-style:normal;font-weight:650;color:#73c6a3;overflow-wrap:anywhere}\n.usd-reference.stale{color:var(--warn)}\nbutton:focus-visible{outline:2px solid var(--accent);outline-offset:3px}\n@media(max-width:390px){.tabs{gap:5px}.fx-toggle,.fx-refresh{font-size:10px;padding:5px 8px}}\n@media(max-height:690px){.fx-tools{padding-top:6px}.fx-tools p{font-size:8px;margin-top:3px}.fx-toggle,.fx-refresh{min-height:28px;font-size:10px}.rub-note{font-size:9px}.result-note{font-size:8px;margin-top:5px}.usd-reference{font-size:9px;margin-top:3px}}\n\n"},"/app.js":{"type":"application/javascript; charset=utf-8","body":"'use strict';\nconst $ = id => document.getElementById(id);\nconst fmt0 = new Intl.NumberFormat('vi-VN', {maximumFractionDigits: 0});\nconst fmt2 = new Intl.NumberFormat('vi-VN', {maximumFractionDigits: 2});\nconst fmt4 = new Intl.NumberFormat('vi-VN', {maximumFractionDigits: 4});\nconst fmtRate = new Intl.NumberFormat('vi-VN', {useGrouping: false, maximumFractionDigits: 6});\nconst memoryStorage = new Map();\nfunction stored(name) {\n  try { return localStorage.getItem(name) ?? memoryStorage.get(name) ?? null; }\n  catch (_) { return memoryStorage.get(name) ?? null; }\n}\nfunction remember(name, value) {\n  memoryStorage.set(name, String(value));\n  try { localStorage.setItem(name, String(value)); } catch (_) {}\n}\n\n// A/B always means the amount of B for ONE unit of A.\n// Only explicit fiat pairs have an fx property. USDT is never fetched or\n// inferred from the provider's USD rate, except the disclosed RUB convention.\nconst PAGES = {\n  cad: {\n    route: 'CAD → EUR → USDT → CAD', capital: 'CAD', highlight: 0,\n    rates: [\n      {label: 'EUR / CAD', unit: 'CAD', placeholder: 'Ví dụ 1,5500', receive: 'EUR', op: 'divide', fx: ['EUR', 'CAD']},\n      {label: 'USDT / EUR', tag: 'P2P', unit: 'EUR', placeholder: 'Ví dụ 0,8900', receive: 'USDT', op: 'divide'},\n      {label: 'USDT / CAD', tag: 'P2P', unit: 'CAD', placeholder: 'Ví dụ 1,3900', receive: 'CAD', op: 'multiply'}\n    ]\n  },\n  try: {\n    route: 'TRY → EUR → USDT → TRY', capital: 'TRY', highlight: 3,\n    rates: [\n      {label: 'EUR / TRY', unit: 'TRY', placeholder: 'Ví dụ 48,50', receive: 'EUR', op: 'divide', fx: ['EUR', 'TRY']},\n      {label: 'USDT / EUR', tag: 'P2P', unit: 'EUR', placeholder: 'Ví dụ 0,8550', receive: 'USDT', op: 'divide'},\n      {label: 'USDT / TRY', tag: 'P2P', unit: 'TRY', placeholder: 'Ví dụ 41,50', receive: 'TRY', op: 'multiply'}\n    ]\n  },\n  vnd: {\n    route: 'VND → USDT → EUR → VND', capital: 'VND', highlight: 1,\n    rates: [\n      {label: 'USDT / VND', tag: 'P2P', unit: 'VND', placeholder: 'Ví dụ 26.300', receive: 'USDT', op: 'divide', vndThousands: true},\n      {label: 'USDT / EUR', tag: 'P2P', unit: 'EUR', placeholder: 'Ví dụ 0,8600', receive: 'EUR', op: 'multiply'},\n      {label: 'EUR / VND', unit: 'VND', placeholder: 'Ví dụ 30.700', receive: 'VND', op: 'multiply', vndThousands: true, fx: ['EUR', 'VND']}\n    ]\n  },\n  jpy: {\n    route: 'VND → JPY → USDT → VND', capital: 'VND', highlight: 2,\n    rates: [\n      {label: 'JPY / VND', unit: 'VND', placeholder: 'Ví dụ 165,50', receive: 'JPY', op: 'divide', fx: ['JPY', 'VND']},\n      {label: 'USDT / JPY', tag: 'P2P', unit: 'JPY', placeholder: 'Ví dụ 155,00', receive: 'USDT', op: 'divide'},\n      {label: 'USDT / VND', tag: 'P2P', unit: 'VND', placeholder: 'Ví dụ 26.300', receive: 'VND', op: 'multiply', vndThousands: true}\n    ]\n  },\n  rub: {\n    route: 'VND → RUB → USDT → VND', capital: 'VND', highlight: 3,\n    rates: [\n      {label: 'RUB / VND', unit: 'VND', placeholder: 'Ví dụ 310,50', receive: 'RUB', op: 'divide', fx: ['RUB', 'VND']},\n      {label: 'USD / RUB', unit: 'RUB', placeholder: 'Ví dụ 83,50', receive: 'USDT', op: 'divide', fx: ['USD', 'RUB']},\n      {label: 'USDT / VND', tag: 'P2P', unit: 'VND', placeholder: 'Ví dụ 26.300', receive: 'VND', op: 'multiply', vndThousands: true}\n    ]\n  }\n};\n\nfunction migrateVndTab() {\n  const legacy = {capital: 'tiendien_capitalVnd', rate1: 'tiendien_usdtVnd', rate2: 'tiendien_usdtEur', rate3: 'tiendien_eurVnd'};\n  for (const id of ['capital', 'rate1', 'rate2', 'rate3']) {\n    const target = `tiendien_vnd_${id}`;\n    const value = stored(`tiendien_eur_${id}`) ?? stored(legacy[id]);\n    if (stored(target) === null && value !== null) remember(target, value);\n  }\n}\nmigrateVndTab();\n// CAD now has a different starting currency and different quote positions.\n// Keep its new inputs separate so VND capital / unrelated old quotes cannot\n// acquire a new currency label. Only the unchanged USDT/CAD quote migrates.\nconst oldUsdtCad = stored('tiendien_cad_rate2');\nif (stored('tiendien_cad_eur_usdt_rate3') === null && oldUsdtCad !== null) {\n  remember('tiendien_cad_eur_usdt_rate3', oldUsdtCad);\n}\nlet page = stored('tiendien_page');\nif (page === 'eur' || !PAGES[page]) page = 'vnd';\n\nfunction capitalNum(value) {\n  const number = Number(String(value ?? '').replace(/\\D/g, ''));\n  return Number.isFinite(number) ? number : 0;\n}\nfunction rateNum(value, thousands = false) {\n  let text = String(value ?? '').trim().replace(/\\s/g, '');\n  if (!text) return 0;\n  if (text.includes(',')) text = text.replace(/\\./g, '').replace(',', '.');\n  else if (thousands && /^\\d{1,3}(?:\\.\\d{3})+$/.test(text)) text = text.replace(/\\./g, '');\n  const number = Number(text);\n  return Number.isFinite(number) ? number : 0;\n}\nfunction formatCapital() {\n  const digits = $('capital').value.replace(/\\D/g, '');\n  $('capital').value = digits ? fmt0.format(capitalNum(digits)) : '';\n}\nfunction money(value, unit) { return `${value >= 0 ? '+' : '−'}${(unit === 'CAD' ? fmt2 : fmt0).format(Math.abs(value))} ${unit}`; }\nfunction pct(value) { return `${value >= 0 ? '+' : ''}${fmt2.format(value)}%`; }\nfunction tone(element, value) {\n  element.classList.remove('good', 'bad', 'neutral');\n  element.classList.add(value > 0.01 ? 'good' : value < -0.01 ? 'bad' : 'neutral');\n}\nfunction formatReceived(value, unit) {\n  if (!(value > 0 && Number.isFinite(value))) return `Nhận: — ${unit}`;\n  return `Nhận: ${(unit === 'VND' || unit === 'TRY' ? fmt2 : fmt4).format(value)} ${unit}`;\n}\nfunction key(name) { return `tiendien_${page === 'cad' ? 'cad_eur_usdt' : page}_${name}`; }\nfunction save() {\n  remember(key('capital'), $('capital').value);\n  PAGES[page].rates.forEach((rate, index) => {\n    // Keep the last manually entered fiat quote separate from the live cache.\n    if (!fxEnabled || !rate.fx) remember(key(`rate${index + 1}`), $(`rate${index + 1}`).value);\n  });\n}\n\nconst FX_URL = 'https://open.er-api.com/v6/latest/USD';\nconst FX_CACHE_KEY = 'tiendien_fx_usd_v16';\nconst FX_AUTO_KEY = 'tiendien_fx_auto_v16';\nconst FX_ATTEMPT_KEY = 'tiendien_fx_attempt_v16';\nconst FX_CODES = ['USD', 'EUR', 'CAD', 'TRY', 'JPY', 'VND', 'RUB'];\nlet fxEnabled = stored(FX_AUTO_KEY) !== '0';\nlet fxError = '';\nlet fxBusy = false;\nlet fxRequest = null;\nlet fxLastAttempt = Number(stored(FX_ATTEMPT_KEY)) || 0;\n\nfunction validateFx(payload) {\n  if (!payload || payload.result !== 'success' || payload.base_code !== 'USD' || !payload.rates) throw new Error('Invalid FX data');\n  for (const code of FX_CODES) {\n    const rate = payload.rates[code];\n    if (typeof rate !== 'number' || !Number.isFinite(rate) || rate <= 0) throw new Error('Invalid FX rate');\n  }\n  if (Math.abs(payload.rates.USD - 1) > 0.000001) throw new Error('Invalid FX base');\n  const last = payload.time_last_update_unix;\n  const next = payload.time_next_update_unix;\n  if (!Number.isFinite(last) || !Number.isFinite(next) || last <= 0 || next <= last || last * 1000 > Date.now() + 300000) throw new Error('Invalid FX timestamp');\n  return payload;\n}\nfunction readFxCache() {\n  try {\n    const cached = JSON.parse(stored(FX_CACHE_KEY) || 'null');\n    if (!cached || !Number.isFinite(cached.fetchedAt) || cached.fetchedAt <= 0 || cached.fetchedAt > Date.now() + 300000) return null;\n    validateFx(cached.payload);\n    return cached;\n  } catch (_) { return null; }\n}\nlet fxSnapshot = readFxCache();\nfunction fxIsDue() {\n  return !fxSnapshot || Date.now() >= fxSnapshot.payload.time_next_update_unix * 1000 + 60000;\n}\nfunction crossRate(base, quote) {\n  if (!fxSnapshot) return 0;\n  return fxSnapshot.payload.rates[quote] / fxSnapshot.payload.rates[base];\n}\nfunction renderUsdReferences() {\n  // Benchmarks are read-only display data. Never substitute them for P2P\n  // USDT inputs or use them in the route's received/profit calculations.\n  PAGES[page].rates.forEach((rate, index) => {\n    const reference = $(`usdReference${index + 1}`);\n    const pair = rate.label.split('/').map(code => code.trim());\n    const hasUsdt = pair.includes('USDT');\n    reference.classList.toggle('hidden', !hasUsdt);\n    reference.classList.toggle('stale', hasUsdt && Boolean(fxSnapshot) && (fxIsDue() || Boolean(fxError)));\n    if (!hasUsdt) {\n      reference.textContent = '';\n      reference.setAttribute('title', '');\n      return;\n    }\n    const currency = pair.find(code => code !== 'USDT');\n    const label = `USD / ${currency}`;\n    if (fxSnapshot) {\n      const value = crossRate('USD', currency);\n      const qualifier = fxError ? ' · giá lưu' : fxIsDue() ? ' · giá cũ' : '';\n      reference.textContent = `${label}: ${fmt4.format(value)}${qualifier}`;\n      const timestamp = new Date(fxSnapshot.payload.time_last_update_unix * 1000).toLocaleString('vi-VN', {timeZone: 'Asia/Ho_Chi_Minh'});\n      reference.setAttribute('title', `1 USD = ${fmt4.format(value)} ${currency}. Tỷ giá tham khảo từ ExchangeRate-API, lúc ${timestamp} (giờ VN).`);\n    } else {\n      reference.textContent = `${label}: ${fxBusy ? 'đang tải…' : fxError ? 'chưa tải được' : '—'}`;\n      reference.setAttribute('title', 'Chưa có dữ liệu tỷ giá pháp định; không suy ra từ giá USDT nhập tay.');\n    }\n  });\n}\nfunction applyFxToPage() {\n  if (!fxEnabled || !fxSnapshot) return;\n  PAGES[page].rates.forEach((rate, index) => {\n    if (!rate.fx) return;\n    const value = crossRate(...rate.fx);\n    const input = $(`rate${index + 1}`);\n    input.value = fmtRate.format(value);\n    input.dataset.fxSource = 'api';\n  });\n}\nfunction renderFxStatus() {\n  $('fxAuto').setAttribute('aria-checked', String(fxEnabled));\n  $('fxAuto').classList.toggle('enabled', fxEnabled);\n  $('fxAutoText').textContent = `Tự điền: ${fxEnabled ? 'Bật' : 'Tắt'}`;\n  $('fxRefresh').disabled = fxBusy;\n  $('fxRefresh').textContent = fxBusy ? 'Đang tải…' : 'Cập nhật';\n  $('fxStatus').classList.toggle('fx-warning', Boolean(fxError) || (fxIsDue() && Boolean(fxSnapshot)));\n  const manualPrefix = fxEnabled ? '' : 'Ô giá nhập tay. ';\n  if (fxSnapshot) {\n    const date = new Intl.DateTimeFormat('vi-VN', {dateStyle: 'short', timeStyle: 'short', timeZone: 'Asia/Ho_Chi_Minh'}).format(new Date(fxSnapshot.payload.time_last_update_unix * 1000));\n    const prefix = fxError ? `${fxError} · đang dùng giá lưu lúc ` : fxIsDue() ? 'Giá cũ từ ' : 'Tỷ giá lúc ';\n    $('fxStatus').textContent = `${manualPrefix}${prefix}${date} (giờ VN). USDT nhập tay.`;\n  } else if (fxError) {\n    $('fxStatus').textContent = `${manualPrefix}${fxError}. ${fxEnabled ? 'Tắt Tự điền để nhập tay.' : 'USD tham khảo chưa có dữ liệu.'}`;\n  } else {\n    $('fxStatus').textContent = manualPrefix + (fxBusy ? 'Đang lấy tỷ giá pháp định… USDT nhập tay.' : 'Chưa có tỷ giá tự động. USDT nhập tay.');\n  }\n  PAGES[page].rates.forEach((rate, index) => {\n    const input = $(`rate${index + 1}`);\n    const automatic = Boolean(rate.fx && fxEnabled);\n    input.readOnly = automatic;\n    input.setAttribute('aria-readonly', String(automatic));\n    const tag = rate.fx ? (automatic ? (fxSnapshot ? 'TỰ ĐỘNG' : input.value ? 'ĐÃ LƯU' : 'CHỜ GIÁ') : 'NHẬP TAY') : rate.tag;\n    $(`rate${index + 1}Label`).innerHTML = `${rate.label}${tag ? ` <small>${tag}</small>` : ''}`;\n    input.closest('.field').classList.toggle('auto-rate', automatic);\n  });\n  $('resultNote').textContent = fxEnabled ? 'Ước tính theo tỷ giá tham khảo · chưa trừ phí' : 'Ước tính · chưa trừ phí giao dịch';\n  renderUsdReferences();\n}\n\nasync function refreshFx({force = false} = {}) {\n  // The feed also powers USD reference lines while auto-fill is disabled.\n  if (fxRequest) return fxRequest;\n  if (!force && !fxIsDue()) { renderFxStatus(); return; }\n  const elapsed = Date.now() - fxLastAttempt;\n  // One scheduled attempt every five minutes when offline/unavailable; manual\n  // refresh is limited to once a minute. A fresh daily snapshot needs no poll.\n  if (elapsed >= 0 && elapsed < (force ? 60000 : 300000)) { renderFxStatus(); return; }\n  fxLastAttempt = Date.now();\n  remember(FX_ATTEMPT_KEY, fxLastAttempt);\n  fxBusy = true;\n  renderFxStatus();\n  fxRequest = (async () => {\n    const controller = new AbortController();\n    const timeout = setTimeout(() => controller.abort(), 10000);\n    try {\n      const response = await fetch(FX_URL, {cache: 'no-store', credentials: 'omit', signal: controller.signal});\n      if (!response.ok) throw new Error(response.status === 429 ? 'RATE_LIMIT' : 'FETCH_FAILED');\n      const payload = validateFx(await response.json());\n      if (fxSnapshot && payload.time_last_update_unix < fxSnapshot.payload.time_last_update_unix) throw new Error('Older FX response');\n      fxSnapshot = {payload, fetchedAt: Date.now()};\n      remember(FX_CACHE_KEY, JSON.stringify(fxSnapshot));\n      fxError = '';\n      // The user may have switched tabs or disabled auto while fetch awaited.\n      if (fxEnabled) { applyFxToPage(); calculate(); }\n    } catch (error) {\n      fxError = error.message === 'RATE_LIMIT' ? 'Nguồn đang giới hạn truy cập' : 'Không tải được tỷ giá';\n    } finally {\n      clearTimeout(timeout);\n      fxBusy = false;\n      fxRequest = null;\n      renderFxStatus();\n    }\n  })();\n  return fxRequest;\n}\n\nfunction restorePage() {\n  $('capital').value = stored(key('capital')) ?? (page === 'cad' ? '10.000' : page === 'try' ? '100.000' : '100.000.000');\n  ['rate1', 'rate2', 'rate3'].forEach(id => {\n    $(id).value = stored(key(id)) ?? '';\n    delete $(id).dataset.fxSource;\n  });\n  formatCapital();\n}\nfunction renderPage() {\n  const config = PAGES[page];\n  $('routeText').textContent = config.route;\n  $('capitalUnit').textContent = config.capital;\n  config.rates.forEach((rate, index) => {\n    const input = $(`rate${index + 1}`);\n    $(`rate${index + 1}Unit`).textContent = rate.unit;\n    input.placeholder = rate.placeholder;\n    input.setAttribute('aria-label', `${rate.label}: số ${rate.unit} cho một ${rate.label.split(' / ')[0]}`);\n    input.closest('.field').classList.toggle('rate-highlight', index + 1 === config.highlight);\n  });\n  document.querySelectorAll('.tab').forEach(button => {\n    const active = button.dataset.page === page;\n    button.classList.toggle('active', active);\n    button.setAttribute('aria-pressed', String(active));\n  });\n  $('rubNote').classList.toggle('hidden', page !== 'rub');\n  remember('tiendien_page', page);\n  restorePage();\n  applyFxToPage();\n  renderFxStatus();\n  calculate();\n}\nfunction calculate() {\n  const config = PAGES[page];\n  const capital = capitalNum($('capital').value);\n  let amount = capital;\n  config.rates.forEach((rate, index) => {\n    const quote = rateNum($(`rate${index + 1}`).value, Boolean(rate.vndThousands));\n    amount = amount > 0 && quote > 0 ? (rate.op === 'divide' ? amount / quote : amount * quote) : 0;\n    if (!Number.isFinite(amount)) amount = 0;\n    $(`received${index + 1}`).textContent = formatReceived(amount, rate.receive);\n  });\n  if (!(capital > 0 && amount > 0)) {\n    $('profit').textContent = '—'; $('roi').textContent = '—';\n    $('profit').className = ''; $('roi').className = '';\n  } else {\n    const profit = amount - capital;\n    const roi = profit / capital * 100;\n    if (Number.isFinite(profit) && Number.isFinite(roi)) {\n      $('profit').textContent = money(profit, config.capital);\n      $('roi').textContent = pct(roi);\n      tone($('profit'), profit); tone($('roi'), profit);\n    } else {\n      $('profit').textContent = '—'; $('roi').textContent = '—';\n      $('profit').className = ''; $('roi').className = '';\n    }\n  }\n  save();\n}\n\n$('capital').addEventListener('input', () => { formatCapital(); calculate(); });\n['rate1', 'rate2', 'rate3'].forEach(id => $(id).addEventListener('input', calculate));\ndocument.querySelectorAll('.tab').forEach(button => button.addEventListener('click', () => {\n  save(); page = button.dataset.page; renderPage(); refreshFx();\n}));\n$('fxAuto').addEventListener('click', () => {\n  save();\n  fxEnabled = !fxEnabled;\n  remember(FX_AUTO_KEY, fxEnabled ? '1' : '0');\n  if (fxEnabled) applyFxToPage();\n  else {\n    PAGES[page].rates.forEach((rate, index) => {\n      if (!rate.fx) return;\n      const manual = stored(key(`rate${index + 1}`));\n      if (manual !== null) $(`rate${index + 1}`).value = manual;\n      delete $(`rate${index + 1}`).dataset.fxSource;\n    });\n  }\n  renderFxStatus(); calculate();\n  if (fxEnabled) refreshFx();\n});\n$('fxRefresh').addEventListener('click', () => refreshFx({force: true}));\nwindow.addEventListener('online', () => refreshFx());\ndocument.addEventListener('visibilitychange', () => { if (!document.hidden) refreshFx(); });\nsetInterval(() => { if (!document.hidden) refreshFx(); }, 60000);\n\nlet deferredPrompt = null;\nwindow.addEventListener('beforeinstallprompt', event => {\n  event.preventDefault(); deferredPrompt = event; $('installBtn').classList.remove('hidden');\n});\n$('installBtn').addEventListener('click', async () => {\n  if (!deferredPrompt) return;\n  deferredPrompt.prompt(); await deferredPrompt.userChoice;\n  deferredPrompt = null; $('installBtn').classList.add('hidden');\n});\n\n// Retire this app's old cache without touching other apps on the same origin.\n(async () => {\n  try {\n    if ('serviceWorker' in navigator) {\n      const scope = new URL('./', location.href).href;\n      const registrations = await navigator.serviceWorker.getRegistrations();\n      for (const registration of registrations) if (registration.scope === scope) await registration.unregister();\n    }\n    if ('caches' in window) {\n      for (const name of await caches.keys()) if (/^(tien-cua-dien|tiendien)[-_]/.test(name)) await caches.delete(name);\n    }\n  } catch (_) {}\n})();\nrenderPage();\nrefreshFx();\n"},"/manifest.webmanifest":{"type":"application/manifest+json; charset=utf-8","body":"{\"name\":\"Tiền của Điền\",\"short_name\":\"Tiền của Điền\",\"description\":\"Tính vòng CAD, TRY, VND, JPY, RUB; tỷ giá USD tham khảo bên dưới các cặp USDT\",\"start_url\":\"./\",\"display\":\"standalone\",\"background_color\":\"#090b0c\",\"theme_color\":\"#090b0c\",\"icons\":[{\"src\":\"./icon.svg\",\"sizes\":\"any\",\"type\":\"image/svg+xml\",\"purpose\":\"any maskable\"}],\"scope\":\"./\"}\n"},"/sw.js":{"type":"application/javascript; charset=utf-8","body":"self.addEventListener('install', () => self.skipWaiting());\nself.addEventListener('activate', event => event.waitUntil((async () => {\n  for (const name of await caches.keys()) if (/^(tien-cua-dien|tiendien)[-_]/.test(name)) await caches.delete(name);\n  await self.registration.unregister();\n})()));\n"},"/icon.svg":{"type":"image/svg+xml; charset=utf-8","body":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 512 512\"><rect width=\"512\" height=\"512\" rx=\"110\" fill=\"#0b0c0e\"/><text x=\"256\" y=\"330\" text-anchor=\"middle\" font-family=\"Arial,sans-serif\" font-size=\"280\" font-weight=\"800\" fill=\"#00e68a\">Đ</text></svg>\n"},"/":{"type":"text/html; charset=utf-8","body":"<!doctype html>\n<html lang=\"vi\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta http-equiv=\"Cache-Control\" content=\"no-cache, no-store, must-revalidate\">\n  <meta http-equiv=\"Pragma\" content=\"no-cache\">\n  <meta http-equiv=\"Expires\" content=\"0\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n  <meta name=\"theme-color\" content=\"#090b0c\">\n  <meta name=\"color-scheme\" content=\"dark\">\n  <title>Tiền của Điền</title>\n  <link rel=\"manifest\" href=\"./manifest.webmanifest?v=18\">\n  <link rel=\"icon\" href=\"./icon.svg\" type=\"image/svg+xml\">\n<style>\n:root{--bg:#090b0c;--panel:#121517;--field:#0c0f11;--line:#252b2f;--text:#f4f7f8;--muted:#899197;--accent:#00e68a;--bad:#ff6670;--warn:#f2c14e}\n*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;background:var(--bg);overflow:auto}body{font-family:Inter,ui-sans-serif,system-ui,-apple-system,\"Segoe UI\",sans-serif;color:var(--text)}button,input{font:inherit}.app{height:100dvh;min-height:530px;max-width:620px;margin:0 auto;padding:max(12px,env(safe-area-inset-top)) 14px max(12px,env(safe-area-inset-bottom));display:grid;grid-template-rows:auto auto auto minmax(115px,1fr);gap:10px;background:radial-gradient(circle at 90% -10%,rgba(0,230,138,.12),transparent 36%)}header{display:flex;justify-content:space-between;align-items:center;gap:12px}.route{font-size:11px;font-weight:800;letter-spacing:.06em;color:var(--accent)}h1{margin:2px 0 0;font-size:27px;line-height:1;letter-spacing:-.045em}.version{display:inline-block;margin-top:5px;font-size:9px;font-weight:900;letter-spacing:.08em;color:var(--accent);opacity:.8}.install{border:1px solid var(--line);background:var(--panel);color:var(--accent);font-size:11px;font-weight:850;padding:8px 11px;border-radius:10px;cursor:pointer}.hidden{display:none!important}.tabs{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:7px}.tab{height:34px;border:1px solid var(--line);border-radius:10px;background:#101315;color:var(--muted);font-size:12px;font-weight:900;letter-spacing:.04em;cursor:pointer}.tab.active{color:#07110d;background:var(--accent);border-color:var(--accent)}.panel{border:1px solid var(--line);background:linear-gradient(180deg,#15191b,var(--panel));border-radius:17px;padding:12px}.inputs{display:grid;grid-template-columns:1fr 1fr;gap:10px}.inputs label.wide{grid-column:1/-1}.inputs label>span{display:flex;justify-content:space-between;align-items:center;gap:6px;font-size:11px;font-weight:780;color:#c7cdd0;margin:0 2px 5px}.inputs small{font-size:8px;color:var(--muted);font-weight:900;letter-spacing:.07em}.field{height:45px;display:flex;align-items:center;border:1px solid var(--line);background:var(--field);border-radius:12px;overflow:hidden}.field:focus-within{border-color:var(--accent);box-shadow:0 0 0 2px rgba(0,230,138,.08)}.field.rate-highlight{background:linear-gradient(180deg,rgba(0,230,138,.18),rgba(0,230,138,.08));border-color:rgba(0,230,138,.62);box-shadow:inset 0 0 0 1px rgba(0,230,138,.06)}.field.rate-highlight input{color:#f7fffb}.field.rate-highlight b{color:var(--accent)}.field input{width:100%;min-width:0;height:100%;border:0;outline:0;background:transparent;color:var(--text);padding:0 11px;font-size:16px;font-weight:800}.field input::placeholder{color:#535b60;font-size:12px;font-weight:650}.field b{font-size:9px;color:var(--muted);padding:0 10px}.received{display:block;margin:5px 3px 0;color:var(--muted);font-size:10px;line-height:1.15;font-style:normal;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.result-card{min-height:0;border:1px solid #284439;background:linear-gradient(180deg,#142119,#101613);border-radius:18px;padding:14px;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center}.result-card span{font-size:10px;color:var(--muted);font-weight:900;letter-spacing:.12em}.result-card strong{font-size:clamp(30px,8vw,46px);line-height:1.03;margin:8px 0 4px;letter-spacing:-.055em}.result-card b{font-size:16px}.good{color:var(--accent)!important}.bad{color:var(--bad)!important}.neutral{color:var(--warn)!important}\n@media(max-width:390px){.app{padding-left:10px;padding-right:10px;gap:8px}.panel{padding:10px}.inputs{gap:8px}.field{height:41px}.field input{font-size:14px}h1{font-size:23px}.received{font-size:9px;margin-top:4px}.result-card{padding:11px}.result-card strong{font-size:29px}.tab{height:31px;font-size:11px}}\n@media(max-height:690px){.app{gap:7px;padding-top:7px;padding-bottom:7px}.route{font-size:9px}h1{font-size:20px}.tabs{gap:5px}.tab{height:28px;font-size:10px}.panel{padding:8px}.inputs{gap:6px}.inputs label>span{font-size:9px;margin-bottom:3px}.field{height:33px}.field input{font-size:13px}.received{font-size:8px;margin-top:3px}.result-card{padding:8px}.result-card strong{font-size:26px;margin:4px 0 2px}}\n.fx-tools{grid-column:1/-1;border-top:1px solid var(--line);padding-top:9px;min-width:0}\n.fx-controls{display:flex;align-items:center;justify-content:space-between;gap:8px}\n.fx-toggle,.fx-refresh{min-height:32px;border:1px solid var(--line);border-radius:9px;background:var(--field);color:var(--muted);padding:5px 10px;font-size:11px;font-weight:800;cursor:pointer}\n.fx-toggle{display:inline-flex;align-items:center;gap:7px}\n.fx-toggle.enabled{color:var(--accent);border-color:#285d46;background:#11251c}\n.fx-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:currentColor}\n.fx-refresh{color:var(--text)}.fx-refresh:disabled{opacity:.45;cursor:default}\n.fx-tools p{margin:5px 0 0;font-size:9px;line-height:1.4;color:var(--muted);overflow-wrap:anywhere}\n.fx-tools a{color:var(--muted);text-underline-offset:2px}\n.fx-tools .fx-warning{color:var(--warn)}\n.field.auto-rate{border-style:dashed}.field.auto-rate input{cursor:default}\n.rub-note{grid-column:1/-1;margin:0 2px;color:var(--warn);font-size:10px;line-height:1.35}\n.result-note{margin:8px 0 0;font-size:9px;line-height:1.4;color:var(--muted);font-weight:500;letter-spacing:0}\n.usd-reference{display:block;margin:4px 3px 0;font-size:10px;line-height:1.35;font-style:normal;font-weight:650;color:#73c6a3;overflow-wrap:anywhere}\n.usd-reference.stale{color:var(--warn)}\nbutton:focus-visible{outline:2px solid var(--accent);outline-offset:3px}\n@media(max-width:390px){.tabs{gap:5px}.fx-toggle,.fx-refresh{font-size:10px;padding:5px 8px}}\n@media(max-height:690px){.fx-tools{padding-top:6px}.fx-tools p{font-size:8px;margin-top:3px}.fx-toggle,.fx-refresh{min-height:28px;font-size:10px}.rub-note{font-size:9px}.result-note{font-size:8px;margin-top:5px}.usd-reference{font-size:9px;margin-top:3px}}\n\n</style>\n</head>\n<body>\n  <main class=\"app\">\n    <header>\n      <div>\n        <div class=\"route\" id=\"routeText\">VND → USDT → EUR → VND</div>\n        <h1>Tiền của Điền</h1><span class=\"version\">v18 · TỶ GIÁ USD THAM KHẢO</span>\n      </div>\n      <button id=\"installBtn\" class=\"install hidden\">Cài app</button>\n    </header>\n\n    <nav class=\"tabs\" aria-label=\"Loại vòng tiền\">\n      <button type=\"button\" class=\"tab\" data-page=\"cad\">CAD</button>\n      <button type=\"button\" class=\"tab\" data-page=\"try\">TRY</button>\n      <button type=\"button\" class=\"tab active\" data-page=\"vnd\">VND</button>\n      <button type=\"button\" class=\"tab\" data-page=\"jpy\">JPY</button>\n      <button type=\"button\" class=\"tab\" data-page=\"rub\">RUB</button>\n    </nav>\n\n    <section class=\"panel inputs\">\n      <label class=\"wide\">\n        <span>Vốn ban đầu</span>\n        <div class=\"field\"><input aria-label=\"Vốn ban đầu\" id=\"capital\" inputmode=\"numeric\" value=\"100.000.000\"><b id=\"capitalUnit\">VND</b></div>\n      </label>\n\n      <label>\n        <span id=\"rate1Label\">USDT / VND <small>P2P</small></span>\n        <div class=\"field\"><input id=\"rate1\" inputmode=\"decimal\" placeholder=\"Ví dụ 26.300\"><b id=\"rate1Unit\">VND</b></div>\n        <em class=\"received\" id=\"received1\">Nhận: — USDT</em>\n        <em class=\"usd-reference hidden\" id=\"usdReference1\" aria-live=\"polite\"></em>\n      </label>\n\n      <label>\n        <span id=\"rate2Label\">USDT / EUR <small>P2P</small></span>\n        <div class=\"field\"><input id=\"rate2\" inputmode=\"decimal\" placeholder=\"Ví dụ 0,8600\"><b id=\"rate2Unit\">EUR</b></div>\n        <em class=\"received\" id=\"received2\">Nhận: — EUR</em>\n        <em class=\"usd-reference hidden\" id=\"usdReference2\" aria-live=\"polite\"></em>\n      </label>\n\n      <label class=\"wide\">\n        <span id=\"rate3Label\">EUR / VND</span>\n        <div class=\"field\"><input id=\"rate3\" inputmode=\"decimal\" placeholder=\"Ví dụ 30.700\"><b id=\"rate3Unit\">VND</b></div>\n        <em class=\"received\" id=\"received3\">Nhận: — VND</em>\n        <em class=\"usd-reference hidden\" id=\"usdReference3\" aria-live=\"polite\"></em>\n      </label>\n\n      <p id=\"rubNote\" class=\"rub-note hidden\">Bước USD/RUB quy ước 1 USDT = 1 USD. Giá mua USDT thực tế có thể khác.</p>\n      <div class=\"fx-tools\">\n        <div class=\"fx-controls\">\n          <button type=\"button\" id=\"fxAuto\" class=\"fx-toggle enabled\" role=\"switch\" aria-checked=\"true\" aria-label=\"Tự động điền các ô tỷ giá pháp định\"><i class=\"fx-dot\" aria-hidden=\"true\"></i><span id=\"fxAutoText\">Tự điền: Bật</span></button>\n          <button type=\"button\" id=\"fxRefresh\" class=\"fx-refresh\">Cập nhật</button>\n        </div>\n        <p id=\"fxStatus\" role=\"status\" aria-live=\"polite\">Đang lấy tỷ giá pháp định…</p>\n        <p><a href=\"https://www.exchangerate-api.com\" target=\"_blank\" rel=\"noopener noreferrer\">Rates By Exchange Rate API</a> · Tham khảo, cập nhật hằng ngày.</p>\n      </div>\n    </section>\n\n    <section class=\"result-card\">\n      <span>LÃI / LỖ</span>\n      <strong id=\"profit\">—</strong>\n      <b id=\"roi\">—</b>\n      <p id=\"resultNote\" class=\"result-note\">Ước tính · chưa trừ phí giao dịch</p>\n    </section>\n  </main>\n\n\n\n<script>\n'use strict';\nconst $ = id => document.getElementById(id);\nconst fmt0 = new Intl.NumberFormat('vi-VN', {maximumFractionDigits: 0});\nconst fmt2 = new Intl.NumberFormat('vi-VN', {maximumFractionDigits: 2});\nconst fmt4 = new Intl.NumberFormat('vi-VN', {maximumFractionDigits: 4});\nconst fmtRate = new Intl.NumberFormat('vi-VN', {useGrouping: false, maximumFractionDigits: 6});\nconst memoryStorage = new Map();\nfunction stored(name) {\n  try { return localStorage.getItem(name) ?? memoryStorage.get(name) ?? null; }\n  catch (_) { return memoryStorage.get(name) ?? null; }\n}\nfunction remember(name, value) {\n  memoryStorage.set(name, String(value));\n  try { localStorage.setItem(name, String(value)); } catch (_) {}\n}\n\n// A/B always means the amount of B for ONE unit of A.\n// Only explicit fiat pairs have an fx property. USDT is never fetched or\n// inferred from the provider's USD rate, except the disclosed RUB convention.\nconst PAGES = {\n  cad: {\n    route: 'CAD → EUR → USDT → CAD', capital: 'CAD', highlight: 0,\n    rates: [\n      {label: 'EUR / CAD', unit: 'CAD', placeholder: 'Ví dụ 1,5500', receive: 'EUR', op: 'divide', fx: ['EUR', 'CAD']},\n      {label: 'USDT / EUR', tag: 'P2P', unit: 'EUR', placeholder: 'Ví dụ 0,8900', receive: 'USDT', op: 'divide'},\n      {label: 'USDT / CAD', tag: 'P2P', unit: 'CAD', placeholder: 'Ví dụ 1,3900', receive: 'CAD', op: 'multiply'}\n    ]\n  },\n  try: {\n    route: 'TRY → EUR → USDT → TRY', capital: 'TRY', highlight: 3,\n    rates: [\n      {label: 'EUR / TRY', unit: 'TRY', placeholder: 'Ví dụ 48,50', receive: 'EUR', op: 'divide', fx: ['EUR', 'TRY']},\n      {label: 'USDT / EUR', tag: 'P2P', unit: 'EUR', placeholder: 'Ví dụ 0,8550', receive: 'USDT', op: 'divide'},\n      {label: 'USDT / TRY', tag: 'P2P', unit: 'TRY', placeholder: 'Ví dụ 41,50', receive: 'TRY', op: 'multiply'}\n    ]\n  },\n  vnd: {\n    route: 'VND → USDT → EUR → VND', capital: 'VND', highlight: 1,\n    rates: [\n      {label: 'USDT / VND', tag: 'P2P', unit: 'VND', placeholder: 'Ví dụ 26.300', receive: 'USDT', op: 'divide', vndThousands: true},\n      {label: 'USDT / EUR', tag: 'P2P', unit: 'EUR', placeholder: 'Ví dụ 0,8600', receive: 'EUR', op: 'multiply'},\n      {label: 'EUR / VND', unit: 'VND', placeholder: 'Ví dụ 30.700', receive: 'VND', op: 'multiply', vndThousands: true, fx: ['EUR', 'VND']}\n    ]\n  },\n  jpy: {\n    route: 'VND → JPY → USDT → VND', capital: 'VND', highlight: 2,\n    rates: [\n      {label: 'JPY / VND', unit: 'VND', placeholder: 'Ví dụ 165,50', receive: 'JPY', op: 'divide', fx: ['JPY', 'VND']},\n      {label: 'USDT / JPY', tag: 'P2P', unit: 'JPY', placeholder: 'Ví dụ 155,00', receive: 'USDT', op: 'divide'},\n      {label: 'USDT / VND', tag: 'P2P', unit: 'VND', placeholder: 'Ví dụ 26.300', receive: 'VND', op: 'multiply', vndThousands: true}\n    ]\n  },\n  rub: {\n    route: 'VND → RUB → USDT → VND', capital: 'VND', highlight: 3,\n    rates: [\n      {label: 'RUB / VND', unit: 'VND', placeholder: 'Ví dụ 310,50', receive: 'RUB', op: 'divide', fx: ['RUB', 'VND']},\n      {label: 'USD / RUB', unit: 'RUB', placeholder: 'Ví dụ 83,50', receive: 'USDT', op: 'divide', fx: ['USD', 'RUB']},\n      {label: 'USDT / VND', tag: 'P2P', unit: 'VND', placeholder: 'Ví dụ 26.300', receive: 'VND', op: 'multiply', vndThousands: true}\n    ]\n  }\n};\n\nfunction migrateVndTab() {\n  const legacy = {capital: 'tiendien_capitalVnd', rate1: 'tiendien_usdtVnd', rate2: 'tiendien_usdtEur', rate3: 'tiendien_eurVnd'};\n  for (const id of ['capital', 'rate1', 'rate2', 'rate3']) {\n    const target = `tiendien_vnd_${id}`;\n    const value = stored(`tiendien_eur_${id}`) ?? stored(legacy[id]);\n    if (stored(target) === null && value !== null) remember(target, value);\n  }\n}\nmigrateVndTab();\n// CAD now has a different starting currency and different quote positions.\n// Keep its new inputs separate so VND capital / unrelated old quotes cannot\n// acquire a new currency label. Only the unchanged USDT/CAD quote migrates.\nconst oldUsdtCad = stored('tiendien_cad_rate2');\nif (stored('tiendien_cad_eur_usdt_rate3') === null && oldUsdtCad !== null) {\n  remember('tiendien_cad_eur_usdt_rate3', oldUsdtCad);\n}\nlet page = stored('tiendien_page');\nif (page === 'eur' || !PAGES[page]) page = 'vnd';\n\nfunction capitalNum(value) {\n  const number = Number(String(value ?? '').replace(/\\D/g, ''));\n  return Number.isFinite(number) ? number : 0;\n}\nfunction rateNum(value, thousands = false) {\n  let text = String(value ?? '').trim().replace(/\\s/g, '');\n  if (!text) return 0;\n  if (text.includes(',')) text = text.replace(/\\./g, '').replace(',', '.');\n  else if (thousands && /^\\d{1,3}(?:\\.\\d{3})+$/.test(text)) text = text.replace(/\\./g, '');\n  const number = Number(text);\n  return Number.isFinite(number) ? number : 0;\n}\nfunction formatCapital() {\n  const digits = $('capital').value.replace(/\\D/g, '');\n  $('capital').value = digits ? fmt0.format(capitalNum(digits)) : '';\n}\nfunction money(value, unit) { return `${value >= 0 ? '+' : '−'}${(unit === 'CAD' ? fmt2 : fmt0).format(Math.abs(value))} ${unit}`; }\nfunction pct(value) { return `${value >= 0 ? '+' : ''}${fmt2.format(value)}%`; }\nfunction tone(element, value) {\n  element.classList.remove('good', 'bad', 'neutral');\n  element.classList.add(value > 0.01 ? 'good' : value < -0.01 ? 'bad' : 'neutral');\n}\nfunction formatReceived(value, unit) {\n  if (!(value > 0 && Number.isFinite(value))) return `Nhận: — ${unit}`;\n  return `Nhận: ${(unit === 'VND' || unit === 'TRY' ? fmt2 : fmt4).format(value)} ${unit}`;\n}\nfunction key(name) { return `tiendien_${page === 'cad' ? 'cad_eur_usdt' : page}_${name}`; }\nfunction save() {\n  remember(key('capital'), $('capital').value);\n  PAGES[page].rates.forEach((rate, index) => {\n    // Keep the last manually entered fiat quote separate from the live cache.\n    if (!fxEnabled || !rate.fx) remember(key(`rate${index + 1}`), $(`rate${index + 1}`).value);\n  });\n}\n\nconst FX_URL = 'https://open.er-api.com/v6/latest/USD';\nconst FX_CACHE_KEY = 'tiendien_fx_usd_v16';\nconst FX_AUTO_KEY = 'tiendien_fx_auto_v16';\nconst FX_ATTEMPT_KEY = 'tiendien_fx_attempt_v16';\nconst FX_CODES = ['USD', 'EUR', 'CAD', 'TRY', 'JPY', 'VND', 'RUB'];\nlet fxEnabled = stored(FX_AUTO_KEY) !== '0';\nlet fxError = '';\nlet fxBusy = false;\nlet fxRequest = null;\nlet fxLastAttempt = Number(stored(FX_ATTEMPT_KEY)) || 0;\n\nfunction validateFx(payload) {\n  if (!payload || payload.result !== 'success' || payload.base_code !== 'USD' || !payload.rates) throw new Error('Invalid FX data');\n  for (const code of FX_CODES) {\n    const rate = payload.rates[code];\n    if (typeof rate !== 'number' || !Number.isFinite(rate) || rate <= 0) throw new Error('Invalid FX rate');\n  }\n  if (Math.abs(payload.rates.USD - 1) > 0.000001) throw new Error('Invalid FX base');\n  const last = payload.time_last_update_unix;\n  const next = payload.time_next_update_unix;\n  if (!Number.isFinite(last) || !Number.isFinite(next) || last <= 0 || next <= last || last * 1000 > Date.now() + 300000) throw new Error('Invalid FX timestamp');\n  return payload;\n}\nfunction readFxCache() {\n  try {\n    const cached = JSON.parse(stored(FX_CACHE_KEY) || 'null');\n    if (!cached || !Number.isFinite(cached.fetchedAt) || cached.fetchedAt <= 0 || cached.fetchedAt > Date.now() + 300000) return null;\n    validateFx(cached.payload);\n    return cached;\n  } catch (_) { return null; }\n}\nlet fxSnapshot = readFxCache();\nfunction fxIsDue() {\n  return !fxSnapshot || Date.now() >= fxSnapshot.payload.time_next_update_unix * 1000 + 60000;\n}\nfunction crossRate(base, quote) {\n  if (!fxSnapshot) return 0;\n  return fxSnapshot.payload.rates[quote] / fxSnapshot.payload.rates[base];\n}\nfunction renderUsdReferences() {\n  // Benchmarks are read-only display data. Never substitute them for P2P\n  // USDT inputs or use them in the route's received/profit calculations.\n  PAGES[page].rates.forEach((rate, index) => {\n    const reference = $(`usdReference${index + 1}`);\n    const pair = rate.label.split('/').map(code => code.trim());\n    const hasUsdt = pair.includes('USDT');\n    reference.classList.toggle('hidden', !hasUsdt);\n    reference.classList.toggle('stale', hasUsdt && Boolean(fxSnapshot) && (fxIsDue() || Boolean(fxError)));\n    if (!hasUsdt) {\n      reference.textContent = '';\n      reference.setAttribute('title', '');\n      return;\n    }\n    const currency = pair.find(code => code !== 'USDT');\n    const label = `USD / ${currency}`;\n    if (fxSnapshot) {\n      const value = crossRate('USD', currency);\n      const qualifier = fxError ? ' · giá lưu' : fxIsDue() ? ' · giá cũ' : '';\n      reference.textContent = `${label}: ${fmt4.format(value)}${qualifier}`;\n      const timestamp = new Date(fxSnapshot.payload.time_last_update_unix * 1000).toLocaleString('vi-VN', {timeZone: 'Asia/Ho_Chi_Minh'});\n      reference.setAttribute('title', `1 USD = ${fmt4.format(value)} ${currency}. Tỷ giá tham khảo từ ExchangeRate-API, lúc ${timestamp} (giờ VN).`);\n    } else {\n      reference.textContent = `${label}: ${fxBusy ? 'đang tải…' : fxError ? 'chưa tải được' : '—'}`;\n      reference.setAttribute('title', 'Chưa có dữ liệu tỷ giá pháp định; không suy ra từ giá USDT nhập tay.');\n    }\n  });\n}\nfunction applyFxToPage() {\n  if (!fxEnabled || !fxSnapshot) return;\n  PAGES[page].rates.forEach((rate, index) => {\n    if (!rate.fx) return;\n    const value = crossRate(...rate.fx);\n    const input = $(`rate${index + 1}`);\n    input.value = fmtRate.format(value);\n    input.dataset.fxSource = 'api';\n  });\n}\nfunction renderFxStatus() {\n  $('fxAuto').setAttribute('aria-checked', String(fxEnabled));\n  $('fxAuto').classList.toggle('enabled', fxEnabled);\n  $('fxAutoText').textContent = `Tự điền: ${fxEnabled ? 'Bật' : 'Tắt'}`;\n  $('fxRefresh').disabled = fxBusy;\n  $('fxRefresh').textContent = fxBusy ? 'Đang tải…' : 'Cập nhật';\n  $('fxStatus').classList.toggle('fx-warning', Boolean(fxError) || (fxIsDue() && Boolean(fxSnapshot)));\n  const manualPrefix = fxEnabled ? '' : 'Ô giá nhập tay. ';\n  if (fxSnapshot) {\n    const date = new Intl.DateTimeFormat('vi-VN', {dateStyle: 'short', timeStyle: 'short', timeZone: 'Asia/Ho_Chi_Minh'}).format(new Date(fxSnapshot.payload.time_last_update_unix * 1000));\n    const prefix = fxError ? `${fxError} · đang dùng giá lưu lúc ` : fxIsDue() ? 'Giá cũ từ ' : 'Tỷ giá lúc ';\n    $('fxStatus').textContent = `${manualPrefix}${prefix}${date} (giờ VN). USDT nhập tay.`;\n  } else if (fxError) {\n    $('fxStatus').textContent = `${manualPrefix}${fxError}. ${fxEnabled ? 'Tắt Tự điền để nhập tay.' : 'USD tham khảo chưa có dữ liệu.'}`;\n  } else {\n    $('fxStatus').textContent = manualPrefix + (fxBusy ? 'Đang lấy tỷ giá pháp định… USDT nhập tay.' : 'Chưa có tỷ giá tự động. USDT nhập tay.');\n  }\n  PAGES[page].rates.forEach((rate, index) => {\n    const input = $(`rate${index + 1}`);\n    const automatic = Boolean(rate.fx && fxEnabled);\n    input.readOnly = automatic;\n    input.setAttribute('aria-readonly', String(automatic));\n    const tag = rate.fx ? (automatic ? (fxSnapshot ? 'TỰ ĐỘNG' : input.value ? 'ĐÃ LƯU' : 'CHỜ GIÁ') : 'NHẬP TAY') : rate.tag;\n    $(`rate${index + 1}Label`).innerHTML = `${rate.label}${tag ? ` <small>${tag}</small>` : ''}`;\n    input.closest('.field').classList.toggle('auto-rate', automatic);\n  });\n  $('resultNote').textContent = fxEnabled ? 'Ước tính theo tỷ giá tham khảo · chưa trừ phí' : 'Ước tính · chưa trừ phí giao dịch';\n  renderUsdReferences();\n}\n\nasync function refreshFx({force = false} = {}) {\n  // The feed also powers USD reference lines while auto-fill is disabled.\n  if (fxRequest) return fxRequest;\n  if (!force && !fxIsDue()) { renderFxStatus(); return; }\n  const elapsed = Date.now() - fxLastAttempt;\n  // One scheduled attempt every five minutes when offline/unavailable; manual\n  // refresh is limited to once a minute. A fresh daily snapshot needs no poll.\n  if (elapsed >= 0 && elapsed < (force ? 60000 : 300000)) { renderFxStatus(); return; }\n  fxLastAttempt = Date.now();\n  remember(FX_ATTEMPT_KEY, fxLastAttempt);\n  fxBusy = true;\n  renderFxStatus();\n  fxRequest = (async () => {\n    const controller = new AbortController();\n    const timeout = setTimeout(() => controller.abort(), 10000);\n    try {\n      const response = await fetch(FX_URL, {cache: 'no-store', credentials: 'omit', signal: controller.signal});\n      if (!response.ok) throw new Error(response.status === 429 ? 'RATE_LIMIT' : 'FETCH_FAILED');\n      const payload = validateFx(await response.json());\n      if (fxSnapshot && payload.time_last_update_unix < fxSnapshot.payload.time_last_update_unix) throw new Error('Older FX response');\n      fxSnapshot = {payload, fetchedAt: Date.now()};\n      remember(FX_CACHE_KEY, JSON.stringify(fxSnapshot));\n      fxError = '';\n      // The user may have switched tabs or disabled auto while fetch awaited.\n      if (fxEnabled) { applyFxToPage(); calculate(); }\n    } catch (error) {\n      fxError = error.message === 'RATE_LIMIT' ? 'Nguồn đang giới hạn truy cập' : 'Không tải được tỷ giá';\n    } finally {\n      clearTimeout(timeout);\n      fxBusy = false;\n      fxRequest = null;\n      renderFxStatus();\n    }\n  })();\n  return fxRequest;\n}\n\nfunction restorePage() {\n  $('capital').value = stored(key('capital')) ?? (page === 'cad' ? '10.000' : page === 'try' ? '100.000' : '100.000.000');\n  ['rate1', 'rate2', 'rate3'].forEach(id => {\n    $(id).value = stored(key(id)) ?? '';\n    delete $(id).dataset.fxSource;\n  });\n  formatCapital();\n}\nfunction renderPage() {\n  const config = PAGES[page];\n  $('routeText').textContent = config.route;\n  $('capitalUnit').textContent = config.capital;\n  config.rates.forEach((rate, index) => {\n    const input = $(`rate${index + 1}`);\n    $(`rate${index + 1}Unit`).textContent = rate.unit;\n    input.placeholder = rate.placeholder;\n    input.setAttribute('aria-label', `${rate.label}: số ${rate.unit} cho một ${rate.label.split(' / ')[0]}`);\n    input.closest('.field').classList.toggle('rate-highlight', index + 1 === config.highlight);\n  });\n  document.querySelectorAll('.tab').forEach(button => {\n    const active = button.dataset.page === page;\n    button.classList.toggle('active', active);\n    button.setAttribute('aria-pressed', String(active));\n  });\n  $('rubNote').classList.toggle('hidden', page !== 'rub');\n  remember('tiendien_page', page);\n  restorePage();\n  applyFxToPage();\n  renderFxStatus();\n  calculate();\n}\nfunction calculate() {\n  const config = PAGES[page];\n  const capital = capitalNum($('capital').value);\n  let amount = capital;\n  config.rates.forEach((rate, index) => {\n    const quote = rateNum($(`rate${index + 1}`).value, Boolean(rate.vndThousands));\n    amount = amount > 0 && quote > 0 ? (rate.op === 'divide' ? amount / quote : amount * quote) : 0;\n    if (!Number.isFinite(amount)) amount = 0;\n    $(`received${index + 1}`).textContent = formatReceived(amount, rate.receive);\n  });\n  if (!(capital > 0 && amount > 0)) {\n    $('profit').textContent = '—'; $('roi').textContent = '—';\n    $('profit').className = ''; $('roi').className = '';\n  } else {\n    const profit = amount - capital;\n    const roi = profit / capital * 100;\n    if (Number.isFinite(profit) && Number.isFinite(roi)) {\n      $('profit').textContent = money(profit, config.capital);\n      $('roi').textContent = pct(roi);\n      tone($('profit'), profit); tone($('roi'), profit);\n    } else {\n      $('profit').textContent = '—'; $('roi').textContent = '—';\n      $('profit').className = ''; $('roi').className = '';\n    }\n  }\n  save();\n}\n\n$('capital').addEventListener('input', () => { formatCapital(); calculate(); });\n['rate1', 'rate2', 'rate3'].forEach(id => $(id).addEventListener('input', calculate));\ndocument.querySelectorAll('.tab').forEach(button => button.addEventListener('click', () => {\n  save(); page = button.dataset.page; renderPage(); refreshFx();\n}));\n$('fxAuto').addEventListener('click', () => {\n  save();\n  fxEnabled = !fxEnabled;\n  remember(FX_AUTO_KEY, fxEnabled ? '1' : '0');\n  if (fxEnabled) applyFxToPage();\n  else {\n    PAGES[page].rates.forEach((rate, index) => {\n      if (!rate.fx) return;\n      const manual = stored(key(`rate${index + 1}`));\n      if (manual !== null) $(`rate${index + 1}`).value = manual;\n      delete $(`rate${index + 1}`).dataset.fxSource;\n    });\n  }\n  renderFxStatus(); calculate();\n  if (fxEnabled) refreshFx();\n});\n$('fxRefresh').addEventListener('click', () => refreshFx({force: true}));\nwindow.addEventListener('online', () => refreshFx());\ndocument.addEventListener('visibilitychange', () => { if (!document.hidden) refreshFx(); });\nsetInterval(() => { if (!document.hidden) refreshFx(); }, 60000);\n\nlet deferredPrompt = null;\nwindow.addEventListener('beforeinstallprompt', event => {\n  event.preventDefault(); deferredPrompt = event; $('installBtn').classList.remove('hidden');\n});\n$('installBtn').addEventListener('click', async () => {\n  if (!deferredPrompt) return;\n  deferredPrompt.prompt(); await deferredPrompt.userChoice;\n  deferredPrompt = null; $('installBtn').classList.add('hidden');\n});\n\n// Retire this app's old cache without touching other apps on the same origin.\n(async () => {\n  try {\n    if ('serviceWorker' in navigator) {\n      const scope = new URL('./', location.href).href;\n      const registrations = await navigator.serviceWorker.getRegistrations();\n      for (const registration of registrations) if (registration.scope === scope) await registration.unregister();\n    }\n    if ('caches' in window) {\n      for (const name of await caches.keys()) if (/^(tien-cua-dien|tiendien)[-_]/.test(name)) await caches.delete(name);\n    }\n  } catch (_) {}\n})();\nrenderPage();\nrefreshFx();\n\n</script>\n</body>\n</html>\n"}};
export default {
  async fetch(request) {
    const url = new URL(request.url);
    const asset = ASSETS[url.pathname] || ASSETS['/'];
    return new Response(request.method === 'HEAD' ? null : asset.body, {headers: {
      'content-type': asset.type,
      'cache-control': 'no-cache, no-store, must-revalidate',
      'x-content-type-options': 'nosniff'
    }});
  }
};
